pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a non-linear penalty
    // for leaving awkward mid-range dead space.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let dead_zone = (pr / cap - 0.5).abs();
    score += 30.0 * dead_zone * dead_zone * cap; // penalize residuals near half capacity

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        // Strong reward if the next item fits snugly too (chained packing).
        score -= 40.0 * (1.0 - slack_after_next / cap);
        // Extra reward for a near-perfect chain (post_residual == next_item_size).
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // This bin would be "closed" for future use; penalize relative to how
        // far the next item misses fitting.
        let miss = (next_item_size - post_residual) as f64;
        score += 10.0 * (miss / cap).min(1.0);
    }

    // Relative-to-mean coupling: placing into a bin with residual far below
    // mean (a tight bin) is good; placing into an above-mean residual bin
    // wastes packing potential.
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: a fresh bin is only attractive when no open
    // bin gives a good fit (post_residual large relative to capacity) or when
    // the item is large and lookahead suggests a fresh bin packs better.
    if bin_residual == bin_capacity {
        let fit_quality = pr / cap; // 1.0 - item_size/cap for a fresh bin
        // Penalize fresh bins mildly by default.
        score += 20.0;
        // But reward a fresh bin when the item is huge (poor fits everywhere)
        // or when the lookahead pair packs cleanly in a fresh bin.
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.7 {
            score -= 30.0 * item_frac;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            let pair = (item_size + next_item_size) as f64 / cap;
            if pair > 0.85 {
                score -= 45.0 * (pair - 0.85) / 0.15;
            }
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If many bins are already open, discourage more.
        score += (open_bins_count as f64).ln().max(0.0) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 30.0;
        } else if post_residual < 35 {
            score += 12.0;
        }
    } else {
        score -= 40.0; // perfect closure is excellent
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item is large relative to the mean residual.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / mean_residual.max(1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0
            - 30.0 * (tightness - 1.0).clamp(0.0, 2.0)
            - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    // Lookahead: if the next item would fit exactly in the post residual,
    // this placement chains nicely.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (subtract).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to leftover after next item.
            let after_next = post_residual - next_item_size;
            score -= 50.0 + after_next as f64 * 0.5;
        } else {
            // Next item cannot fit: penalize dead space that is too small to be useful.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 60.0; // tiny unusable sliver
            } else {
                score += dead * 0.3;
            }
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Relative to mean residual: bins with more free space than average should be
    // used for large items; prefer spreading load.
    let mean = mean_residual;
    if (bin_residual as f64) > mean {
        score -= 20.0;
    } else if (bin_residual as f64) < mean * 0.5 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, or many open bins with small residuals).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let waste_if_open = (bin_capacity - item_size) as f64;
        // Base cost of a fresh bin; offset by pressure when open bins are fragmented.
        score = 150.0 + waste_if_open * 0.5 - pressure * 120.0
            - (open_bins_count as f64) * 2.0
            + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host both current and next item if sizes allow.
            if item_size + next_item_size <= bin_capacity {
                score -= 300.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 25.0; // perfect 2-step chain
        } else {
            score -= 15.0 * (-diff / 20.0).exp();
        }
        // Penalize if next item cannot fit into post_residual (dead-end)
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when no good fit exists
    if bin_residual == bin_capacity {
        score += 18.0;
        // Opening a new bin is attractive if lookahead chains perfectly from full capacity
        if next_item_size > 0 {
            let chain = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() as f64;
            if chain == 0.0 { score -= 30.0; }
        }
    }

    // Early stream: be more selective, later: pack greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by small classes are "reusable".
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // class of residual: exact small remainders are valuable dead space
        let class = if pr <= 10 { 0.0 }
                    else if pr <= 20 { 1.0 }
                    else if pr <= 50 { 2.0 }
                    else { 3.0 };
        score += class * 8.0;

        // modulo arithmetic: residuals that are multiples of common item sizes are reusable
        if pr % 10 == 0 { score -= 10.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 5 == 0 { score -= 3.0; }

        // residual large enough to host typical next item
        if next_item_size > 0 {
            if pr >= next_item_size {
                score -= 12.0;
                // exact divisibility of residual by next item is a harmonic bonus
                if pr % next_item_size == 0 { score -= 15.0; }
            } else {
                score += 6.0;
            }
            // lookahead: next item fits in the new post_residual too
            if post_residual >= next_item_size && post_residual - next_item_size >= 0 {
                let second = post_residual - next_item_size;
                if second % 10 == 0 { score -= 5.0; }
            }
        }
    }

    // last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // penalty for wasting a nearly-empty bin's potential on a tiny item
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness < 0.3 { score += 10.0 * (0.3 - tightness); }

    // new-bin candidate: keep it attractive only when current bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 5.0 * crowd * (0.5 + 0.5 * progress) + mean_residual * 0.3;
    }

    // mild pressure toward filling bins as stream progresses
    score -= 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) super-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // small slivers are nearly worthless; prefer filling exactly
    }

    // Lookahead synergy: bonus if next item fits in the post residual.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 15.0;
        } else {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when mean residual is large.
    score += 0.05 * open_bins_count as f64 + 0.1 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate handling: opening a bin is penalized, but more
    // acceptable early in the stream or when current bins are crowded.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        if mean_residual < 20.0 { score -= 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post-residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Small dead space is nearly useless.
        score += 15.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 25.0 - chain_quality * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item: penalize proportionally.
        let waste = post_residual as f64;
        score += waste * 0.5;
    }

    // Penalize using a nearly-full bin when many alternatives exist.
    let fill_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score += fill_frac * open_bins_count as f64 * 2.0;

    // Global balance: prefer bins whose residual is close to what we leave behind.
    let dev = (mean_residual - post_residual as f64).abs();
    score += dev * 0.1;

    // Time horizon: early in stream, be conservative (favor new bins for large items);
    // late in stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if item_size > 60 && progress < 0.3 && bin_residual == bin_capacity {
        score -= 10.0; // open fresh bins early for big items
    }
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 5.0; // prefer existing bins late
    }

    // New-bin candidate baseline: mild penalty so it's chosen only when it beats real fits,
    // but not so high that we never open bins when needed.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If no open bin fits well (post_residual of new bin vs item), opening is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that nothing else could use (post residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty if we leave awkward large gap.
            let gap = post_residual as f64;
            if gap > next_item_size as f64 * 0.5 && gap < next_item_size as f64 {
                score += 5.0;
            }
        }
    }

    // Prefer bins with residuals below mean (consolidate small spaces).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: make empty bins attractive only when current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (open_bins_count as f64) * mean_residual / bin_capacity as f64;
        // Opening a new bin is favored when many bins are highly fragmented late in stream.
        let pressure = fragmentation * (0.5 + progress);
        score = bin_capacity as f64 - 15.0 * pressure;
        // But discourage opening new bins when a good fit exists elsewhere.
        if fitting_bins_count > 0 && fit_ratio > 0.7 {
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0; // next item needs fresh bin anyway
        }
    }

    // Mild time-horizon term: early on, be slightly greedy toward balance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the NEXT item exactly matches post_residual,
    // this placement chains into a perfect fit -> strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack * 2.0;
        } else {
            // next item cannot use the leftover space: penalize dead space
            // more severely when the leftover is small (unusable) relative to mean
            let waste = next_item_size - post_residual;
            if waste <= 10 {
                score += 60.0;
            } else {
                score += (waste as f64).sqrt() * 8.0;
            }
        }
    }

    // Penalize leaving residual far below mean residual (creating outliers of dead space)
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.5;
    } else {
        score += dev * 0.2; // slightly reward keeping residual above mean
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make empty bins mildly attractive only when the item
    // is large and no good fit exists; otherwise discourage fragmentation.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 50.0;
        } else {
            score += 120.0;
        }
    }

    // Late in the stream, tighten packing (avoid opening bins needlessly)
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits into the post residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly it fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 50.0 + 100.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize dead space left behind.
            let dead = post_residual as f64;
            score += 30.0 + dead;
        }
    }

    // Penalize small unusable residuals (dead space below typical item range).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Reward using bins with large residuals relative to mean (balance bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor filling it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Early in the stream, prefer opening new bins slightly less (keep bins tight later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress;

    // New-bin candidate: mildly penalize so it's chosen only when open bins fit poorly.
