}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it divides into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual fraction of capacity

    // Class A: post_residual in (0, 10] -> dead space, nearly unusable (items >= 10... but sizes can be 1..100).
    if post_residual <= 10 && post_residual > 0 {
        score -= 30.0; // reward filling a bin to near-exactness
    }
    // Class B: small usable remainder (10, 25]
    else if post_residual <= 25 {
        score -= 12.0;
    }
    // Class C: medium remainder (25, 50]
    else if post_residual <= 50 {
        score -= 4.0;
    }
    // Class D: large remainder -> wasteful placement, penalize
    else {
        score += 8.0 * (frac - 0.5);
    }

    // Modulo-10 harmonic granularity: dead space below the smallest item quantum
    let quantum = 10u32.min(bin_capacity);
    let unusable = post_residual % quantum.max(1);
    score += unusable as f64 * 1.5;

    // Lookahead: reward if next item fits exactly into post_residual (perfect chain)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: post residual becomes a waiting buffer
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Brand-new bin candidate: penalize mildly unless current bins are tight
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 20.0 - 30.0 * pressure.min(1.0);
    }

    // Prefer bins whose residual deviates from mean (specialization of bin classes)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Late-stream consolidation: prefer tighter fits as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let min_useful = 10u32; // smallest plausible item footprint
        if post_residual < min_useful {
            // Complete dead space: nothing can ever fit here.
            score += 200.0;
        } else {
            // Non-linear dead-space penalty: gaps just below typical item
            // sizes are "almost dead" and waste capacity disproportionately.
            let gap = post_residual as f64;
            let dead_zone = (gap < 20.0) as f64 * 60.0
                + (gap < 30.0) as f64 * 30.0
                + (gap < 40.0) as f64 * 12.0;
            score += dead_zone;
            // Superlinear penalty on small gaps generally.
            score += 500.0 / (gap * gap);
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 150.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    // (chaining placements keeps bins tight); otherwise penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize placements that leave many bins open with
    // scattered residual; encourage consolidation into few bins.
    let pressure = open_bins_count as f64;
    score += pressure * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for fuller bins relative to fleet average.
    if (bin_residual as f64) > mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: only attractive when all open bins would be left
    // with near-dead residuals or none fit; empty bin starts clean but
    // carries a fixed opening cost.
    if bin_residual == bin_capacity {
        score += 30.0 + pressure * 1.5;
        // Late in the stream, opening new bins is fine (fewer future items
        // to consolidate).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Partial lookahead credit: leftover can still host the next item.
            score -= 15.0 * (post_residual as f64 / (post_residual + next_item_size) as f64);
        } else {
            // Leftover too small for next item: penalize dead space relative to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Penalize leaving residuals that are awkwardly small (unusable dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer packing into bins whose residual is already below average
    // (consolidate fullness, keep large-residual bins flexible).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight preference for filling bins more fully as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (item_size as f64 / bin_capacity as f64);

    // When many bins are open, favor tighter fits to avoid bin proliferation.
    if open_bins_count > 3 {
        score += 0.05 * (post_residual as f64) * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (i.e., current score would otherwise be very poor).
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space non-linearly: small post_residual that is still
    // unusable by the next item is wasted capacity.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if (next_item_size as f64) > gap && gap > 0.0 {
            // Dead space: nothing of the lookahead fits here.
            score += (next_item_size as f64 - gap) * 0.35;
        } else if (next_item_size as f64) <= gap {
            // Reward bins that can also host the lookahead item.
            score -= (gap - next_item_size as f64).min(20.0) * 0.5;
        }
    }

    // Perfect-fit reward: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Tightness reward: prefer bins where the item occupies a large fraction
    // of the residual (good fit density).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.1 * (bin_residual as f64 - post_residual as f64);
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Penalize
    // it mildly so open bins get used, but less when open bins are crowded
    // (low mean residual) or many bins exist and time is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = mean_residual / bin_capacity as f64;
        score += 12.0 - 10.0 * crowd - 6.0 * progress;
    }

    // Global state coupling: when mean residual is high, prefer spreading
    // (favor tighter fits less); when mean residual is low, squeeze hard.
    score += 0.08 * (mean_residual - post_residual as f64);

    // Late-stream pressure: as the stream progresses, discourage opening
    // bins and encourage closing out existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    // Mild penalty for creating residuals that few future items could use
    // (residuals below the minimum item size are pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap; // 0..1
    let prog = progress.clamp(0.0, 1.0);
    let coupling = pr_norm * pr_norm * (1.0 - prog) + (1.0 - pr_norm) * prog * pr_norm;
    score += 12.0 * coupling;

    // Penalize large dead space more than linearly as stream advances.
    score += 8.0 * pr_norm.powi(3) * (0.3 + 0.7 * prog);

    // Reward tight fits (small post_residual) with a smooth bonus.
    score -= 10.0 * (1.0 - pr_norm).powi(4) * (1.0 - prog);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_gap = (pr - next_item_size as f64) / cap;
        score -= 9.0 * (1.0 - fit_gap).powi(3);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr) / cap;
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64).sqrt() * (pr - mean_residual).abs() / cap;

    // New-bin candidate handling: prefer opening a new bin only when fits are poor.
    if bin_residual == bin_capacity {
        score = pr + 20.0 * (1.0 - (1.0 - pr_norm).powi(2)) + 10.0 * (1.0 - prog);
        if fitting_bins_count == 1 {
            score += 25.0; // avoid wasting a new bin when a last-chance fit exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small" residue classes (<= 20) are nearly closed — reward them strongly.
    let pr = post_residual;
    let residue_class = pr % 25; // quarter-capacity harmonic
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 40.0;
    } else if residue_class == 0 {
        score -= 15.0; // clean harmonic leftover (25/50/75) reusable by many sizes
    }

    // Penalize dead space in awkward classes (post_residual in 11..=20 wastes slots)
    if pr > 10 && pr <= 20 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= 10 {
                score -= 25.0;
            } else {
                score += gap as f64 * 0.3;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to leftover
            score += pr as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Fraction-of-capacity fill ratio reward (non-linear)
    let fill_ratio = (bin_residual as f64 - item_size as f64) / cap;
    score -= fill_ratio * fill_ratio * 20.0;

    // New-bin candidate: penalize opening a bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * (open_bins_count as f64).sqrt() * -1.0;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        if pr_class_bonus(next_item_size) > 0.0 {
            score -= 5.0;
        }
    }

    // Stream progression: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs().min(50.0) * 0.2;

    score
}

fn pr_class_bonus(next_item_size: u32) -> f64 {
    match next_item_size % 25 {
        0 => 10.0,
        _ => 0.0,
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }
    // Mid-range dead space (11..20) is moderately wasteful.
    if post_residual > 10 && post_residual <= 20 {
        score += 2.0 * (post_residual as f64 - 10.0);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; makes new-bin candidate less attractive as count grows.
    score += 1.5 * open_bins_count as f64 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if this bin would leave
    // a large dead gap and the next item could use the leftover space.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when justified.
        score += 35.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 {
            // If the next item fits into the post residual of this placement,
            // opening a fresh bin is more acceptable.
            if next_item_size <= post_residual {
                score -= 30.0;
            }
        }
    }

    // Lookahead coupling: penalize placements whose leftover cannot host
    // the next item if the next item is large.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Slight late-stream pressure to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits into the post residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly it fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 50.0 + 100.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize dead space left behind.
            let dead = post_residual as f64;
            score += 30.0 + dead;
        }
    }

    // Penalize small unusable residuals (dead space below typical item range).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Reward using bins with large residuals relative to mean (balance bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor filling it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Early in the stream, prefer opening new bins slightly less (keep bins tight later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress;

    // New-bin candidate: mildly penalize so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that can't
    // fit a typical future item is wasted. Penalize residuals that are "almost
    // usable" (small but nonzero) more than very large usable space.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // valley penalty: residuals in [1, 15] are the worst dead space
        let dead = if pr <= 15.0 { (16.0 - pr) * 1.5 } else { 0.0 };
        score += dead;
    } else {
        // perfect fit: strong reward
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 12.0 - slack.min(12.0) * 0.5; // reward exact-ish lookahead fit
        } else if pr > 0.0 && nxt > pr {
            // next item won't fit here regardless; mildly neutral
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Prefer filling fuller bins relative to the fleet average residual.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Late in the stream, consolidate: fewer open bins is better, and we should
    // avoid opening new bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 10.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Reward high fill ratio of the current bin.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a non-linear (quadratic) penalty on wasted space
    let mut score = pr * (1.0 + 0.8 * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, waste is increasingly costly
    let progress_coupling = 2.0 * progress * (1.0 - progress) * norm_pr * pr;
    score -= progress_coupling;

    // Interact with mean residual: penalize bins far below the mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: strong smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving room for the next item, smoothly scaled
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let compat = if pr >= ni { 1.0 - (pr - ni) / cap } else { 0.0 };
        score -= 8.0 * compat * compat * (0.5 + progress);
    }

    // Mild penalty on opening new bins late in the stream
    let is_new_bin = (bin_residual as u64) == (bin_capacity as u64);
    if is_new_bin {
        score += 6.0 + 10.0 * progress * progress;
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" does it land in?
    // Classes of 10 units; residuals in [0..=9] are dead space (unusable for
    // items >= 10 in the classic regime, but sizes can be as small as 1 here,
    // so dead space only starts below ~5).
    let class = post_residual / 10; // 0..=10
    let dead = if post_residual < 5 { 1.0 } else { 0.0 };

    // Penalize landing in a low-value band: small residuals waste capacity.
    // Harmonic weighting: penalty grows as 1/(class+1) shrinks... invert:
    // small class => large penalty.
    score += 40.0 / (class as f64 + 1.0) * 0.25;

    // Dead-space penalty (residual too small for any realistic item).
    score += dead * 60.0;

    // Perfect fit bonus: post_residual exactly 0.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item fits exactly into the leftover class.
            let next_class = next_item_size / 10;
            let resid_class = post_residual / 10;
            if next_class == resid_class {
                score -= 25.0; // same harmonic band: excellent chaining
            } else {
                score -= 10.0;
            }
            // Exact chaining fit
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; penalize slightly more if this bin
            // would be left with tiny dead space.
            score += dead * 20.0;
            // If next item is large and post_residual is small, mild penalty.
            if next_item_size > 50 && post_residual < 20 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual >= 5 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Prefer using existing bins when the fit is decent; opening a new bin
    // should only win when this bin's post-fit residual is poor.
    if bin_residual == bin_capacity {
        // Opening a new bin: neutral-ish base, penalized so existing good fits win.
        score += 15.0;
        // But reward a new bin when the current item is large relative to capacity
        // (large items pair well with fresh bins for future complements).
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 20.0;
        }
    }

    // Mild pressure against proliferating bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 3 {
        score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean: choosing a
    // bin with residual below mean concentrates waste in fewer bins.
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += dev * 0.05; // tighter-than-average bins slightly favored
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item * 10 {
        // Unusable sliver: heavy penalty scaled by how close it is to being pure waste.
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits generally (small waste relative to item).
    score -= 0.35 * (item_size as f64 / (item_size + post_residual).max(1) as f64) * 10.0;

    // Penalize residuals that can't host the lookahead item when the next item could
    // otherwise have used this bin's space well.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Dead-space avoidance relative to mean residual: bins far below mean residual
    // (i.e., nearly full) are good targets.
    score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // New-bin candidate: penalize opening a new bin, but less when current bins are crowded.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Late-stream tightening: as stream progresses, prefer filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for filling the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills the post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }

    // Partial lookahead: next item fits comfortably in leftover space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    }

    // Dead space penalty: leftover space too small for any plausible item (min size 1..100 unknown,
    // penalize small-but-nonzero leftovers relative to mean residual).
    if post_residual > 0 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 20.0;
        }
        // Penalize leftovers well below the mean residual (fragmented bin).
        if (post_residual as f64) < mean_residual * 0.5 {
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins with tighter residual (best-fit core) modulated by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.3 * (bin_residual as f64) * (0.5 + 0.5 * progress);

    // Early in the stream, allow opening new bins more freely to keep flexibility.
    if bin_residual == bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Exact / near-exact fill bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strong preference to use it before opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use leftover; penalize proportionally
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling: only open a new bin when fits are poor
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fit = mean_residual / bin_capacity as f64;
        // discourage new bins early or when open bins have room
        score += 15.0 + 20.0 * avg_fit + 10.0 * (1.0 - progress);
        // but if the item is huge and nothing fits well, allow new bin
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 60.0;
        }
        if fitting_bins_count <= 1 && mean_residual < item_size as f64 {
            score -= 35.0;
        }
    }

    // Mild preference for fuller bins among many open bins
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual), with smooth non-linear shaping.
    let mut score = pr;

    // Non-linear penalty on post_residual: dead space quadratically penalized,
    // scaled by stream progress (later in stream => tighter packing required).
    let prn = pr / cap;
    score += prn * prn * cap * (0.5 + 0.5 * progress);

    // Reward bins whose residual is well-used relative to mean residual.
    score -= (mean_residual - pr) * 0.15 * (1.0 + progress);

    // Last-chance bonus: smooth cubic coupling with fitting_bins_count.
    let fbn = fitting_bins_count as f64;
    let scarcity = 1.0 / (fbn * fbn);
    score -= scarcity * item * 0.4;

    // Lookahead coupling: reward leaving residual that can host the next item.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = pr - nxt;
        if gap >= 0.0 {
            // Smooth reward decaying with leftover gap size.
            score -= (gap / cap).exp() * nxt * 0.25;
        } else {
            // Penalize residuals that barely miss the next item.
            score += (-gap) * 0.1 * (1.0 - progress);
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += (open_bins_count as f64).ln() * 0.3 * prn;

    // New-bin candidate: neutralize its raw residual advantage via smooth bias
    // that grows with stream progress and number of open bins.
    if bin_residual == bin_capacity {
        score += cap * (0.4 + 0.4 * progress + 0.05 * (open_bins_count as f64).ln());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into "usable" classes
    // (multiples of common item sizes / quarter-capacity bands), penalize dead space.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Class bonus: exact multiples of 10, 20, 25, 50 are re-usable by future items.
    let class_bonus = if pr == 0 {
        -30.0 // perfect fit is best
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr >= quarter && pr < half {
        -2.0
    } else {
        6.0 // small awkward slivers are dead space
    };
    score += class_bonus;

    // Integer-division threshold on post_residual: residuals below the smallest
    // item (10) can never be used again -> heavy penalty.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // next item fits but leaves a new residual: evaluate its class
            let npr = pr - next_item_size;
            if npr % 10 == 0 {
                score -= 6.0;
            } else if npr < 10 {
                score += 8.0;
            }
            score += (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: penalize wasting space
            score += (next_item_size - pr).min(40) as f64 * 0.4;
        }
    }

    // Capacity-fraction scaling of residual waste: waste matters more early
    // in the stream when many decisions remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / cap) * (1.0 - progress) * 10.0;

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when residuals are fragmented
    // or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (mean_residual as u32 % 10) as f64) / cap;
        if mean_residual < 20.0 || (item_size as f64) > mean_residual + 15.0 {
            score -= 15.0;
        } else {
            score += 10.0 + fragmentation * 5.0;
        }
    }

    // Mild tie-break toward tighter bins when many bins are open.
    score += (post_residual as f64 / cap) * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let dead_zone: f64 = if post_residual < 10 {
        40.0
    } else if post_residual < 20 {
        18.0
    } else {
        0.0
    };
    score += dead_zone;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Exact match with lookahead item: strong bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    // Last fitting bin pressure: avoid forcing a new bin when feasible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin count pressure: discourage opening new bins as bins accumulate.
    let new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin {
        score += 30.0 + 20.0 * open_bins_count as f64 * (0.3 + progress);
    } else {
        score -= 8.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins tighter than the mean residual (compactness).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Dead-space coupling: if the gap left is smaller than the next item, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the NEXT item exactly matches post_residual,
    // this placement chains into a perfect fit -> strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack * 2.0;
        } else {
            // next item cannot use the leftover space: penalize dead space
            // more severely when the leftover is small (unusable) relative to mean
            let waste = next_item_size - post_residual;
            if waste <= 10 {
                score += 60.0;
            } else {
                score += (waste as f64).sqrt() * 8.0;
            }
        }
    }

    // Penalize leaving residual far below mean residual (creating outliers of dead space)
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.5;
    } else {
        score += dev * 0.2; // slightly reward keeping residual above mean
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make empty bins mildly attractive only when the item
    // is large and no good fit exists; otherwise discourage fragmentation.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 50.0;
        } else {
            score += 120.0;
        }
    }

    // Late in the stream, tighten packing (avoid opening bins needlessly)
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
