pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: normalized post residual
    let mut score = post / cap;

    // Non-linear polynomial coupling with stream progress:
    // later in the stream, tight fits (small post_residual) are worth more,
    // while wasted space is penalized super-linearly.
    let tightness = 1.0 - post / cap;
    score -= 2.0 * progress * tightness * tightness;
    score += 1.5 * (1.0 - progress) * (post / cap) * (post / cap);

    // Dead-space penalty: residuals too small for typical future items
    let dead = (post / cap) * (post / cap) * (post / cap);
    score += 3.0 * dead * (0.5 + progress);

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 1.0 * snug * snug;
    } else if next_item_size > 0 {
        score += 0.5 * progress;
    }

    // Last-chance bonus: this is the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // Penalize opening a new bin when open bins fit well
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post).abs() / cap;
        score += 0.8 + 0.5 * spread + 0.3 * progress;
    }

    // Mild pressure against scattering across many open bins
    score += 0.02 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;

    // Harmonic class of post_residual: mod-10 buckets; small buckets are "dead space" classes.
    let class = (post_residual % 10) as f64;
    // Penalize residual classes that are hard to fill (small but nonzero leftovers).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 12.0; // unusable sliver for most items
        } else if post_residual < 20 {
            score += 6.0;
        }
        // modulo coupling: residuals near multiples of 10 pair well with 10-multiple items
        score -= 4.0 * (1.0 - class / 10.0);
    } else {
        score -= 15.0; // perfect closure: strongly reward
    }

    // Lookahead: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            score -= 8.0 + (next_left as f64) / 10.0;
            if next_left == 0 {
                score -= 10.0; // chain closure bonus
            }
        } else {
            score += 3.0; // next item won't fit here; residual likely dead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's post_residual would be badly fragmented.
    if bin_residual == bin_capacity {
        // empty bin: neutral-ish score = capacity; reward when item is large
        score = bin_capacity as f64 - 2.0 * item_size as f64;
        if item_size >= 50 {
            score -= 5.0;
        }
        if post_residual < 10 && post_residual > 0 {
            score += 8.0; // creating a sliver in a fresh bin is wasteful
        }
    }

    // Progression: as stream matures, be more conservative with open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * fit_ratio * (open_bins_count.min(20) as f64 / 10.0);

    // Mean residual coupling: when mean residual is high, tolerate looser fits.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

