        score += 30.0 + pressure * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin can pair large items with next one
        }
    }

    // Late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    // Prefer filling bins that are already below average residual (consolidation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
