    }

    // Penalize leaving dead space below the minimum item size (unusable residue),
    // scaled by stream progress since endgame waste is costlier.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 + 20.0 * progress;
    }

    // Prefer bins whose residual is already below the mean (denser bins),
    // keeping relative tightness across the pool.
    score -= 0.3 * (mean_residual - post_residual as f64);

