    // (encourages packing big items into big spaces first).
    if post_residual as f64 > mean_residual && next_item_size == 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 2.0;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            if gap == 0.0 {
                score -= 90.0;
            } else if gap <= 10.0 {
                score -= 45.0;
            } else {
                score -= 20.0 * (1.0 - gap / cap);
            }
        } else {
            // next item won't fit here after placement; penalize large leftovers
            score += (post / cap) * 25.0;
        }
    }

    // Penalize bins whose residual deviates far from mean (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Time horizon: later in stream, be greedier about tight fits, avoid opening bins
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= t * 25.0 * tightness;
    score += (1.0 - t) * 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 { 0.0 } else { 0.0 };
        score = 100.0 + (cap - item_size as f64) * 0.5 - best_possible;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if fitting_bins_count == 1 {
            score += 70.0; // an open bin is last chance; prefer it
        }
    }

    // Mild penalty for wasting a large bin on a small item
    score += (item_size as f64 / cap) * (post / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: post residual with non-linear damping (dead space matters more when small)
    let mut score = post + 18.0 * norm_post * norm_post - 6.0 * norm_post.powi(3);

    // Smooth stream-progress coupling: tighter packing demanded later in the stream
    let tight = 1.0 - progress;
    score += 10.0 * tight * norm_post * (1.0 - norm_post);

    // Interaction between post residual and mean residual across bins
    let mean_norm = mean_residual / cap;
    score += 8.0 * (norm_post - mean_norm) * (1.0 - progress);

    // Lookahead: reward leaving room for the next item (smooth quadratic gap match)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 14.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin (smooth sigmoid-like weight)
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * (1.0 - norm_post));
    }

    // Mild penalty for bin proliferation early on
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // Prefer fuller placements via item-to-residual ratio coupling
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill * fill * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    // Residuals in (0..10] are near-perfect fits; reward them strongly.
    if post_residual == 0 {
        score -= 60.0; // perfect packing
    } else if post_residual <= 10 {
        score -= 40.0;
    } else {
        // Dead-space harmonic classes: residuals that no item (min size 1..10)
        // can use well are penalized via integer-division buckets.
        let quarter = bin_capacity / 4; // 25
        let half = bin_capacity / 2;    // 50
        let bucket = post_residual / 10; // harmonic class index
        score += (bucket as f64) * 3.0;
        if post_residual > half {
            score += 8.0; // large dead space
        }
        if post_residual % quarter == 0 {
            score -= 6.0; // aligned residual is reusable by future items
        }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0; // chain two items here
        // bonus if next item leaves another near-zero residual
        let next_post = post_residual - next_item_size;
        if next_post <= 10 {
            score -= 15.0;
        }
    } else if next_item_size > post_residual {
        score += 10.0; // next item will need another bin anyway
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when current residual
    // is a bad harmonic class and next item is large.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        if post_residual == bin_capacity && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big item, fresh bin is fine
        }
        score += pressure; // slight preference to reuse existing bins
        if bin_residual <= 30 {
            score -= 5.0;
        }
    }

    // Stream progression: early on, be conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Prefer bins whose residual is close to mean (balanced packing).
    score += ((post_residual as f64 - mean_residual) / 20.0).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strong bonus to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate: penalize mildly so it only wins when fits are terrible,
    // but relax the penalty as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: if next item could use the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to item needs.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 500.0; // perfect 2-item chain fill
        }
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize dead space.
        score += 25.0 + (post_residual as f64).min(30.0);
    }

    // Penalize leaving residuals too small to ever be useful (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Compare post_residual against mean residual: prefer tighter-than-average fills.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0
            && next_item_size > 0
            && post_residual >= next_item_size;
        if good_fit_exists {
            score += 200.0; // keep filling existing bins
        } else {
            // Poor fits everywhere: opening fresh capacity is fine.
            score -= 150.0;
        }
    }

    // Mild preference for compact bin sets as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (open_bins_count as f64).recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score toward 0 as post_residual shrinks (non-linear).
    let pr = post_residual as f64;
    score += pr * pr / (bin_capacity as f64 * 4.0); // quadratic dead-space penalty

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the residual
    // would be useful for the lookahead item or no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut new_bin_score = (bin_capacity as f64) * 0.75; // base reluctance
        // Favor new bin if item is large (poor fit candidates elsewhere)
        new_bin_score -= (item_size as f64) * 0.5;
        // Favor new bin if post-residual can host the next item exactly-ish
        if next_item_size > 0 && next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            new_bin_score -= 30.0 - slack * 0.4;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 25.0;
        // Many open bins with high mean residual: avoid adding another
        new_bin_score += (open_bins_count as f64) * 1.5 + mean_residual * 0.1;
        score = new_bin_score;
    } else {
        // Lookahead synergy: bonus if post_residual accommodates next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.15;
        } else if next_item_size > post_residual {
            // dead space that can't host lookahead item: mild penalty
            score += 3.0;
        }

        // Prefer bins whose residual deviates below the mean (better packing targets).
        score += (mean_residual - bin_residual as f64).max(0.0) * -0.05;
        score -= (bin_residual as f64 - mean_residual).max(0.0) * 0.05;

        // Early stream: slightly prefer tighter fits to build dense bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * (item_size as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Smooth polynomial coupling: base cost of leftover space, warped by progress
    let base = pr as f64;
    let warp = 1.0 + 0.6 * progress - 0.5 * progress * progress;
    let mut score = base * warp;

    // Non-linear penalty for small dead space (unusable fragments), stronger late
    let dead = (1.0 - x).max(0.0);
    score += 12.0 * dead * dead * (0.5 + progress);

    // Reward tight fits (post_residual near zero) smoothly
    score -= 25.0 * (-x * 8.0).exp();

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead coupling: if next item fits into resulting post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let tight = 1.0 - (next_item_size as f64 / pr.max(1.0));
        score -= 10.0 * (1.0 + tight * tight);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Mild preference for bins below mean residual (keeps balance), smooth
    score += 0.05 * (mean_residual - pr).abs();

    // New-bin candidate: penalize slightly unless open bins are scarce
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes group residuals
    // into "compatibility bands" for typical item sizes.
    let post = post_residual as i64;
    let class = post % 10;

    // Reward residuals that fall into highly reusable classes (small residues
    // divisible by common item sizes: 10, 20, 25, 50).
    if post % 50 == 0 {
        score -= 18.0;
    } else if post % 25 == 0 {
        score -= 12.0;
    } else if post % 10 == 0 {
        score -= 8.0;
    } else if post % 5 == 0 {
        score -= 3.0;
    } else {
        // Odd/prime-like residuals create dead space; penalize by class distance.
        score += (10 - class) as f64 * 0.6;
    }

    // Integer-division threshold: residual in the "small pocket" band is dead space.
    let pocket = post / 10; // which decade band the residual lives in
    match pocket {
        0 => score += 15.0,           // 0..9: nearly unusable
        1 => score += 6.0,            // 10..19: only tiny items fit
        2 | 3 => score -= 4.0,        // 20..39: sweet spot for mid items
        4 | 5 => score -= 6.0,        // 40..59: good for large items
        _ => score -= 2.0,            // large residual: fine but wasteful
    }

    // Coupling with lookahead: if the next item exactly fits the post residual,
    // strongly reward this bin (perfect harmonic pairing).
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt == post {
            score -= 30.0;
        } else if nxt < post {
            let left = post - nxt;
            // How clean is the leftover after the lookahead pair?
            if left % 10 == 0 {
                score -= 10.0;
            } else if left < 10 {
                score += 8.0; // pair creates tiny dead space
            } else {
                score -= (left / 10) as f64 * 1.5;
            }
        } else {
            // Next item cannot follow in this bin: mild penalty unless bin
            // will be effectively closed (post residual tiny).
            if post >= 10 {
                score += 4.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the item is big or open bins are fragmented.
    if bin_residual == bin_capacity {
        let tight_fit = item_size as f64 / bin_capacity as f64;
        if tight_fit > 0.7 {
            score -= 12.0; // big items deserve fresh bins
        } else if mean_residual > item_size as f64 * 1.5 && open_bins_count > 0 {
            score += 10.0; // existing bins have room; don't open new ones
        } else {
            score += 2.0;
        }
    }

    // Stream progression: late in the stream, prefer closing bins tightly
    // (small residuals) to avoid spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;
    score -= progress * 3.0 * (post as f64 / 100.0);

    // Slight preference for bins whose residual is close to the item (snug fit).
    score += (bin_residual as f64 - item_size as f64) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
