pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near match: next item fits snugly (within small slack)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 60.0 - slack as f64 * 5.0;
        }
    }

    // Penalize dead space too small for any plausible next item (items >= 1, typical >= 10)
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement wastes a lot
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin if placing here would leave a large awkward residual
        if next_item_size > 0 && post_residual > 40 && post_residual < next_item_size {
            score -= 55.0;
        }
    }

    // Favor bins with residual below mean (tighter bins absorb items well)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Early stream: be slightly more conservative with open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) especially when item is large.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 12.0;

    // Penalize dead space: small post_residual that is unusable (>0 but < min plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits into this bin's post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving awkward gap.
        score += 0.05 * (next_item_size as f64 - post_residual as f64);
    }

    // New-bin candidate handling: empty bin gets baseline competition.
    if bin_residual == bin_capacity {
        // Prefer new bin when open bins are crowded or fit is poor.
        let crowdedness = mean_residual / bin_capacity as f64;
        let poor_fit = post_residual as f64 > 40.0;
        if crowdedness < 0.25 || poor_fit {
            score -= 8.0;
        } else {
            score += 10.0;
        }
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Penalize bins far below mean residual (fragmentation avoidance).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += 0.08 * dev;
        }
    }

    // Slight preference for bins with fewer alternatives when many bins fit.
    if fitting_bins_count > 3 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    let mut score = 3.0 * poly;

    // Reward tight fits (small post_residual) more strongly late in the stream.
    score += 0.5 * (1.0 - progress) * norm_pr;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = ((pr - nxt).abs()) / cap;
        score += 0.8 * waste * waste * (0.4 + 0.6 * progress);
        if pr >= nxt {
            score -= 0.6 * (1.0 - norm_pr) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 + 0.5 * progress);
    }

    // Slight preference to keep many open bins balanced: compare with mean residual.
    score += 0.3 * (pr - mean_residual) / cap;

    // New-bin candidate: penalize mildly so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 1.2 + 1.5 * progress + 0.01 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of residual.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Harmonic class logic: classify post_residual by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Penalize "awkward" residual classes: residuals just above common item sizes
    // (e.g., 1..=5 dead zones are nearly unusable for many distributions).
    if post_residual > 0 && post_residual <= 5 {
        score += 25.0; // dead space penalty
    }

    // Modulo arithmetic: residuals that are multiples of common divisors (10, 20, 25, 50)
    // compose well with typical item sizes; reward them.
    let harmonic_bonus = if post_residual == 0 {
        60.0 // perfect fit
    } else if post_residual % 50 == 0 {
        30.0
    } else if post_residual % 25 == 0 {
        22.0
    } else if post_residual % 10 == 0 {
        16.0
    } else if post_residual % 5 == 0 {
        8.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Integer-division thresholds on residual: how many "half-capacity" chunks remain.
    let half_chunks = post_residual / 50;
    score -= 4.0 * half_chunks as f64;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let post2 = post_residual - next_item_size;
            // reward leaving residual that again stays in a good harmonic class
            if post2 % 10 == 0 {
                score -= 12.0;
            }
            score -= 6.0 * (1.0 - post2 as f64 / cap);
        } else {
            // next item cannot use this residual: mild penalty proportional to leftover
            score += 5.0 * frac;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    // or fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open new bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If many open bins already, opening another is more costly.
        score += 2.0 * open_bins_count as f64;
        // If the mean residual of open bins is large, prefer existing bins.
        score += 0.3 * mean_residual;
        // If item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.2 * item_size as f64;
    }

    // Slight preference for bins with residual above the mean (balance preservation).
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits: fraction of bin consumed
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (open_bins_count as f64) * (2.0 + 6.0 * progress);

    // Lookahead: if next item fits in the post-residual, reward; if it would
    // exactly fill, extra reward (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item can't fit here: leftover becomes dead space for lookahead
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Prefer bins below mean residual (keep mean residual low and uniform)
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits tightly into post_residual.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot use the leftover: penalize proportionally to dead space.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward bins tighter than the mean residual (well-filled bins).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Early in the stream, allow opening new bins more freely; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear discount.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 4.0; // still useful range for typical items
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward heavily (perfect chaining).
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 1.0 {
            score -= 30.0;
        } else if post_residual as i64 - next_item_size as i64 >= 0 {
            score -= 8.0 * (1.0 - (post_residual as f64 - nr) / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving medium gaps
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: opening a bin is costly unless current bins
    // are fragmented or the stream is early with many items remaining.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            (mean_residual - post_residual as f64).abs() / bin_capacity as f64
        } else {
            0.0
        };
        // Base cost of a new bin, discounted early in the stream and when
        // open bins have poor average residual vs. this fresh bin.
        let mut new_bin_cost = 18.0
            + 30.0 * progress
            - 20.0 * fragmentation
            - 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 && next_item_size as f64 <= bin_capacity as f64 {
            new_bin_cost -= 6.0; // fresh bin can host the next item too
        }
        score += new_bin_cost.max(2.0);
    }

    // Mild pressure to consolidate across many open bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Time-horizon term: late in the stream, prefer filling bins as fully as possible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Alignment with global mean residual: bins far from the mean are
    // slightly preferred targets when they can absorb more.
    if bin_residual < bin_capacity {
        score -= 0.05 * (mean_residual - post_residual as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear coupling to stream progress.
    // Early on, keep residuals flexible (penalize small post_residual less);
    // later, tight fits matter more, so post_residual weight grows.
    let mut score = pr * (0.6 + 1.2 * progress * progress);

    // Non-linear penalty for awkward dead space: residual in the "unusable band"
    // (small but nonzero) is worse than either a perfect fit or generous space.
    let dead = norm_pr * (1.0 - norm_pr);
    score -= 8.0 * dead * dead * (0.5 + progress);

    // Perfect fit reward, smoothly scaled by progress.
    let perfect = (norm_pr * (cap - 1.0) / cap).tanh();
    score -= 12.0 * perfect * (0.5 + progress);

    // Lookahead coupling: reward leaving room for the next item, smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let compat = 1.0 - (norm_pr - nxt).abs();
        if compat > 0.0 {
            score -= 6.0 * compat * compat;
        } else {
            score += 4.0 * (-compat) * (-compat);
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * progress;

    // Prefer bins whose residual is near the mean (keeps residual spread tight).
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot band" does the leftover fall into?
    let band = post_residual / 10; // 0..=10 harmonic class
    // Small leftovers (bands 0-1) are excellent: big bonus
    if band == 0 {
        score -= 30.0;
    } else if band == 1 {
        score -= 18.0;
    } else if band == 2 {
        score -= 6.0;
    } else if band >= 5 && band <= 7 {
        // mid-range leftovers are the classic dead zone
        score += 8.0 + (band as f64 - 5.0) * 3.0;
    }

    // Integer-division threshold: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect harmonic pairing: next item exactly consumes the class
            if next_item_size == post_residual {
                score -= 40.0;
            } else {
                score -= 12.0;
                // pair residual class: leftover after pair
                let pair_left = post_residual - next_item_size;
                if pair_left / 10 == 0 {
                    score -= 15.0;
                } else if pair_left > 40 {
                    score += 5.0;
                }
            }
        } else {
            // next item won't fit here: bin becomes terminal
            score += 10.0;
            if next_item_size > 60 && post_residual < 30 {
                score -= 5.0; // terminal is fine, next item needs a big bin anyway
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 1 {
            score -= 30.0; // still prefer using the last fitting bin
        }
        if item_size >= bin_capacity / 2 {
            score -= 20.0; // big items are fine in fresh bins
        }
    }

    // Fraction of capacity filled by this item: harmonic fraction coupling
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 20.0;

    // Prefer tighter bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (post_residual as f64 / cap);

    // Small dead-space penalty scaled quadratically
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10) are unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // Gaps below 20 fit only tiny items; moderate penalty.
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; penalize leaving a gap it can't use.
            score += 6.0;
        }
    }

    // Mild bonus for using bins with residual above mean (consolidate large gaps).
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    }

    // Late in stream: be more conservative, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly as stream progresses.
        score += 25.0 + 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (subtract).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to leftover after next item.
            let after_next = post_residual - next_item_size;
            score -= 50.0 + after_next as f64 * 0.5;
        } else {
            // Next item cannot fit: penalize dead space that is too small to be useful.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 60.0; // tiny unusable sliver
            } else {
                score += dead * 0.3;
            }
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Relative to mean residual: bins with more free space than average should be
    // used for large items; prefer spreading load.
    let mean = mean_residual;
    if (bin_residual as f64) > mean {
        score -= 20.0;
    } else if (bin_residual as f64) < mean * 0.5 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, or many open bins with small residuals).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let waste_if_open = (bin_capacity - item_size) as f64;
        // Base cost of a fresh bin; offset by pressure when open bins are fragmented.
        score = 150.0 + waste_if_open * 0.5 - pressure * 120.0
            - (open_bins_count as f64) * 2.0
            + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host both current and next item if sizes allow.
            if item_size + next_item_size <= bin_capacity {
                score -= 300.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
