    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly -> penalize quadratically.
    score += (norm_pr * norm_pr) * cap * (0.25 + 0.75 * progress);

    // Reward tight fits (small post_residual) with a smooth saturating term.
    let tightness = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= 8.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Penalize wasted residual that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = ((pr - nx) / cap).max(0.0);
        score += 6.0 * waste * waste * cap * (0.3 + 0.7 * progress);
        // Reward leaving exactly enough room for the next item.
        let gap = (pr - nx).abs() as f64 / cap;
        score -= 5.0 * (-gap * gap * 20.0).exp();
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.3 * progress);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    let open_norm = (open_bins_count as f64).ln().max(0.0);
    score += 0.5 * open_norm * norm_pr * cap * progress;

    // Pull score toward mean residual regime: prefer bins near the mean residual
    // (balanced packing), with smooth distance penalty.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 8 equal classes.
    let cap_f = bin_capacity as f64;
    let class = (post_residual * 8 / bin_capacity.max(1)) as u32; // 0..7
    // Classes near 0 are tight fits (good); classes near 7 are nearly empty (bad).
    let class_reward: [f64; 8] = [-14.0, -10.0, -6.0, -2.0, 2.0, 5.0, 8.0, 11.0];
    score += class_reward[class.min(7) as usize];

    // Exact fill bonus: post_residual in {0, 1, 2} is near-perfect packing.
    if post_residual <= 2 {
        score -= 18.0;
    }

    // Dead-space penalty: residual in the "unusable" band (too small for the
    // smallest plausible item) is heavily punished.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 22.0;
        } else if next_item_size <= post_residual {
            // partial fit reward scaled by how well it chains
            let chain = (post_residual - next_item_size) as f64;
            score -= 8.0 - (chain / cap_f) * 16.0;
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += ((next_item_size - post_residual) as f64 / cap_f) * 6.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are
    // already open and mean residual is large (existing slack should absorb item).
    if bin_residual == bin_capacity {
        score += 25.0 + 0.35 * open_bins_count as f64 + (mean_residual / cap_f) * 20.0;
    }

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (balanced packing), slight effect.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (dev / cap_f) * 4.0;

    // Late-stream tightening: as the stream progresses, prefer tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (post_residual as f64 / cap_f) * 3.0
           + progress * (post_residual as f64 / cap_f) * 10.0;

    // Integer-division threshold: residual divisible into clean halves/quarters
    // of capacity is more reusable by typical items.
    let q = bin_capacity / 4;
    if post_residual == q || post_residual == 2 * q || post_residual == 3 * q {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small gaps is unusable
    // (items are >= 10 typically, but sizes 1..100 possible here).
    if post_residual > 0 && post_residual < 10 {
        score += 500.0; // dead space penalty: gap can never be filled
    } else if post_residual < 20 {
        score += 120.0; // nearly-dead gap, very unlikely to be useful
    } else if post_residual < 35 {
        score += 40.0;
    }

    // Reward exact / near-exact fills strongly.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Prefer bins whose residual is "consumed" proportionally well:
    // fill ratio bonus (tighter fit relative to capacity is better).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin -> strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: neutral-to-slightly-penalized baseline so it only
    // wins when existing bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 80.0 + 3.0 * open_bins_count as f64;
        // But if the item is large (poor fit anywhere), opening fresh is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 200.0;
        }
    }

    // Lookahead: if next item would fit perfectly into the post_residual,
    // reward leaving exactly that gap; otherwise penalize mismatched gaps.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 60.0; // would create dead space for the next item
        }
    }

    // Slight preference for bins already below mean residual (more full).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves a new residual; reward proportionally to tightness
            let next_post = post_residual - next_item_size;
            score -= 400.0 * (1.0 - next_post as f64 / bin_capacity as f64);
        } else {
            // next item will NOT fit in this bin's remainder: penalize dead space
            score += 150.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Small unusable residuals are dead space; penalize tiny leftovers that don't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            // pairing current item with next item in a fresh bin can be good
            if item_size + next_item_size >= bin_capacity {
                score -= 300.0;
            }
        }
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item can fit into the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        }
        // Penalize leaving a residual that is awkwardly too small for the next item
        // (dead space that will likely never be used).
        if next_item_size > post_residual && post_residual > 0 {
            let waste_ratio = post_residual as f64 / next_item_size as f64;
            score += 6.0 * (1.0 - waste_ratio).max(0.0);
        }
    } else {
        // Last item: prefer the absolute tightest fit.
        score -= 8.0 * tightness;
    }

    // Last-chance bonus: if this is the only open bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize placing small items into bins with large residuals (preserve big
    // residual bins for larger future items).
    let item_frac = item_size as f64 / bin_capacity as f64;
    if item_frac < 0.35 && bin_residual > item_size * 2 {
        score += 5.0;
    }

    // New-bin candidate handling: opening a new bin should be discouraged unless
    // the item is large or there are many open bins with poor residual structure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 30.0;
        // Large items are fine to start fresh bins for.
        new_bin_score -= 20.0 * item_frac;
        // If open bins have low mean residual (they are nearly full), a new bin is reasonable.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 10.0;
        // Later in the stream, be slightly more willing to open new bins to avoid
        // fragmenting many bins simultaneously.
        new_bin_score -= 5.0 * progress;
        // If many bins can already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            new_bin_score += 12.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
        }
        // If this is the only fitting candidate (i.e., no open bins fit), opening
        // a new bin is necessary - make it clearly attractive.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        score = new_bin_score;
    }

    // Mild global-state coupling: with many open bins, favor consolidating into
    // bins whose residual is below the mean (drain the fuller bins first).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: penalize large post-residual, with a non-linear (quadratic/cubic) coupling
    let mut score = post * (1.0 + 0.8 * post_norm * post_norm);

    // Smooth stream-progress coupling: early on, tolerate slack; late, squeeze bins
    let progress_coupling = post_norm * (0.5 + 1.5 * progress * progress);
    score += 20.0 * progress_coupling;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 12.0 * (-post_norm * 4.0).exp();

    // Lookahead: reward if next item fits smoothly in post_residual
    if next_item_size > 0 {
        let gap = post_norm - next_norm;
        score += 6.0 * gap * gap;
        score -= 4.0 * (1.0 - (gap.abs() * 5.0)).max(0.0);
    } else {
        // last item: strongly prefer filling existing bins
        score -= 8.0;
    }

    // Last-chance bin: smooth reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Penalize bins far from mean residual (fragmentation), scaled by open bins
    let mean_norm = mean_residual / cap;
    score += 5.0 * (post_norm - mean_norm).abs() * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Mild penalty for many open bins to discourage needless spreading
    score += 0.3 * open_bins_count as f64 * post_norm;

    // New-bin candidate: neutral base cost so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * progress + 8.0 * item_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Dead-space penalty grows when post_residual falls into "unusable" classes.
        // Items are >= 1, so residual < smallest plausible item is near-dead space.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

        // Modulo-10 harmonic class: residuals that are multiples of 10 align with
        // common item granularities; reward them slightly.
        let mod10 = post_residual % 10;
        if mod10 == 0 {
            score -= 3.0;
        } else if mod10 >= 7 {
            score += 2.0; // awkward leftover
        }

        // Integer-division thresholds: residual in [1,10) is nearly dead.
        if post_residual < 10 {
            score += 8.0;
        } else if post_residual < 20 {
            score += 3.0;
        } else if post_residual <= 40 {
            score -= 2.0; // sweet spot: fits medium items
        }

        // Lookahead coupling: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 25.0;
            } else if next_item_size < post_residual {
                // reward proportional to how well next item fills the leftover
                let fill = next_item_size as f64 / post_residual as f64;
                if fill > 0.7 {
                    score -= 10.0 * fill;
                } else {
                    score -= 4.0 * fill;
                }
                // harmonic check: does next item leave a multiple-of-10 remainder?
                let next_left = post_residual - next_item_size;
                if next_left % 10 == 0 && next_left > 0 {
                    score -= 5.0;
                }
            } else {
                // next item won't fit here; penalize small residuals more as stream progresses
                score += 4.0 + 6.0 * progress;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        } else if fitting_bins_count > 3 {
            // many options: be picky, prefer tighter fits -> post_residual term already does this
            score += 1.0;
        }

        // Prefer filling bins when many bins are open (reduce fragmentation).
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

        // If this bin is far below mean residual, it is "ragged"; slight penalty
        // encourages balanced closing of bins.
        let dev = mean_residual - bin_residual as f64;
        if dev > 20.0 {
            score += 2.0;
        }
    }

    // New-bin candidate: bin_residual == bin_capacity. Make it moderately
    // attractive only when current placement would create tiny dead space
    // or when no good alternative exists.
    if bin_residual == bin_capacity {
        // baseline competitiveness: a fresh bin scores like post_residual = 100
        // minus a small bonus, so only placements leaving < ~15 dead space win.
        score = 100.0 - 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin is good if item + next item pair well
            if item_size + next_item_size <= bin_capacity {
                score -= 6.0;
            }
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // forced to open anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1..10) are unusable "dead" gaps -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }
    // Gaps that cannot fit the lookahead item are semi-dead unless tiny.
    if next_item_size > 0 && post_residual >= 10 && (post_residual as u64) < (next_item_size as u64) {
        score += 60.0;
    }

    // Reward tight fits generally (small post_residual relative to capacity).
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64).max(0.0).sqrt();

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer
    // filling existing bins, and make new-bin candidate less attractive.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += 120.0 + 15.0 * pressure;
        // New bin more acceptable early in the stream.
        score -= 100.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    } else {
        score -= 5.0 * pressure.min(20.0);
    }

    // Prefer bins with residual close to what is being consumed
    // (avoid leaving large mean_residual mismatch).
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    // Lookahead synergy: if the next item fits the post residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when next item exactly matches post_residual (perfect 2-step packing)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong bonus if next item fits exactly into post_residual
        if post_residual >= next_item_size {
            let exact = if diff == 0.0 { 25.0 } else { 0.0 };
            // Reward proportional to tightness of the two-step fit
            let tight = (bin_capacity as f64 - diff) * 0.15;
            score -= exact + tight;
        } else {
            // Next item won't fit here: penalize dead space creation
            score += diff * 0.10;
        }
    }

    // Penalize bins whose post_residual deviates from mean residual (fragmentation risk)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Last-chance bin: strong incentive to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize tiny unusable post_residuals (dead space) unless zero
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mild reward for filling bins tightly as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - post_residual) as f64 * 0.02 * (0.5 + progress);

    // Slight penalty for opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared dead-space penalty
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // dead space that blocks the next item
            score += (next_item_size as f64 - post_residual as f64) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding: when many bins are open, prefer consolidating into fuller bins
    if open_bins_count > 2 {
        score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count.min(20) as f64) * 0.8;
    }

    // Global residual pressure: if mean residual is high, prefer bins below mean (fill the emptier-ish tight fits)
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Time horizon: early in stream, be more liberal about opening new bins; late, conserve
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: mild penalty that grows with progress
        score += 6.0 + 18.0 * progress;
        // opening a new bin is attractive if it gives perfect fit for next item too
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    } else if progress > 0.7 {
        // late stream: strongly avoid leaving tiny unusable slivers
        if post_residual < 10 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits, but with a smooth non-linear (quadratic-cubic) shaping
    let x = pr / cap; // normalized post-residual in [0,1)
    let mut score = pr as f64;
    // Smooth polynomial penalty on wasted space: strongly penalize mid-range dead space
    score += 12.0 * x * x * (1.0 - x) * cap * 0.05;

    // Non-linear coupling with stream progress: early on, be pickier about tight fits;
    // late in the stream, weight tightness even more (residuals are scarcer).
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0; // smooth bump
    score *= 0.5 + 0.5 * progress_coupling;

    // Lookahead synergy: reward bins whose post-residual can host the next item,
    // with a smooth quadratic interaction between post_residual and next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0);
        let synergy = (pr - fits_next) / cap; // ~1 if next item fits snugly
        score -= 8.0 * synergy * synergy * (1.0 - progress * 0.5);
    } else {
        // Last item: strongly prefer zero post-residual
        score += 5.0 * x * x * cap * 0.1;
    }

    // Last-chance bin: smooth reward scaled by how scarce fitting bins are
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - x) * (1.0 + progress);
    }

    // Mean-residual coupling: if this bin is far below the mean residual, it's a good
    // "garbage collector" bin; smooth non-linear reward.
    let dev = (mean_residual - pr) / cap;
    score -= 4.0 * dev * dev.abs();

    // Penalize opening new bins when plenty of open bins exist (smooth in open count)
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64).ln() + 1.0;
        score += 6.0 + 2.0 * congestion * (1.0 - progress * 0.5);
        // But a brand-new bin is attractive for large items leaving tiny post-residual
        score -= 10.0 * (1.0 - x) * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small leftovers are "dead space" if next item cannot use them; big leftovers are flexible.
    // Penalize residuals in awkward narrow bands (just above common item sizes).
    let dead_bands: [u32; 6] = [1, 2, 3, 4, 5, 6];
    if dead_bands.contains(&post_residual) {
        score += 40.0 * (1.0 - post_residual as f64 / 7.0);
    }

    // Modulo-class logic: residuals that are multiples of 10 are "harmonic" with item grid,
    // so they are more likely reusable by future items -> reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    // Residuals that are odd and small are worst class.
    if post_residual % 2 == 1 && post_residual <= 15 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills the leftover
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 60.0 * fill;
        } else {
            // next item cannot use this residual: penalize small residuals more
            let waste = post_residual as f64 / cap;
            score += 30.0 * (1.0 - waste);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // reusing open bins, but relax the penalty for large items or when open bins
    // would leave very fragmented state.
    if bin_residual == bin_capacity {
        let mut penalty = 120.0;
        // large items leave less fragmentation in a fresh bin
        penalty -= (item_size as f64 / cap) * 80.0;
        // many open bins with low mean residual -> fragmentation, prefer new bin
        if open_bins_count > 0 {
            let frag = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            penalty -= 60.0 * frag;
        }
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty -= 30.0 * (1.0 - progress);
        score += penalty.max(0.0);
    }

    // Prefer tighter existing bins: small residual before placement = tight fit.
    let tightness = 1.0 - (bin_residual as f64 / cap);
    score -= 25.0 * tightness;

    // Integer-division threshold: post_residual above 3/4 capacity means we barely
    // used the bin; if it's an open bin that's fine (it stays flexible), but
    // discourage leaving huge residual when many bins are open.
    if post_residual >= 3 * quarter && open_bins_count > 4 {
        score += 10.0;
    }

    // Reward residuals in the "sweet spot" band (eighth..quarter) that many item
    // sizes (10..=25) can fill.
    if post_residual >= eighth && post_residual < quarter {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are wasted -> heavy penalty.
    let dead_threshold: f64 = 12.0;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 3.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let fit_ratio = 1.0 - (post / cap);
    score -= 6.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 5.0 + 4.0 * open_bins_count as f64 + 6.0 * progress;
    } else {
        score += 0.05 * open_bins_count as f64;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 4.0;
    }
    // Penalize if next item nearly fits but not quite (creates temptation).
    if next_item_size > 0 && post > 0.0 && (next_item_size as f64) > post && (next_item_size as f64) - post < 10.0 {
        score += 3.0;
    }

    // Slight preference for bins with residuals near mean (balance).
    score += 0.02 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with little slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize dead space: residual too small for the smallest plausible next item.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 0.8 * dead;
    }
    // Penalize residuals below the typical minimum item size (unusable sliver).
    if post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let good_lookahead = next_item_size > 0 && post_residual >= next_item_size;
        if fitting_bins_count > 0 && (good_lookahead || post_residual <= 15) {
            score += 80.0; // discourage opening a new bin when a decent fit exists
        } else if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: open a new bin
        }
    }

    // Late in the stream: consolidate harder, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for many open bins: encourage filling existing ones.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty dominates.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Lookahead coupling: if the next item fits in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize leaving mid-range dead space.
            score += 10.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize opening new bins when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 15.0; // existing slack exists; don't open a new bin
        }
    }

    // Prefer bins tighter than the mean residual (below-average slack bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, prioritize minimizing post residual even harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * frac;

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post-residual with stream progress
    score += 12.0 * (norm_pr * norm_pr) * (1.0 + 2.0 * progress * progress);

    // Reward tight fits more strongly as the stream progresses
    score -= 18.0 * fit * fit * (1.0 + progress);

    // Penalize dead space relative to mean residual across open bins
    score += 8.0 * (norm_pr - (mean_residual / cap)) * (norm_pr - (mean_residual / cap));

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 4.0 * progress * (1.0 - norm_pr);
    }

    // Last-chance bonus: smooth decay of penalty when few bins fit
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure against hoarding many open bins
    score += 0.5 * (open_bins_count as f64).ln();

    // Slight preference to keep filling existing bins early on
    score -= 3.0 * (1.0 - progress) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo classes: leftover divisible by 10 is highly reusable.
    let mod10 = post_residual % 10;
    score += match mod10 {
        0 => -6.0,
        1 | 9 => 4.0,
        _ => (mod10 as f64) * 0.5,
    };

    // Integer-division thresholds on post_residual: classify leftover size.
    let leftover_class = post_residual / 20; // 0..=5
    score += match leftover_class {
        0 => 12.0,          // dead space (<20): terrible
        1 => 4.0,           // small leftover
        2 => -2.0,          // sweet spot ~40-59
        3 => -5.0,          // ~60-79
        4 => -3.0,          // ~80-99
        _ => 0.0,           // nearly full bin
    };

    // Harmonic coupling: does next_item_size divide or nearly divide post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let fits_next = post_residual % next_item_size == 0;
        if fits_next {
            score -= 10.0; // perfect harmonic match for lookahead item
        } else {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 6.0; // near-perfect packing of next item too
            }
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize proportionally to wasted potential
        score += ((next_item_size - post_residual) as f64).min(30.0) * 0.3;
    }

    // Capacity fraction harmonics: reward filling toward capacity fractions
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    score -= (fill_frac * 10.0).sin() * 3.0; // peaks near 50%, 100% fill

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is awful
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (mean_residual / cap).max(0.1);
        let bad_fit = (post_residual as f64) > 60.0; // would leave big hole in some bin? no: new bin means no hole
        let _ = bad_fit;
        // prefer new bin when mean residual across bins is small (bins nearly full)
        let mean_frac = mean_residual / cap;
        score = 40.0 - mean_frac * 55.0 + (open_bins_count as f64) * 0.05;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        let _ = crowding;
    }

    // Stream progression: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never hold the smallest
    // future item (size 1..100 unknown, assume min ~10) are pure waste.
    let dead_threshold: u32 = 10;
    if post_residual < dead_threshold && post_residual > 0 {
        score += 200.0 * (dead_threshold - post_residual) as f64;
    }

    // Penalize "awkward" residuals: too small for next item but not tiny.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0 + 0.5 * post_residual as f64;
    }

    // Reward perfect or near-perfect fits strongly.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Last-chance bin pressure: if this is the only fitting bin, avoid new bin
    // unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: fewer open bins => keep using them (consolidation).
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current open bins are all badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).min(1.0)
        } else {
            0.0
        };
        // Penalize opening a new bin normally; discount penalty when existing
        // residuals are large (item would leave big gap anyway).
        let new_bin_penalty = 60.0 - 45.0 * fragmentation;
        score += new_bin_penalty.max(5.0);
        // Bonus for large items that would waste space in any partial bin.
        if item_size > 60 {
            score -= 20.0;
        }
    }

    // Slight lookahead synergy: reward leaving space usable by next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 25.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
    }
    // Next item won't fit here: penalize relative to how far off we are.
    else if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.5;
    }

    // Reward tight fits (small post_residual) more than linearly.
    if post_residual < 20 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize creating dead space below the minimum item size (unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Discard new-bin candidate unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Allow new bin if mean residual across open bins is already small (fragmented).
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Late in stream: prefer closing bins tightly, avoid spreading.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.1;

    // Slight preference for bins tighter than the mean (keeps big holes free).
    score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize dead space: post_residual too small to ever fit a future item (< 10).
    if post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted capacity.
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Global state: many open bins with high mean residual -> discourage spreading,
    // prefer filling existing bins (penalize new-bin-like behavior).
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus penalty scaling with open bins.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If mean residual across open bins can fit the item, opening new bin is wasteful.
        if mean_residual >= item_size as f64 {
            score += 20.0;
        }
        // Late in the stream, opening new bins is even worse.
        score += 25.0 * progress;
    } else {
        // Slight reward for placing into bins with below-average residual (balancing).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Fragmentation guard: penalize leaving residual in the awkward 11..=25 zone
    // that few item sizes can use, unless lookahead suggests otherwise.
    if post_residual >= 11 && post_residual <= 25 && next_item_size != post_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize leftover space, with a non-linear (quadratic) waste penalty.
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tight packing matters less; late, residual waste is heavily penalized.
    let coupling = pr * progress * (1.0 + progress * progress) / cap;
    score += 2.0 * coupling;

    // Reward near-perfect fits smoothly (post_residual close to 0 gets extra discount).
    let fit_quality = 1.0 - pr / cap;
    score -= 1.5 * fit_quality * fit_quality * fit_quality;

    // Lookahead: if the next item fits exactly in post_residual, strongly reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let exactness = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= 3.0 * exactness * exactness;
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize creating dead space.
        score += 0.5 * (pr / cap);
    }

    // Last-chance bonus: this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Mild penalty when many bins are already open (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    // Nudge toward bins with above-average residual (spread usage evenly).
    score += 0.3 * (mean_residual - pr) / cap;

    // New-bin candidate: give it a neutral baseline so it is chosen only when
    // all open bins score poorly.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact small classes are ideal dead space
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit
    } else if pr <= 10 {
        score -= 30.0;
    } else if pr <= 20 {
        score -= 15.0;
    } else if pr <= 30 {
        score -= 5.0;
    }

    // Modulo classes on post_residual (harmonic residue bands)
    let m = pr % 10;
    score -= (10 - m) as f64 * 0.8;

    // Penalize large residuals that no plausible item (1..=80) can use well
    if pr > 80 {
        score += (pr - 80) as f64 * 0.5;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.6;
        } else {
            score += 10.0; // next item can't use this bin's leftover
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Tightness of fit relative to capacity
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // Prefer filling bins when many are open
    score += open_bins_count as f64 * 0.3;

    // Early stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Mean residual coupling: avoid bins far from mean (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // New-bin candidate: penalize mildly so it's only chosen when fits are terrible
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit, close the bin
    }

    // Reward tight fits generally (small post_residual relative to capacity).
    score -= 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // If the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 45.0;
        } else {
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }
    // Penalize if next item cannot use the leftover space at all.
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual < bin_capacity {
        score -= pressure * 4.0;
    } else {
        // New-bin candidate: penalize more when pressure is high, unless residual is very tight.
        score += pressure * 6.0;
        if item_size >= 60 {
            score -= 20.0; // big items deserve a fresh bin if nothing tight fits
        }
    }

    // Prefer bins with below-mean residual (fill emptier bins first keeps spread even).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: large bonus when the item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits snugly into
    // the post-residual of this placement (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how tightly the next item nests,
            // leaving minimal double-leftover space.
            let leftover_after_next = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - leftover_after_next / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's residual: penalize if the
            // residual is small enough to become dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(60.0);
        }
    }

    // Relative residual vs mean: prefer bins tighter than average
    // (keeps loose bins open for larger future items).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only fitting bin to
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize new-bin candidate unless residual is genuinely unusable
    // (opening new bins should be a last resort).
    if bin_residual == bin_capacity {
        score += 400.0;
        // But if nothing fits well, allow opening a new bin: soften when
        // the item leaves a large residual in any existing bin anyway.
        if post_residual as f64 > 0.6 * bin_capacity as f64 && item_size > 50 {
            score -= 250.0;
        }
    }

    // Slight early-stream preference for tight packing to build structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small post-residuals non-linearly (dead space penalty)
    let pr = post_residual as f64;
    score += (pr / bin_capacity as f64).powi(3) * 200.0;

    // Lookahead: bonus if next item fits exactly in post-residual
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u32) == post_residual {
            score -= 300.0;
        } else if next_item_size as u32 <= post_residual {
            // next item fits but leaves residue: mild reward scaled by fit tightness
            let tight = 1.0 - ((post_residual - next_item_size as u32) as f64 / post_residual as f64);
            score -= 100.0 * tight;
        } else {
            // next item won't fit here: penalize wasted residual
            score += 40.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Prefer fuller bins (low residual relative to capacity)
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill * 80.0;

    // Global state coupling: if mean residual is high, prefer bins below mean
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Time horizon: early in stream, be picky (higher score tolerance); late, pack tight
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 30.0;

    // New-bin candidate: penalize opening new bins when good open bins exist,
    // but allow it when open bins fit poorly (large post_residual elsewhere)
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 {
            (open_bins_count as f64).ln().max(1.0) * 20.0
        } else {
            -500.0
        };
        score += pressure;
        // late in stream, opening fresh bins is less costly
        score -= progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = post_norm;

    // Quadratic/cubic shaping: penalize tiny dead space more as stream progresses.
    let tight = 1.0 - post_norm;
    score -= 0.6 * tight * tight * (0.5 + 0.5 * progress);
    score -= 0.3 * tight * tight * tight * progress;

    // Perfect-fit reward, stronger late in the stream.
    if post_residual == 0 {
        score -= 1.5 + 1.5 * progress;
    }

    // Penalize leaving dead space that no small item can plausibly use,
    // coupled smoothly with mean residual.
    let mean_norm = mean_residual / cap;
    score += 0.4 * post_norm * (1.0 - mean_norm);

    // Lookahead: reward residuals that can host the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let fit_tightness = 1.0 - ((post - nxt) / cap);
            score -= 0.5 * fit_tightness * fit_tightness;
        } else {
            score += 0.3 * (1.0 - post_norm) * (nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.0 + 2.0 * progress;
    }

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 0.8 + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by residue mod 10
    // and by capacity fraction bands. Residues in {0} are perfect fits.
    let residue = post_residual % 10;
    if post_residual == 0 {
        score -= 500.0; // perfect fit: strongly reward
    } else if residue == 0 {
        score -= 30.0; // post_residual is a multiple of 10: highly reusable
    } else if residue <= 3 {
        score += 12.0; // tiny unusable sliver risk
    } else if residue >= 8 {
        score -= 6.0; // nearly a multiple of 10, still decent
    }

    // Capacity fraction bands on post_residual
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac >= 0.5 {
        score -= 15.0; // bin still half usable: good to leave room here
    } else if frac >= 0.3 {
        score -= 5.0;
    } else if frac > 0.0 {
        score += 20.0; // creating a small pocket: penalize dead space
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // harmonic class of the slack after the lookahead item
            if slack % 10 == 0 {
                score -= 25.0;
            }
            score += slack as f64 * 0.3;
        } else {
            // next item won't fit here; mildly penalize leaving large gaps
            score += 8.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // open a new bin when existing residuals are small or many bins are open
        score = 45.0 + 60.0 * pressure + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        // late in the stream, prefer consolidating into open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 30.0;
        }
    }

    // Mild normalization by stream position: early on, be more selective about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64); // tiny gap => worst outcome
        } else if post_residual < 30 {
            score += 12.0; // awkward mid gap
        } else {
            score -= 8.0; // gap still usable for typical items
        }
    } else {
        score -= 40.0; // perfect fill: strongly reward
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins => discourage spreading, encourage consolidation.
    score += (open_bins_count as f64) * 0.8;

    // Lookahead: if next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use the leftover; if leftover is small, this is dead space
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // New empty bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // neutralize the base residual advantage so it competes fairly,
        // then penalize mildly unless existing bins are fragmented.
        score = score - post_residual as f64 + (bin_capacity as f64) * 0.9
            + 10.0
            - if fitting_bins_count == 0 { 30.0 } else { 0.0 }
            + if mean_residual < 25.0 { 0.0 } else { 15.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: exact match with next item -> chain both items.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // Next item still fits here: mild reward proportional to closeness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space: next item cannot use the leftover -> penalize small leftovers hard.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 150.0 * (1.0 - dead / next_item_size as f64);
            }
        }
    }

    // Prefer bins tighter than the mean residual (fill crowded bins first).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New empty bin candidate: penalize so it's only chosen when open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 400.0;
        // But if no existing bin fits well (post_residual large in all bins),
        // this penalty stands; if some bin fits well, it wins.
        if post_residual == bin_capacity - item_size && item_size >= bin_capacity / 2 {
            score -= 100.0; // allow fresh bin for very large items
        }
    }

    // Late in the stream: consolidate harder, discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    } else {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can't hold typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: reward bins whose post residual can host the next item exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 5.0; // kills future fit potential
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins
        score = (item_size as f64) + 30.0;
        // Open new bin more readily when few bins or late in stream with high mean residual
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 3.0));
        score -= 15.0 * progress * (mean_residual / bin_capacity as f64);
        // If item is large, new bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // If next item nearly fills what this bin would leave, opening is good
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64;

    // Prefer bins whose residual deviates favorably from the mean (consolidation)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog = progress.clamp(0.0, 1.0);

    // Normalized post residual
    let pr = post_residual as f64 / cap;

    // Smooth non-linear coupling: penalize residual more as stream progresses
    score += 8.0 * pr * pr * (0.5 + prog);

    // Tight fit reward (smooth, non-piecewise): strongly subtract when post_residual is small
    let tightness = 1.0 - pr;
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward bins whose leftover could fit the next item (smooth bell)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_gap = (post_residual as f64 - ns) / cap;
        let bell = (-fit_gap * fit_gap * 40.0).exp();
        score -= 6.0 * bell;
        // Penalize leaving a residual that is too big relative to next item (waste)
        score += 2.0 * (fit_gap.max(0.0)) * cap / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + prog);
    }

    // Mild penalty for spreading across many bins late in the stream
    score += 0.5 * open_bins_count as f64 * pr;

    // Deviation from mean residual: prefer bins below mean residual (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that fall into "useless" harmonic classes:
    // classes in (0, 0.1] and (0.1, 0.2] are nearly dead; reward classes near 0.5, 0.25 etc.
    let class = (frac * 8.0).floor(); // 8 harmonic slices
    match class as i64 {
        0 => score += 30.0,                 // (0, 12.5): dead space
        1 => score += 15.0,                 // (12.5, 25): poor
        2 => score -= 2.0,                  // (25, 37.5): usable
        3 => score -= 10.0,                 // (37.5, 50): good
        4 => score -= 8.0,                  // (50, 62.5): good
        5 => score -= 3.0,                  // (62.5, 75): okay
        6 => score -= 1.0,                  // (75, 87.5): okay
        _ => {}                             // (87.5, 100]: near-empty bin
    }

    // Integer-division threshold: post_residual divisible by small harmonics is reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 20 == 0) {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect class match: next item exactly fills remaining space.
            if next_item_size == post_residual {
                score -= 40.0;
            } else {
                score -= 12.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.5;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it only wins
    // when all open bins have bad residual classes.
    if bin_residual == bin_capacity {
        score = 55.0 - (mean_residual * 0.3);
        if open_bins_count == 0 {
            score -= 60.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin is attractive
        }
    }

    // Stream progression: late in the stream, tighten packing (prefer tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    // Mean residual context: many open bins with slack -> avoid fragmenting further.
    if mean_residual > 40.0 && post_residual > 0 {
        score += (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // (below the minimum conceivable item size) are heavily penalized,
    // unless the gap is zero (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post) * 8.0;
    }

    // Reward tight fits: the smaller the post_residual relative to capacity,
    // the better (already captured by base score), but add a superlinear
    // bonus for near-perfect packing.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin should only win when the current
    // bin would leave a bad gap or the fit is loose. Penalize the fresh bin
    // mildly by default, scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the next item would fit the leftover of a new bin perfectly
        // and this item fits poorly here, soften the penalty.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the post-residual exactly accommodates the next
    // item, reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading.
    score += 0.15 * open_bins_count as f64 * (post / cap);

    // Late in the stream, dead space matters more (fewer chances to fill it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: make it attractive only if no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; reward it when item is huge relative to residuals.
        let tight_elsewhere = mean_residual < (item_size as f64) * 1.15;
        let mut nb = 40.0;
        if tight_elsewhere {
            nb -= 30.0;
        }
        if fitting_bins_count == 0 {
            nb -= 50.0;
        }
        if post_residual >= next_item_size {
            nb -= 5.0;
        }
        return nb + post_residual as f64 * 0.1;
    }

    // --- 2-step lookahead: reward post_residual matching next_item_size exactly ---
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect chain (post_residual == next_item_size): strong reward.
        if gap == 0.0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits after this placement: reward scaled by closeness.
            score -= 25.0 * (1.0 - gap / 40.0).max(0.0);
        } else {
            // Next item will NOT fit in residual: penalize dead space creation.
            score += gap * 0.6;
        }
    }

    // Reward tight fits (small post_residual) relative to mean residual.
    let tightness = post_residual as f64 / bin_capacity as f64;
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.4;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Discard unusable slivers (dead space below minimum item size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Extra reward if next item nearly fills the remaining space.
            let gap = post_residual as f64 - next_item_size as f64;
            if gap <= 10.0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: penalize leaving large dead space.
            let waste = post_residual as f64;
            if waste < next_item_size as f64 && waste > 20.0 {
                score += 8.0;
            }
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 25.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when plenty of open bins exist that fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are more acceptable late in the stream when mean residual is fragmented.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 25.0 - 20.0 * fragmentation - 10.0 * progress;
        // If many bins fit the item, discourage opening a new one.
        score += 3.0 * fitting_bins_count as f64;
    }

    // Mild penalty for spreading residual too high relative to the mean.
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Prefer consolidating into fewer bins early on.
    if !is_new_bin {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = x * x * (1.0 - x) * (1.0 - x); // smooth bump favoring mid-range residuals
    let coupling = poly * (0.5 + 2.0 * progress);

    let mut score = pr;

    // Penalize large post residuals more as the stream progresses (waste compounds late).
    score += (pr * pr / cap) * (0.3 * progress);

    // Reward tight fits (small post residual) with a smooth quadratic bonus.
    score -= (1.0 - x) * (1.0 - x) * 8.0;

    // Coupled polynomial term.
    score -= coupling * 10.0;

    // Last-chance bin: strong reward to avoid opening new bins unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits into resulting post residual.
    if next_item_size > 0 {
        let fits_next = if (post_residual as f64) >= next_item_size as f64 { 1.0 } else { 0.0 };
        let tight_next = 1.0 - ((post_residual as i64 - next_item_size as i64).abs() as f64) / cap;
        score -= fits_next * (4.0 + 6.0 * tight_next) * (0.5 + progress);
    }

    // Prefer bins with below-mean residual (denser bins) via smooth coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (2.0 + 3.0 * progress);

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 2.0 + 0.5 * open_bins_count as f64 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into a
    // "dead zone" (small, unusable slivers) are penalized via modulo classes.
    let pr = post_residual;
    if pr > 0 {
        let mod10 = pr % 10;
        // residuals like 1..9 (non-multiples of 10) are harder to fill later
        score += (mod10 as f64) * 1.5;
        // tiny slivers are pure dead space
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 15.0;
        }
        // harmonic quarter classes of capacity
        let quarter = (cap / 4.0) as u32;
        if pr >= quarter && pr < 2 * quarter {
            score -= 8.0; // sweet spot: fits mid-size future items
        } else if pr >= 2 * quarter {
            score -= 4.0;
        }
    } else {
        // perfect fit: strongly reward
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item can slot in: reward, more so for tighter coupling
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 - slack * 0.3;
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += ((next_item_size - pr) as f64) * 0.2;
        }
        // harmonic class of next item: multiples of 10 pack well anywhere
        if next_item_size % 10 == 0 {
            score -= 5.0;
        }
    } else {
        // last item: just minimize residual
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer keeping item in an existing bin unless the
    // existing fit is bad. Empty-bin call has bin_residual == bin_capacity,
    // so post_residual == capacity - item_size, which is naturally large;
    // add a fixed handicap so only genuinely poor fits trigger a new bin.
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if item is large (> half capacity), a fresh bin is reasonable
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Stream progression: early on, allow more bins (exploration); later,
    // consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (mean_residual / cap.max(1.0));

    // Many open bins with high mean residual: encourage using slack bins
    if open_bins_count > 2 && mean_residual > cap * 0.5 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.09;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match bonus: next item exactly fills this bin afterwards.
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Penalize leaving residual that neither fits next item nor is tiny.
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0; // dead space relative to lookahead
        }
        // Reward residual that can still hold next item.
        if post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize opening a new bin unless residual is unusable for typical items.
    if bin_residual == bin_capacity {
        score += 70.0 * (post_residual as f64 / bin_capacity as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin is fine if it accommodates lookahead too
        }
    }

    // Late in stream: be greedier, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    // Small absolute waste bonus.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Small dead space is still good — near-perfect fill.
        score -= 10.0 - post_residual as f64;
    }

    // Penalize creating dead space that the next item could not use anyway.
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u64) < next_item_size as u64 {
            // Dead space too small for the lookahead item — extra penalty,
            // but soften if it's tiny (unavoidable).
            score += (next_item_size as f64 - post_residual as f64) * (0.3 + 0.4 * progress);
        } else {
            // Next item fits in the leftover: reward this bin.
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // Many alternatives: mild penalty to prefer the best-fit among them.
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Prefer bins whose residual is close to the item (best-fit style),
    // coupled with global mean residual state.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += residual_gap * 0.1;

    // Prefer bins that are already relatively full (small residual),
    // scaled by how fragmented the global state is.
    let fragmentation = (mean_residual - bin_residual as f64).abs();
    score += fragmentation * 0.05;

    // Early in the stream: allow spreading to keep flexibility (mild bonus
    // for using emptier bins); late: strongly prefer tight consolidation.
    score -= (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64) * 3.0;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and no good fit exists, or
    // early when spreading is cheap.
    if bin_residual == bin_capacity {
        let waste_if_open = bin_capacity as f64 - item_size as f64;
        let mut new_bin_score = waste_if_open;
        // If this bin is the only fitting option, opening new is wasteful.
        if fitting_bins_count == 1 {
            new_bin_score += 40.0;
        }
        // If lookahead item is large, a fresh bin can host it later — mild bonus.
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_score -= 4.0;
        }
        // Late in the stream, opening new bins is costly.
        new_bin_score += progress * 15.0;
        // If many bins are open and fragmented, a fresh bin adds order early on.
        new_bin_score -= (1.0 - progress) * (open_bins_count as f64).ln().max(0.0) * 2.0;
        // Keep the new-bin score comparable to real-bin scores.
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress = progress.clamp(0.0, 1.0);

    // Normalized post-residual and its non-linear (quartic) waste profile:
    // small residuals are valuable, mid residuals are dead-space prone.
    let r = post / cap;
    let waste = r * r * (1.0 - r) * (1.0 - r); // peaks when r ~ 0.5 (unusable slack)

    let mut score = post * (1.0 + 0.35 * progress) + 40.0 * waste;

    // Penalize the brand-new empty bin candidate smoothly; allow it when the
    // item fits poorly everywhere else (few fitting bins) or late in stream.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let escape = (fitting_bins_count.max(1) as f64).ln();
        score += 18.0 + 25.0 * (1.0 - progress) - 12.0 / escape;
    } else {
        // Last-chance bonus: if this is the only bin that fits, use it hard.
        if fitting_bins_count == 1 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score -= 3.0 / fitting_bins_count as f64;
        }
    }

    // Tight-fit reward: item consuming most of the bin is excellent.
    let fill = item / cap;
    score -= 20.0 * fill * fill;

    // Lookahead coupling: prefer leaving residuals that still admit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = (post - nxt) / cap;
            score -= 8.0 * (1.0 - 4.0 * gap * gap).max(0.0);
        } else {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Mean-residual coupling: diverging from the fleet average is mildly penalized,
    // keeping residuals homogeneous for future items.
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual mod capacity quantized into
    // "usable" vs "dead" zones. Residuals that are small but reusable (<= 20)
    // are penalized gently; large residuals are naturally attractive.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold class 0..=10
    match class {
        0 => score += 8.0,          // 0..9: near-perfect fill, tiny dead space
        1 => score += 14.0,         // 10..19: awkward sliver
        2 => score -= 3.0,          // 20..29: still fits small items
        3 => score -= 6.0,          // 30..39: good zone
        4 => score -= 10.0,         // 40..49: prime reuse zone
        5 => score -= 9.0,
        6 => score -= 7.0,
        7 => score -= 5.0,
        _ => {}
    }

    // Modulo coupling: if post_residual is congruent to a common item size
    // (multiples of 5), a future item can exactly fill it -> reward.
    if pr > 0 && pr % 5 == 0 && pr <= 80 {
        score -= 6.0;
    }
    // Exact-fill lookahead: next item exactly consumes the post residual.
    if next_item_size > 0 && next_item_size == pr {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // Next item fits in the leftover: reward proportionally.
        score -= 4.0 + 10.0 * (next_item_size as f64 / pr as f64);
    } else if next_item_size > pr {
        // Leftover unusable for the immediate next item: penalize dead space.
        score += 5.0 + 0.1 * pr as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if post_residual <= 5 {
            score += 10.0; // but a near-exact fill is fine
        }
    }

    // New-bin candidate handling: empty bins should only win when open bins
    // would leave bad residuals. Penalize opening a new bin mildly.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Prefer tighter bins overall: compare residual to mean residual.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Large items should go into the emptiest bins to avoid fragmentation.
    if item_size > 50 {
        score += 0.2 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as f64) * 25.0;
    }
    if post_residual > 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: more open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Mean residual coupling: if this bin's residual is far below mean, it is a poor fit target.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score += (mean_residual - residual_f) * 0.5;
    } else {
        score -= (residual_f - mean_residual) * 0.3;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 60.0;
        } else {
            score -= 20.0;
        }
    }
    // If next item would be blocked by a tiny post-residual, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 30.0;
    }

    // New-bin candidate: attractive early or when existing bins are fragmented,
    // unattractive when many bins are open late in the stream.
    if bin_residual == bin_capacity {
        let new_bin_base = 60.0 + open_bins_count as f64 * (6.0 + 10.0 * progress);
        score = new_bin_base + item_size as f64 * 0.2;
        // Keep new bins appealing when few fitting bins exist (fragmentation).
        if fitting_bins_count <= 2 && open_bins_count > 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills, but weight by stream progress (late = pack tighter).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score = score * (0.5 + 0.9 * progress);

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 1.0 {
            // Perfect match: next item exactly fills this bin.
            score -= 60.0;
        } else if post_residual as f64 >= nxt {
            // Next item fits here with room to spare; reward proportionally.
            score -= 25.0 * (nxt / (post_residual as f64 + 1.0));
        } else {
            // Dead space relative to next item: penalize unusable gap.
            let gap = nxt - post_residual as f64;
            score += 12.0 * (gap / nxt);
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins),
    // penalize dumping into already-loose bins.
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    score += 0.35 * (post_residual as f64 - mr);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing bins would leave large unusable fragments or no bin fits well.
    if bin_residual == bin_capacity {
        // Neutral default; gets selected only if all open-bin scores are worse.
        score = bin_capacity as f64 * (0.5 + 0.9 * progress);
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 10.0;
        }
        // Encourage new bin when few bins are open early (spread load).
        if open_bins_count <= 2 && progress < 0.3 {
            score -= 5.0;
        }
    }

    // Penalize creating tiny unusable residuals (dead space < smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more strongly as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * (0.5 + progress);

    // Penalize small dead space that nothing can use later; dead space in
    // (0, 10) is nearly unusable given typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.3;
        } else {
            // Next item won't fit here; slight penalty for leaving awkward gap.
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.2;
        }
    }

    // Prefer bins with residual below mean (tighter bins absorb items first),
    // keeping large-residual bins flexible.
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.4;

    // Early stream: mildly encourage opening new bins to build a diverse pool
    // of residuals; late stream: discourage spreading.
    if bin_residual == bin_capacity {
        let new_bin_bias = 8.0 * (1.0 - progress) - 6.0 * progress;
        score += new_bin_bias;
        // Don't open a new bin if an existing bin gives a perfect fit.
        if post_residual == 0 && bin_residual < bin_capacity {
            score += 100.0;
        }
        // Avoid new bin when item is small and many bins can fit it.
        if item_size <= 30 && fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild penalty for crowding when many bins already open.
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its smooth polynomial coupling with progress.
    let post_norm = post / cap;
    let mut score = post_norm * (1.0 + 0.8 * progress) + 0.35 * post_norm * post_norm * (1.0 + 1.5 * progress);

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 0.6 * fit_ratio * fit_ratio;

    // Penalize residual that is dead space: too small for typical future items.
    let dead = (30.0f64 - post).max(0.0) / 30.0;
    score += 0.5 * dead * dead * (0.5 + 0.5 * progress);

    // Last-chance bonus: only one fitting bin, avoid opening new bins.
    if fitting_bins_count <= 1 {
        score -= 0.4 + 0.3 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 0.4 * (1.0 - diff / cap).max(0.0);
    }

    // Mildly discourage scattering across many bins vs. mean residual alignment.
    score += 0.002 * open_bins_count as f64;
    let dev = (mean_residual - post).abs() / cap;
    score += 0.2 * dev * dev;

    // New-bin candidate: penalize so it only wins when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 0.9 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items in real streams often come in
    // size classes; leftover space that is a "nice" fraction of capacity is
    // more reusable. Classify post_residual by integer division thresholds.
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Reward large post_residual (score already = post_residual, lower is better,
    // so subtract a term that grows with how "usable" the leftover is).
    // Harmonic classes: leftover >= 50 (half bin) is highly reusable.
    if post_residual >= bin_capacity / 2 {
        score -= 12.0 + 8.0 * frac;
    } else if post_residual >= bin_capacity / 4 {
        score -= 6.0 + 4.0 * frac;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill: best possible outcome
    } else {
        // small dead space: penalize relative to how dead it is
        score += (1.0 - frac) * 10.0;
    }

    // Modulo arithmetic on post_residual: leftovers that are multiples of common
    // small sizes (10, 20, 25) tend to be filled by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
        if post_residual % 25 == 0 {
            score -= 3.0;
        }
        if post_residual % 20 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; leftover is likely dead if small
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins are crowded or the item is huge.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap; // average slack across open bins
        let pressure = if open_bins_count == 0 { 0.0 } else { 1.0 - crowded };
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Big items prefer fresh bins; small items prefer existing bins.
        let big_item = item_size as f64 / cap;
        let bias = 18.0 * big_item + 15.0 * pressure - 10.0 * (1.0 - progress);
        score = cap - bias; // baseline so it competes fairly
    }

    // Mild preference for tighter bins among comparable fits.
    score -= (bin_residual as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are nearly unusable
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space relative to next item: gap that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than average residual (best-fit flavor)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Slight stream progression bias: early on, keep bins flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: reward bins whose post_residual
    // closely matches the next item size (perfect chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize post_residual that cannot fit the next item (likely dead space)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - (post_residual as f64 / bin_residual.max(1) as f64));
    }

    // Compare post_residual against mean residual: prefer bins tightened
    // toward the average (avoids leaving one bin very full / others loose).
    let pr = post_residual as f64;
    let diff = (pr - mean_residual).abs();
    score += 0.15 * diff;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish default; discourage unless open bins are tight.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // If next item is large and no bin will have room, opening fresh is fine.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 40.0;
        }
    }

    // Late in stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual proportionally.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.6 * tight * (item_size as f64);

    // Last-chance bonus: only one bin fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: penalize opening a new bin, but relax when
    // the item fits no open bin well (large post_residual everywhere)
    // or near the end of the stream when consolidation is pointless.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 55.0;
        // If post_residual here is large, other bins likely fit poorly too.
        penalty -= 0.25 * post_residual as f64;
        // Fewer open bins => cheaper to open a fresh one.
        penalty -= 3.0 * open_bins_count as f64;
        // Early in stream, opening bins is less costly.
        penalty -= 15.0 * (1.0 - progress);
        score += penalty.max(5.0);
    }

    // Lookahead: penalize leaving a residual that cannot fit the next item
    // (wasted dead space), reward residuals that can host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
        // Perfect pairing: this bin takes item AND next item exactly.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: just minimize post_residual, prefer any open bin.
        score -= 10.0;
        if is_new_bin {
            score += 100.0;
        }
    }

    // Prefer bins below mean residual (more crowded bins get priority),
    // keeping emptier bins flexible for future items.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild preference for filling bins with larger residuals to reduce
    // fragmentation across many open bins.
    score -= 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post_residual); late, tolerate slack slightly.
    let coupling = post_norm * post_norm * (1.0 - progress) * 40.0
                 - post_norm * progress * 15.0;
    score += coupling * cap * 0.1;

    // Reward filling bins tightly (small post_residual) with smooth decay.
    score -= (1.0 - post_norm).powi(3) * 12.0;

    // Penalize dead space that can't fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64 / cap;
        score += 8.0 + gap * 25.0;
    }

    // Reward when next item fits exactly into resulting gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild penalty for spreading across many open bins; smooth in mean residual.
    score += 0.3 * open_bins_count as f64 * (1.0 - mean_residual / cap).abs();

    // New-bin candidate: prefer it only if current bin would be left nearly full or very empty.
    if bin_residual == bin_capacity {
        let slack_bias = post_norm.powi(2) * 20.0;
        score += 3.0 + slack_bias - progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // common item sizes (e.g. 10, 20, 25, 50) are reusable "harmonics".
    let pr = post_residual;
    let mut harmonic_bonus = 0.0f64;
    for m in [10u32, 20, 25, 50] {
        if pr % m == 0 && pr > 0 {
            harmonic_bonus += m as f64 * 0.5;
        }
    }
    score -= harmonic_bonus;

    // Penalize small, awkward residuals (dead space): worst zones just below
    // common item sizes. Anything < 10 is unusable dead space.
    if pr < 10 && pr > 0 {
        score += 30.0;
    }
    // Dead zones: residual that no plausible item (1..=100) fills well,
    // e.g. pr in 1..10 or 51..59 style gaps; use integer-division threshold.
    let zone = pr / 10; // coarse decile class
    match zone {
        0 => score += 15.0,          // 0..9 dead
        1 => score -= 5.0,           // 10..19 usable by small items
        2 => score -= 8.0,
        3 => score -= 6.0,
        4 => score += 3.0,           // 40..49 awkward
        5 => score -= 4.0,           // 50..59 half-bin harmonic
        6 => score += 2.0,
        _ => {}
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && pr >= next_item_size {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap < 10 {
            score -= 25.0;
        } else {
            score -= (gap as f64).recip() * 20.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Next item won't fit here: mild penalty proportional to next size.
        score += next_item_size as f64 * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when the
    // item is large relative to capacity or residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + item_size as f64 * 0.2 + fragmentation * 0.3 - progress * 10.0;
        if item_size >= 50 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // room for lookahead pairing in fresh bin
        }
        return score;
    }

    // Tight fit reward: prefer bins where the item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= fill_frac * 15.0;

    // Prefer bins below mean residual (consolidating fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Modulo coupling between item size and residual class
    if bin_residual % item_size.max(1) == 0 && item_size > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (unusable gaps).
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Non-linear penalty on post_residual: small gaps hurt more than large ones
    // once below a useful-size threshold; large residuals are mildly rewarded.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / (bin_capacity as f64);

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bins pressure: penalize bins when many are open, encouraging
    // consolidation into existing bins rather than opening new ones.
    let obp = open_bins_count as f64;
    score += 0.8 * obp.ln().max(0.0);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // into existing bins is poor (large dead space would result).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // If placing here would leave a very tight residual in an existing bin
        // instead, we already penalized that; soften new-bin cost when item is
        // large relative to capacity (hard to place later).
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * item_frac;
        // Lookahead: if next item is large, having a fresh bin may help.
        if next_item_size > 0 {
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            score -= 15.0 * next_frac;
        }
    } else {
        // Existing-bin fit quality: reward using bins whose residual is close
        // to the item size (tight fit).
        let tightness = 1.0 - (post_residual as f64 / bin_residual as f64);
        score -= 20.0 * tightness;

        // Lookahead synergy: if next item could fit the post residual,
        // reward this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // If next item would NOT fit post residual and post residual is small,
        // it's dead space; penalize.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
            score += 15.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins),
    // keeping looser bins available for future items.
    let mr = mean_residual;
    if pr < mr {
        score -= 6.0;
    } else {
        score += 4.0 * ((pr - mr) / bin_capacity as f64);
    }

    // Stream progression: early on, be more willing to open bins (explore);
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this is a perfect chain — reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item could also fit here later; mild reward proportional to fill.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * fill;
    } else if next_item_size > post_residual {
        // Next item won't fit in post_residual: dead space penalty grows with gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.3 * gap;
    }

    // Compare against mean residual: bins below mean residual are "small" bins;
    // placing here consolidates space. Penalize bins far above mean residual.
    let dev = post_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; lookahead can override via the
        // chain bonus above (empty bin post_residual == capacity > item).
        score += 20.0;
        if next_item_size > 0 && (next_item_size + item_size as u32) <= bin_capacity {
            score -= 25.0; // room to chain next item in a fresh bin
        }
    }

    // Slight preference to use more open bins as stream progresses (avoid sprawl).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 + 0.5 * post_residual as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can also host the next item.
            score -= 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere (large post_residual elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 25.0;
        // Early stream: opening bins is cheaper (more future items to fill them).
        new_bin_penalty *= 1.0 - 0.5 * (1.0 - progress);
        // Many open bins with slack: discourage adding another.
        new_bin_penalty += 2.0 * open_bins_count as f64 * mean_residual / bin_capacity as f64;
        // If the item would leave a big hole in any open bin, new bin is less bad.
        new_bin_penalty -= 0.3 * post_residual as f64;
        // If next item is huge, a fresh bin has future value.
        if next_item_size >= 50 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for filling already-open bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Slight global pressure: as mean residual grows, prefer bins below it
    // (concentrate waste) and penalize bins above it (spreading waste).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.1 * diff;
    }

    // Time horizon coupling: late in the stream, be greedy (minimize waste now).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual

    // Non-linear polynomial coupling of post residual with stream progress
    let mut score = post;
    score += 40.0 * x * x * (1.0 - progress);
    score += 25.0 * x * x * x * progress;
    score -= 30.0 * x * (1.0 - x) * (1.0 - progress);

    // Penalize dead space relative to the mean residual of open bins
    score += 0.15 * (post - mean_residual).abs() * (0.5 + progress);

    // Reward tight fits (small post residual)
    score -= 20.0 * (1.0 - x) * (1.0 - x);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (post - nx).max(0.0) / cap;
        score += 50.0 * waste * waste;
        if nx <= post {
            score -= 15.0 * (1.0 - waste);
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * progress;

    // Prefer filling bins more completely as the stream progresses
    score -= 10.0 * (item_size as f64 / cap) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: how "useful" is the leftover space? ---
    // Class bins by leftover space in units of a small item (assume ~10-unit granularity
    // when possible, degrade gracefully for unknown 1..100 distributions).
    let unit = 10u32;
    let post_class = post_residual / unit;              // integer-division harmonic class
    let post_mod = post_residual % unit;                // sub-class remainder

    // Dead-space penalty: leftovers that are too small for anything meaningful.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0;   // tiny unusable slivers are bad
    }

    // Reward "perfect" harmonic classes: post_residual exactly divisible by unit,
    // or exactly zero (perfect closure).
    if post_residual == 0 {
        score -= 40.0;                                  // perfect fit, ideal closure
    } else if post_mod == 0 && post_class >= 1 {
        score -= 8.0 + post_class as f64;               // aligned leftover, reusable
    } else {
        // Misaligned leftover: penalize proportional to how misaligned it is.
        score += post_mod as f64 * 0.8;
    }

    // --- Lookahead coupling (k=2): does the next item fit into the leftover? ---
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportionally to how snugly the next item slots in.
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 + 20.0 * snug;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: leftover becomes potential dead space.
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // --- Last-chance logic: if this is the ONLY bin that fits, prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing leftovers are poor.
        // Base cost of a fresh bin, discounted by stream progress (late items
        // benefit less from hoarding open bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 - 20.0 * progress;
        // If the item leaves a nicely aligned residual in a fresh bin, discount more.
        let fresh_post = bin_capacity.saturating_sub(item_size);
        if fresh_post % unit == 0 {
            new_bin_score -= 10.0;
        }
        // If no open bin fits well (many bins but few fit), opening a new one is fine.
        if open_bins_count > 0 && (fitting_bins_count as f64) < (open_bins_count as f64) * 0.4 {
            new_bin_score -= 12.0;
        }
        score = score.min(new_bin_score.max(5.0));
    }

    // --- Mean-residual coupling: when open bins are generally full, be thrifty ---
    if mean_residual < 15.0 && bin_residual != bin_capacity {
        score -= 10.0; // scarcity: reuse whatever still fits
    } else if mean_residual > 45.0 {
        // Lots of slack across bins: penalize spreading into a bin with big residual
        // only mildly; encourage consolidation into the best-fitting bin instead.
        score += (post_residual as f64) * 0.15;
    }

    // --- Integer-division threshold tiers on post_residual ---
    if post_residual >= 50 {
        score += 5.0;        // huge leftover: wasteful placement of a small item
    } else if post_residual >= 20 {
        score -= 3.0;        // comfortable reusable zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize opening new bins when fitting bins exist (open-bins pressure)
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it before opening a new one
        score -= 20.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mild pressure proportional to number of open bins to consolidate
    score += 0.3 * open_bins_count as f64;

    // Prefer tighter bins relative to the mean residual
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match lookahead: post_residual close to next_item_size is good.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (-gap / 15.0).exp();
    }

    // Penalize dead space too small for any plausible item (min item size 1, but
    // typical items are larger); residual below ~10 is likely wasted.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Favor tight fits: small post_residual relative to bin capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred unless fit is poor.
        score += 120.0;
        // Reward opening a new bin if the current bin would leave large dead space.
        if post_residual > 40 {
            score -= post_residual as f64;
        }
        // If next item would fit perfectly in a fresh bin alongside current item,
        // opening a new bin is attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0;
        }
    }

    // Slight preference for bins below mean residual (keeps large bins available).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Early in stream: be slightly more conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: if the next item fits into this bin's post_residual,
    // reward placing current item here (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.35 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; penalize wasting a large residual.
        score += 0.08 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, opening bins is cheap; late, prefer packing into open bins.
        score += 25.0 - 20.0 * progress;
        // If many open bins already, discourage more.
        score += 1.5 * open_bins_count as f64;
        // If only this new bin fits (fitting_bins_count == 1 means new bin is sole option),
        // the penalty above is acceptable; if other bins fit, extra penalty unless tight.
        if fitting_bins_count > 1 {
            score += 6.0;
        }
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping larger residuals available for bigger items.
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Mild time horizon coupling: as stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small bonus for leaving residuals that match common small item sizes.
    for r in [10u32, 20, 25, 30, 40, 50] {
        if post_residual == r {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) coupling
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, tolerate larger residuals slightly;
    // late in the stream, penalize dead space more aggressively.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * norm_pr * cap * (1.0 - fit_ratio);

    // Reward tight fits (fit_ratio near 1) via smooth sigmoid-like term
    score -= 20.0 * fit_ratio * fit_ratio * fit_ratio;

    // Penalize leaving residual too small for typical items (dead space)
    let dead = if pr > 0.0 { ((20.0 - pr).max(0.0) / 20.0) } else { 0.0 };
    score += 15.0 * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item can fit into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Mild preference for bins below mean residual (balance across bins)
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: penalize opening a new bin unless current residual is large
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - fit_ratio) + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small residue" classes are nearly perfect fits -> reward strongly.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // modulo classes: residues divisible by 10 pair well with item sizes 10..80
        let class = pr % 10;
        score -= match class {
            0 => 18.0,
            5 => 8.0,
            2 | 8 => 3.0,
            _ => 0.0,
        };
        // integer-division thresholds: leftover <= 10 is dead space
        if pr <= 10 {
            score -= 25.0;
        } else if pr <= 20 {
            score -= 10.0;
        } else if pr > 60 {
            score += 6.0; // large waste
        }
    }

    // Fractional fill level: reward high utilization via capacity fractions
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * fill * fill;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            // harmonic class match between next item and leftover
            if pr % next_item_size == 0 {
                score -= 15.0;
            }
            let slack = (pr - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: leftover likely dead space
            score += 4.0 + (pr.min(next_item_size) as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are terrible,
    // but reward it late in the stream or when mean residual is high (fragmented bins).
    if bin_residual == bin_capacity {
        score += 20.0;
        if mean_residual > 40.0 {
            score -= 15.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score -= 5.0; // early stream: fresh bins are cheap
        }
    }

    // Tie-break by tightness relative to mean residual
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals below the minimum item size more softly as they shrink.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits (small but usable leftovers).
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward tight fits proportionally to how much of the bin was consumed.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading out; with few open bins, allow opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += pressure * 4.0 * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 15.0 - slack as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual is dead for the lookahead item; penalize.
        score += 12.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing), especially early in the stream.
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate: make opening a new bin costly unless the current
    // item is large relative to capacity or the bin would be nearly filled.
    if bin_residual == bin_capacity {
        let open_bonus = if item_size >= 60 || fill_ratio > 0.6 { -30.0 } else { 45.0 };
        score += open_bonus + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64) * (next_item_size as f64) / (post_residual as f64 + 1.0);
        } else {
            // next item cannot use leftover space: penalize dead space
            score += (post_residual as f64) * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 50.0 + 100.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Small bonus for keeping item_size large relative to residual (dense packing)
    score -= (item_size as f64) / (bin_residual as f64 + 1.0) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: late in the stream, consolidate harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
    let residual_scale = bin_capacity as f64;

    // Reward tight fits: shrink effective post_residual when the fit is snug.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.8 {
        score -= 0.45 * post_residual as f64 * fit_ratio;
    } else if fit_ratio > 0.5 {
        score -= 0.20 * post_residual as f64 * fit_ratio;
    }

    // Penalize dead space relative to mean residual of open bins.
    score += 0.30 * (post_residual as f64 - mean_residual).max(0.0) * (0.5 + 0.5 * progress);

    // Lookahead (k=2): if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_fit = 1.0 - (post_residual - next_item_size) as f64 / residual_scale;
        score -= 8.0 * lookahead_fit;
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item could have fit here if we wasted space: mild penalty.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // More competing bins: prefer bins that stay useful afterward.
    if open_bins_count > 1 {
        score += 0.05 * post_residual as f64 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when the fit into open bins is poor
    // (large post_residual) or the item is big; otherwise discourage.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size >= 50 {
            score -= 10.0;
        }
        if post_residual > 0 && post_residual < 15 {
            score -= 6.0; // opening fresh for a near-perfect big item is fine
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 9.0; // new bin can also serve the next item
        }
    }

    // Late-stream consolidation pressure.
    score *= 1.0 + 0.25 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };

    // Smooth polynomial coupling: reward tight fits with a quartic in fit_ratio
    score -= 60.0 * fit_ratio.powi(4) * (1.0 + 0.5 * progress);

    // Penalize dead space with quadratic in normalized post_residual, growing late in stream
    let norm_pr = pr / cap;
    score += 40.0 * norm_pr.powi(2) * (0.5 + 0.5 * progress);

    // Interaction: post_residual * progress cubic term (prefer closing bins early-late)
    score -= 25.0 * norm_pr.powi(3) * progress;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty when bin residual deviates from mean residual (balance bins)
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap).powi(2);

    // Slight preference for existing bins over opening new ones, stronger early
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual modulo capacity/4 quadrants
    let quarter = bin_capacity / 4;
    let class = (post_residual / quarter.max(1)) as f64;
    score += class * 3.0;

    // Reward near-perfect fits (post_residual in small harmonic classes)
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Modulo-based dead-space penalty: residuals not expressible as sums of
    // common small item sizes are less reusable.
    let m = post_residual % 10;
    if m != 0 {
        score += m as f64 * 0.8;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 15.0 + (10 - slack.min(10)) as f64;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate unless current fits are bad.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > quarter * 2; // would leave > half empty
        if poor_fit || fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            score += 45.0;
        }
    }

    // Slight preference to fill already-open bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    // Deviation from mean residual: prefer bins below mean (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold typical future
    // items are wasted. Penalize sharply when post_residual falls into the
    // "unusable gap" zone (small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits (waste < 10% of capacity).
    if post_residual as f64 <= 0.10 * bin_capacity as f64 {
        score -= 30.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when the fleet is large.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if the bin's residual is far below the mean,
    // it is already "tight" — favor using it up.
    let tightness = mean_residual - bin_residual as f64;
    score -= 0.3 * tightness.max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward heavily; if next item cannot fit, mild penalty for stranding.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.2 * (post_residual - next_item_size) as f64;
        }
    }

    // New-bin candidate: an empty bin is attractive only when no open bin
    // gives a decent fit. Make the empty bin slightly less attractive than
    // a good existing fit, but better than a poor/stranding fit.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: moderate score; worsens with open-bin
        // count to reuse bins when possible.
        score = 0.5 * bin_capacity as f64 + 2.0 * open_bins_count as f64;
        // Late in the stream, closing out cleanly matters less; slightly
        // favor new bins early when many bins will be needed anyway.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If the next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-match: lookahead item fits with small waste.
    else if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + gap * 0.15);
    }
    // Lookahead item cannot follow into this bin: penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Tight fit reward: little dead space left.
    if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Compare residual against mean residual: prefer bins with less space
    // (denser packing) unless it's a new empty bin.
    if bin_residual < bin_capacity {
        score -= (mean_residual - post_residual as f64) * 0.5;
    } else {
        // New-bin candidate: mild penalty so it's chosen only when fits are bad.
        score += 6.0 + (mean_residual - post_residual as f64).abs() * 0.1;
    }

    // Late in the stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: bonus if the next item exactly fits the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item cannot fit here; penalize proportionally to wasted space.
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless the
    // current item is large relative to residual space of open bins or the
    // stream is early and many items remain.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size as f64) / cap;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 22.0 * pressure - 10.0 * big_item * (1.0 - progress);
    }

    // Global state: when many bins are open with high mean residual, prefer
    // consolidating into fuller bins (score bins below mean residual better).
    if open_bins_count > 1 {
        let fullness = 1.0 - (bin_residual as f64) / cap;
        let mean_fullness = 1.0 - mean_residual / cap;
        if fullness > mean_fullness {
            score -= 5.0 * (fullness - mean_fullness);
        } else {
            score += 3.0 * (mean_fullness - fullness);
        }
    }

    // Time-horizon modulation: late in the stream, prioritize exact packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Penalize small dead space quadratically (waste indicator)
    let dead = norm_pr * (1.0 - norm_pr);
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bonus: only bin that fits should be strongly favored
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: favor leaving room for the next item smoothly
    let nis = next_item_size as f64;
    if nis > 0.0 {
        let gap = (pr - nis).abs();
        score += 0.15 * gap * gap / cap;
    }

    // Mild penalty for proliferation of open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - norm_pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward (dead space zero)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Classify post_residual into harmonic classes via integer division thresholds
    let class = post_residual / 10; // classes 0..10
    match class {
        0 => score -= 50.0,                    // tiny waste, near-perfect
        1 => score -= 20.0,                    // good
        2 => score -= 8.0,
        3 | 4 => score += 5.0,                 // mediocre residual band
        5 => score += 15.0,                    // half-full: ambiguous zone
        6 | 7 => score += 8.0,
        8 | 9 => score -= 10.0,                // large residual still usable
        _ => {}
    }

    // Modulo arithmetic on post_residual: divisible residuals pair well with
    // common item sizes (10,20,25,50 classes)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does next_item_size fit the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact or harmonic match with next item is very desirable
            if next_item_size == post_residual {
                score -= 120.0;
            } else {
                score -= 25.0;
                // reward if post_residual - next_item_size lands in a good class
                let nxt = post_residual - next_item_size;
                if nxt % 10 == 0 {
                    score -= 15.0;
                }
            }
        } else {
            // next item cannot use the residual: penalize wasting space
            score += 10.0;
            // extra penalty if residual is small dead space (unusable for typical items)
            if post_residual < 10 {
                score += 30.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits (high post_residual waste or unusable residuals)
    if bin_residual == bin_capacity {
        // base penalty so new bins are not opened frivolously
        score += 40.0;
        // but if existing bins are fragmented (high mean residual spread),
        // opening fresh becomes attractive
        if mean_residual < 0.35 * cap {
            score -= 20.0;
        }
        // large items deserve a fresh bin when few bins fit them
        if item_size > 60 && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // late in the stream, consolidate rather than open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Prefer tighter bins among open bins (small residual relative to mean)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Mild pressure against proliferating many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Items are 1..=100; treat gaps below 10 as pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward bins that can also host the next item (lookahead synergy).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // over spreading; with few bins, mildly favor tight fits anywhere.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Prefer bins whose residual is already below average (consolidate slack).
    score += ((mean_residual - bin_residual as f64) / bin_capacity as f64) * 15.0;

    // Late in the stream, tighten up: dead space costs more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits perfectly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            // Penalize leftovers that are too small to be useful later
            if leftover < 10.0 {
                score += 25.0 - leftover * 2.0;
            } else {
                score -= leftover * 0.15;
            }
        } else {
            // Next item doesn't fit here; penalize more if gap is small (dead space)
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Compare post_residual against mean residual: prefer bins that stay near/below mean
    // (avoid draining the most reusable bin) unless it creates a tight fit.
    let mean_dev = post_residual as f64 - mean_residual;
    score += mean_dev * 0.3;

    // Tight fit reward: small post_residual is good if no lookahead mismatch
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize new-bin candidate slightly when open bins exist with reasonable residual
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + mean_residual * 0.2;
    }

    // Late in stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 0 {
        score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual more than linearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead synergy: if the next item fits into the post residual,
    // reward this bin strongly (perfect chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving awkward small gaps.
        let gap = post_residual as f64;
        if gap > 0.0 && gap < next_item_size as f64 {
            score += 0.5 * (next_item_size as f64 - gap);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins are already open and
    // the global mean residual suggests consolidation is possible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 1.5 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 6.0; // an existing bin could host this item
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling
    // existing bins); late in the stream, allow more freedom to open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score += 10.0 * (1.0 - progress);
    } else {
        score -= 4.0 * progress;
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps residual distribution balanced).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post_residual (tight fit)
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (superlinear).
    let norm_pr = pr / cap;
    let dead_penalty = norm_pr * norm_pr * (1.0 + 3.0 * progress) * cap * 0.5;
    score += dead_penalty;

    // Reward near-perfect fits smoothly (post_residual close to 0).
    let perfect_fit_reward = (1.0 - norm_pr).powi(6) * 8.0;
    score -= perfect_fit_reward;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        // Mild penalty when many bins compete: encourage consolidation.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = pr - nxt;
        if slack >= 0.0 {
            let fit_quality = 1.0 - (slack / cap);
            score -= 6.0 * fit_quality * fit_quality;
        } else {
            // Smooth penalty for blocking the next item.
            let gap = (-slack / cap).min(1.0);
            score += 5.0 * gap * gap;
        }
    }

    // Mean residual coupling: penalize bins far from the mean residual
    // (smooth deviation term) to keep residual distribution homogeneous.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    // New-bin candidate handling: empty bin gets a smooth adaptive offset.
    if bin_residual == bin_capacity {
        // Prefer new bin late in stream or when few bins fit the item;
        // discourage opening new bins early when consolidation is possible.
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 10.0 - 8.0 * progress - 2.0 * open_pressure;
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
