    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic match: next item leaves another class-aligned residual
            let nr = post_residual - next_item_size;
            if nr % 25 == 0 || nr % 10 == 0 {
                score -= 10.0;
            }
            score -= (next_item_size as f64) * 0.2;
        } else {
            // next item won't fit here; slight penalty for hoarding space
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer existing bins unless residual is very tight.
    if bin_residual == bin_capacity {
        score = c * 0.75 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Phase-based pressure: late in stream, consolidate aggressively.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= phase * (bin_residual as f64) * 0.1;

    // Prefer tight fits relative to mean residual state.
    if (pr - mean_residual).abs() < 5.0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harder than large residuals (dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 5.0;

    // Open-bin pressure: fewer open bins => prefer filling existing bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // New-bin candidate: penalize opening a new bin mildly unless residual is large.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.2;
    }

    // Progress pressure: later in stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: 2-step lookahead matching — reward when next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: residual exactly matches next item -> big reward.
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                // Partial reward scaled by how well the next item consumes the remainder.
                let fill_after_next = (post_residual - next_item_size) as f64;
                score -= 25.0 * (1.0 - fill_after_next / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize leaving dead space relative to next item.
            score += 10.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer minimal post residual.
        score += 5.0;
    }

    // Tight fits are good: reward small post_residual relative to mean residual.
    let mean_post = mean_residual - item_size as f64;
    if mean_post > 0.0 {
        score -= 8.0 * (mean_post - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large or existing bins are too full.
        score += 40.0 + item_size as f64 * 0.3;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // If mean residual is large, existing bins are usable -> discourage new bin.
        score += mean_residual * 0.2;
        // Late in stream, prefer reusing bins.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        // Reward reusing bins that are already partially filled (compactness).
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // Penalize creating tiny unusable residuals (dead space), except when next item matches.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * (post_residual as f64 / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize small-but-nonzero dead space (unusable gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it heavily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward if the next item fits the post residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 15.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0 * (open_bins_count as f64).ln().max(1.0);

    // Compare against mean residual: bins below mean residual are "fuller" and favored.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight preference for opening a new bin early in the stream vs. late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more late in the stream, reward early.
        score += 10.0 + 40.0 * progress;
        // But if it's a big item and nothing fits well, new bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic penalty on post_residual (dead space), modulated by progress.
    let mut score = norm_pr * (1.0 + progress * norm_pr);

    // Smooth interaction: item fill ratio vs residual — reward tight fits.
    score -= 2.0 * norm_item * (1.0 - norm_pr) * (1.0 + 0.5 * progress);

    // Cubic coupling of residual with stream progress: late in stream, waste is costlier.
    score += progress * norm_pr * norm_pr * norm_pr * 3.0;

    // Lookahead: if next item fits the post residual, reward this placement smoothly.
    let lookahead_fit = if next_item_size > 0 && post_residual >= next_item_size {
        (norm_next * (norm_pr - norm_next + 0.5)).max(0.0)
    } else {
        0.0
    };
    score -= 1.5 * lookahead_fit;

    // Scarcity pressure: when few bins can fit, favor using this one.
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= scarcity * (1.0 + progress);

    // Mean residual alignment: prefer bins near the mean residual (smooth gaussian-like term).
    let dev = (pr - mean_residual) / cap;
    score += 0.5 * dev * dev;

    // Open bins pressure: many open bins → prefer filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.05 * (1.0 - norm_pr);

    // New-bin candidate: penalize opening a fresh bin unless residual is large relative to item.
    if bin_residual == bin_capacity {
        score += 0.8 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse if it cannot
    // accommodate small item classes (sizes 1..100). Class = post_residual mod 10.
    let pr = post_residual;
    let class = pr % 10;
    // Residuals in "harmonic" classes divisible by 10 or 5 are more reusable
    let harmonic_bonus = match class {
        0 => 25.0,
        5 => 12.0,
        2 | 4 | 6 | 8 => 5.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Penalize small unusable dead space (cannot fit even mid-size items)
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let exact_next = (next_item_size == pr) as f64;
        score -= 60.0 * exact_next + 15.0 * (next_item_size as f64 / 100.0);
        // Harmonic match: next item leaves a multiple-of-10 residual again
        if (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > pr {
        // next item cannot follow here; penalize proportionally
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Progress-aware tightening: late in the stream, prefer tighter fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    // Prefer filling bins whose residual is far below mean (consolidate)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Many open bins: encourage closing them out by filling small residuals
    if open_bins_count > 4 {
        score += 0.1 * open_bins_count as f64 * (post_residual as f64 / 10.0);
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    if bin_residual == bin_capacity {
        let bad_fit = (pr > 0 && pr < 15) || (next_item_size > pr && next_item_size > 0);
        if bad_fit {
            score -= 120.0;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // Unusable dead space (min item size assumed ~1, but tiny gaps are hard to fill)
        score += 40.0 * (10.0 - pr) / 10.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Usable leftover: mild reward proportional to how well next item could fit.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // leaves room for the lookahead item
        } else if next_item_size > 0 {
            score += 0.35 * (next_item_size as f64 - pr).min(30.0);
        }
    }

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual differs from average
    // (best-fit style targeting) — a bin much tighter than average is precious.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a fresh bin; make it competitive with poor fits.
        score = 55.0 + 1.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large item now, similar/larger next: fresh bin reasonable
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits elsewhere: new bin is mandatory
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), with non-linear penalty
    // for mid-range dead space that is too big to be useful but too small to waste.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 15.0; // tiny unusable sliver
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect chain: next item exactly fits
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to how tight
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving large leftovers
            score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }

        // Bonus if both current and next item nearly fill the bin
        if item_size + next_item_size as u32 == bin_residual {
            score -= 40.0;
        }
    }

    // Compare against mean residual: bins with residual close to mean are
    // "typical" targets; prefer placing into bins with residual below mean
    // (consolidating fragmentation) when the fit is tight.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: rely on tightness primarily
        score += 0.0;
    }

    // Mild penalty for opening new bins when many bins are already open
    // and this bin is empty (new-bin candidate gets natural high post_residual,
    // so only override when it's genuinely attractive).
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // Exception: large items (>60) may justify a fresh bin
        if item_size > 60 {
            score -= 45.0;
        }
    }

    // Slight stream-progression pressure: later in stream, favor closing bins tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 6.0 * tightness;

    // Penalize dead space: post_residual too small for any future item (min size 1 assumed, but
    // penalize very small leftover that wastes capacity).
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if post_residual < 10 {
            score += 8.0 * (1.0 - waste_ratio * 10.0).max(0.0);
        }
    } else {
        // Perfect closure of the bin is ideal.
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to leftover gap.
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so we prefer
    // reusing open bins with good fits, but not so large that a bad fit wins.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * open_bins_count as f64;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating
    // into bins with residual below mean (reduce fragmentation).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev; // bins with residual below mean get rewarded (dev > 0 lowers score)
    }

    // Time horizon: late in the stream, be more conservative about opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr + 0.5 * norm_pr * norm_pr);

    // Tight fits are rewarded quadratically
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space below next item size (smoothly)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 15.0 * gap * gap;
        // Reward residual that exactly accommodates next item
        let match_closeness = 1.0 - ((pr - next_item_size as f64).abs() / cap).min(1.0);
        score -= 8.0 * match_closeness * match_closeness * (1.0 + progress);
    }

    // Last-chance bin bonus (smooth in fitting count)
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress) * norm_pr;

    // Small residual entropy term: penalize very small unusable residuals smoothly
    score += 6.0 * (1.0 - (pr / (cap * 0.5)).min(1.0)) * (1.0 - norm_pr).max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "composable" the leftover space is.
    // Residuals divisible by small integers (10, 20, 25, 50) pair well with
    // common item sizes, so reward them; prime/awkward residuals are penalized.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 {
            score -= 12.0;
        } else if pr % 25 == 0 {
            score -= 8.0;
        } else if pr % 20 == 0 {
            score -= 6.0;
        } else if pr % 10 == 0 {
            score -= 4.0;
        } else if pr % 5 == 0 {
            score -= 1.5;
        }
        // Dead-space penalty: residual too small for the smallest plausible item
        if pr < 5 {
            score += 25.0;
        } else if pr < 10 {
            score += 10.0;
        }
    } else {
        // Perfect fit: best possible outcome
        score -= 40.0;
    }

    // Lookahead coupling: reward when next_item_size exactly divides or fits
    // into the post-residual (harmonic continuation of the packing).
    if next_item_size > 0 {
        if pr >= next_item_size {
            if pr % next_item_size == 0 {
                score -= 10.0;
            } else if (pr - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
            // penalize if next item would leave an awkward class behind
            let nr = pr - next_item_size;
            if nr > 0 && nr < 10 {
                score += 6.0;
            }
        } else {
            // next item cannot use this bin anyway; slight penalty for wasting
            // a flexible large residual on a small gain
            score += pr as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would create large dead space.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * mean_residual;
        score += 20.0;
        if pressure > 0.0 && (post_residual as f64) < pressure * 0.5 {
            score -= 10.0;
        }
    }

    // Stream progression: early on, keep bins flexible (favor larger residuals);
    // late in the stream, prioritize tight fits aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;
    score -= (1.0 - progress) * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    // Fractional capacity tie-break: prefer bins whose fill level is near
    // harmonic fractions of capacity (1/2, 3/4).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if (fill - 0.5).abs() < 0.05 || (fill - 0.75).abs() < 0.05 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 3.0;
    } else {
        // Larger residuals are more reusable; reward mildly.
        score -= 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size > post_residual {
            // Next item cannot use leftover; dead space likely.
            score += 15.0;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64) * 0.5;
    } else {
        score -= (open_bins_count as f64).sqrt() * 1.5;
    }

    // Prefer filling bins below mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect chained fit).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if diff == 0.0 {
            score -= 40.0; // perfect lookahead match: place here
        } else if post >= next {
            // next item fits after this placement; reward closeness
            score -= (20.0 * (1.0 - diff / bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot fit in the leftover: penalize dead space
            score += 8.0 + 0.1 * diff;
        }

        // Bonus if the next item exactly fills the bin after this placement chain
        if item_size as f64 + next == bin_residual as f64 {
            score -= 25.0;
        }
    }

    // Penalize creating tiny unusable slivers (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Reward bins that are tighter than the current average (good consolidation),
    // penalize bins that are unusually loose.
    let post_f = post_residual as f64;
    score += 0.3 * (post_f - mean_residual);

    // Early in the stream, be more willing to open fresh bins for large items;
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus progress-scaled reluctance.
        score += 10.0 + 30.0 * progress;
        // Opening a new bin is attractive if the item leaves a residual that
        // matches the next item (start a bin tailored to the lookahead).
        if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
            score -= 35.0;
        }
    }

    // Slight preference for bins with low open count pressure (fewer bins = better)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward chains: lookahead item fits exactly into the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.35 * next_item_size as f64 + 8.0 * (1.0 - progress);
    }
    // Penalize placements that strand the lookahead item (it won't fit here afterwards)
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Deviation from mean residual: prefer bins whose fill state matches the fleet average
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // New empty bin candidate: usually expensive, but cheaper for large items or early stream
    if bin_residual == bin_capacity {
        let large_item_bonus = 0.6 * item_size as f64;
        score += 55.0 - large_item_bonus + 25.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Mild bonus for near-perfect fills
    if post_residual < 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, prefer tight fits less aggressively (keep bins flexible);
    // later, strongly reward minimal post-residual.
    let tightness = norm_pr * norm_pr; // quadratic waste penalty
    let progress_coupling = (1.0 - progress) * (1.0 - progress);
    score += 30.0 * tightness * (0.5 + 0.5 * progress_coupling);

    // Cubic interaction: post residual vs item size ratio
    score += 8.0 * norm_pr * norm_pr * norm_pr * (1.0 - norm_item);

    // Reward bins whose leftover can plausibly fit the next item (smooth, not piecewise)
    let next_fit_margin = (norm_next - norm_pr).abs();
    score -= 12.0 * (1.0 - next_fit_margin.min(1.0)) * (1.0 - progress * 0.5);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - tightness);
    }

    // Mean residual context: penalize bins far from the mean (smooth quadratic)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Crowding: many open bins -> encourage consolidation into existing bins
    let crowd = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).powi(2);
    score -= 15.0 * crowd * (1.0 - norm_pr);

    // New-bin candidate: empty bin gets a mild penalty unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 6.0 + 40.0 * (1.0 - norm_item) * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and integer-division bands
    let pr = post_residual;
    let band = pr / 10;          // coarse harmonic band
    let residue = pr % 10;       // fine residue class

    // Perfect fits are gold
    if pr == 0 {
        score -= 1000.0;
    }
    // Small residues are near-perfect fits: reward quadratically
    if residue == 0 {
        score -= 40.0;
    } else {
        score -= 40.0 / (residue as f64);
    }

    // Penalize post_residuals that are "dead zones": too small for typical items (1..100 unknown, assume >=10)
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr >= 10 && pr <= 20 {
        // usable but tight — mild penalty scaled by band
        score += 10.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: reward, more if it nearly fills the bin
            let nxt_post = pr - next_item_size;
            if nxt_post == 0 {
                score -= 300.0;
            } else {
                score -= 30.0 + (nxt_post as f64) * -0.2; // tighter next fit is better
            }
        } else {
            // next item won't fit here: penalize proportionally to overflow
            score += 0.5 * ((next_item_size - pr) as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // early stream: consolidation preferred; late stream: new bins more acceptable
        let new_bin_penalty = 120.0 - 40.0 * progress;
        // if item is huge relative to capacity, opening fresh bin is fine
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 50.0;
        score += new_bin_penalty - big_item_bonus;
    }

    // Prefer bins below mean residual (consolidate fragmented space)
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Slight preference for bins with many siblings (keep bin count low)
    score += 0.5 * (open_bins_count as f64);

    // Integer-division threshold: bins whose residual is in [50,100) band are attractive
    if band >= 5 && band < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0; // leaves a gap the next item cannot use
        }
        // Perfect two-item packing: residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow consolidation into tight fits rather than opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * (1.5 - progress);

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { (post_residual as f64).min(40.0) };
        let tight_new_fit = (item_size as f64 / bin_capacity as f64).powi(3) * 50.0;
        score += 15.0 + desperation + pressure * 2.0 - tight_new_fit;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Penalize dead space that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Compare residual against mean residual: prefer tighter bins
    score -= (mean_residual - bin_residual as f64).clamp(-10.0, 10.0) * 0.8;

    // Last-chance bin bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New bin candidate: penalize opening unless residual is large and nothing fits well
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space: post_residual too small for the smallest plausible item (size 1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; slight penalty for wasting large residual.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // As stream progresses, prefer reusing bins more strongly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins are open and mean residual is large, discourage new bins.
        score += (open_bins_count as f64).ln1p() * 4.0;
        if mean_residual >= item_size as f64 {
            score += 25.0;
        }
        // If only one fitting bin exists, strongly discourage opening a new bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
        // Small items justify a fresh bin less.
        if item_size <= 30 {
            score += 15.0;
        }
    }

    // Prefer filling bins that are already relatively full (large item_size relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * fill_ratio;

    // Global balance: bins far from the mean residual are slightly penalized (keep residuals uniform).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = post / cap;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    let mut score = post;

    // Smooth non-linear waste penalty: quadratic in post_residual, modulated by progress.
    let waste = (fit_ratio * fit_ratio) * cap * (0.5 + progress);
    score += waste;

    // Dead-space term: cubic interaction of post_residual with mean residual gap.
    let gap = (mean_residual - post).abs();
    score += (gap / cap) * (gap / cap) * cap * 0.3;

    // Last-chance bonus: strongly favor the only fitting bin (subtract).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= cap * (1.0 + progress);
    }

    // Lookahead coupling: reward if next item fits into post_residual (smooth logistic-like).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0) / cap;
        score += fits_next * cap * 0.4; // leftover after next item
        let next_fits = if nxt <= post { 1.0 } else { 0.0 };
        score -= next_fits * cap * 0.6 * (1.0 - progress * 0.5);
    }

    // Congestion penalty: many open bins with large residuals -> prefer filling existing.
    let congestion = (open_bins_count as f64).ln().max(0.0);
    score += congestion * (mean_residual / cap) * 2.0 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless it enables a near-perfect fit later.
    if is_new_bin {
        let base_penalty = cap * (1.2 + 0.8 * (1.0 - progress));
        let perfect_fit = (1.0 - fit_ratio) * cap; // 0 when empty bin => large reward potential
        score += base_penalty;
        // Empty bin post_residual == cap; if item is large relative to cap, opening is fine.
        let large_item = (item_size as f64 / cap).powi(3) * cap;
        score -= large_item * (0.5 + progress);
        let _ = perfect_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into "composable" classes
    // (small residuals likely fillable by future items), penalize awkward mid-range dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries via integer division on post_residual
    let class = post_residual / 10; // 0..=10 harmonic classes
    match class {
        0 => score -= 25.0,            // near-perfect fill
        1 => score -= 15.0,            // excellent
        2 => score -= 8.0,             // good
        3 | 4 => score -= 2.0,         // moderate
        5 | 6 => score += 6.0,         // awkward dead zone
        7 | 8 => score += 10.0,        // large waste
        _ => {}                        // fresh bin class
    }

    // Modulo coupling: residuals divisible by common item sizes are reusable
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 3 == 0 { score -= 1.5; }
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: penalize proportionally to wasted opportunity
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { (mean_residual / cap).clamp(0.0, 1.0) } else { 0.0 };
        score = cap * 0.85 + 20.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 20 {
            score -= 10.0; // current bins too small for lookahead too
        }
    }

    // Progress term: later in stream, be slightly more frugal with open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are small and thus hard to reuse
    // are heavily penalized. Treat residuals in (0, 10] as near-dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits: perfect fill or near-perfect fill is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item can't use the leftover gap -> dead space likely.
        score += 8.0;
    }

    // Open-bin pressure: penalize placements into bins when many bins are open,
    // encouraging consolidation; but relax pressure late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 - 1.5 * progress);

    // Last-chance bin: strongly favor using the only bin that can fit the item,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mean residual coupling: if this bin's post residual is far below the mean,
    // we are compacting well; reward it slightly.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make opening a new bin mildly attractive only when the
    // item is large relative to residual (poor fit elsewhere is implied by other scores),
    // but default new-bin score is high (post_residual = capacity - item is large),
    // so no explicit bonus needed; add small penalty to keep consolidation preferred.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 25.0; // perfect 2-step chain
        } else {
            score -= 15.0 * (-diff / 20.0).exp();
        }
        // Penalize if next item cannot fit into post_residual (dead-end)
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when no good fit exists
    if bin_residual == bin_capacity {
        score += 18.0;
        // Opening a new bin is attractive if lookahead chains perfectly from full capacity
        if next_item_size > 0 {
            let chain = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() as f64;
            if chain == 0.0 { score -= 30.0; }
        }
    }

    // Early stream: be more selective, later: pack greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize small unusable dead space (post_residual too small for typical future items).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: only one bin can fit this item -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins whose residual is below the mean residual (consolidate emptiness).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Early in stream: encourage opening new bins / spreading; late: consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer early, or when no good fit exists among few bins.
        let new_bin_bonus = 12.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));
        score -= new_bin_bonus;
        // Penalize opening a new bin when an existing bin would end up nearly empty.
        if post_residual as f64 > mean_residual + 20.0 && fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild penalty for many open bins (fragmentation pressure).
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "large residue class" are more reusable; classes with tiny leftovers
    // create dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled.
    score = post * 0.08;

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Modulo-10 harmonic class: residues divisible by 10 align with common
    // item sizes (items 1..100 often cluster on multiples of 5/10).
    let r10 = post_residual % 10;
    if r10 == 0 {
        score -= 8.0;
    } else if r10 == 5 {
        score -= 4.0;
    } else {
        // Odd small residues are the least reusable.
        score += (r10 as f64) * 0.6;
    }

    // Integer-division thresholds: post_residual bucket via division by 25
    // (capacity fractions 1/4). Larger buckets are more attractive.
    let bucket = post_residual / 25; // 0..4
    score -= (bucket as f64) * 3.0;

    // Lookahead coupling: reward if the next item fits exactly or well into
    // the post residual; penalize if next item is bigger than post_residual
    // (this bin's leftover is likely wasted).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 30.0;
            } else if slack <= 10 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            score += (ni - post).min(50.0) * 0.15;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the fresh bin mildly so tight fits
    // in open bins win, but let it win when open-bin post residuals are tiny.
    if bin_residual == bin_capacity {
        score = 55.0;
        // If the stream is early and few bins are open, opening is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
        score += (open_bins_count as f64) * 0.3;
    } else {
        // Compare against mean residual: bins far above mean are attractive
        // targets (they carry the most slack to absorb).
        score -= (mean_residual - post).clamp(-50.0, 50.0) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space hard (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate: penalize unless current fit is poor or bin count low.
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual >= 40 && open_bins_count < 3 {
            score -= 25.0;
        }
    }

    // Lookahead: avoid blocking a large next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Slight preference for bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward: zero waste is always best
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space penalty scaled by how much the next item overflows
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.8 * overflow;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent existing fits exist
    if bin_residual == bin_capacity {
        let tightness = (post_residual as f64 / bin_capacity as f64) * 100.0;
        score += 60.0 + tightness;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // new bin is fine if it also anticipates the next item
        }
    }

    // Prefer bins below mean residual (consolidate waste into fuller bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, be greedier about closing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: smaller post_residual relative to capacity is already
    // captured by the base term; amplify the tightness gradient.
    score += 0.5 * (post_residual as f64 / cap) * (item_size as f64 / cap) * 10.0;

    // Lookahead: if the next item can still fit after this placement,
    // strongly favor this bin (keeps future options open).
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 8.0 + 6.0 * (1.0 - post_residual as f64 / cap);
    } else if next_item_size > 0 {
        // Penalize leaving a dead zone the next item cannot use.
        let waste = (post_residual as f64).min(next_item_size as f64 - 1.0);
        score += 0.15 * waste;
    }

    // Last-chance bin: if this is the only open bin that fits, prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a fresh bin, more so later in the
    // stream; relax the penalty when the item is large (fewer future chances
    // to pair it) or when global residuals are already fragmented.
    if bin_residual == bin_capacity {
        let mut penalty = 14.0 + 18.0 * progress;
        if item_size >= 60 { penalty -= 6.0; }
        if mean_residual > cap * 0.5 { penalty -= 4.0; }
        score += penalty.max(0.0);
    }

    // Global fragmentation coupling: when many bins are open with high mean
    // residual, mildly discourage spreading into more bins.
    if open_bins_count > 1 {
        score += 0.02 * mean_residual * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 - norm_pr * progress * 25.0
                 + norm_pr * norm_pr * norm_pr * 15.0;
    score += coupling;
    // Penalize dead space that cannot fit the next item (lookahead waste)
    if next_item_size > 0 {
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += waste * waste / cap * 0.8;
        // Reward leaving room for the next item
        if pr >= next_item_size as f64 {
            score -= 6.0 * (1.0 - (pr - next_item_size as f64) / cap);
        }
    }
    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 8.0 * progress;
    }
    // Slight preference for filling bins tighter than the mean residual
    score += 0.15 * (pr - mean_residual);
    // Discard spreading across many bins early on
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);
    // New-bin candidate: make it mildly unattractive unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * mean_residual / cap;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "capacity fraction" band does it fall into?
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Integer-division thresholds: dead space classes.
    // post_residual in [0..9]  : near-perfect fit (reward strongly)
    // [10..29]                 : can host small items (mild reward)
    // [30..49]                 : mid dead zone (neutral)
    // [50..99]                 : large leftover (penalize waste)
    let class: u32 = post_residual / 10;
    match class {
        0 => score -= 25.0,                     // near-perfect packing
        1 => score -= 12.0,                     // small but usable
        2 => score -= 4.0,                      // mediocre
        3 => { /* neutral */ }
        4 => score += 6.0,
        5 => score += 12.0,
        6 => score += 16.0,
        7 => score += 20.0,
        8 => score += 24.0,
        _ => score += 28.0,
    }

    // Modulo arithmetic on post_residual: residues divisible by common small item
    // sizes (10, 20, 25, 50) make the leftover reusable by aligned future items.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 8.0;
    }
    // Odd, prime-ish residues are hard to fill later.
    if pr > 0 && pr % 2 == 1 && pr < 20 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this leftover: penalize proportionally.
            score += 5.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when the current item is large (would leave little dead space anywhere)
    // or when all open bins are crowded (mean residual low).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Large items open fresh bins happily; small items should reuse open space.
        score = 40.0 - 30.0 * item_frac;
        if mean_residual < item_size as f64 {
            score -= 10.0; // no open bin has room anyway
        }
        if open_bins_count == 0 {
            score -= 50.0; // must open the first bin
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Prefer fuller bins overall: bins below mean residual get a nudge.
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0; // dead space up to ~72 penalty
    }
    // Perfect fit rewarded strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // gap likely wasted relative to lookahead
    }

    // Open-bin pressure: prefer spreading when many bins are open,
    // but penalize opening new bins when plenty of capacity exists.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate (empty bin): make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64) * open_bins_count as f64;
        score += 40.0 + pressure * 10.0 - progress * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mild alignment reward: residual close to mean residual keeps bins balanced.
    score -= 0.3 * (mean_residual - post_residual as f64).abs().recip().min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit: dead space zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small dead space that is likely unusable (< 10 typical min item).
        if post_residual < 10 {
            score += 25.0; // tiny unusable gap is worse than moderate gap
        }
        // Reward residual that exactly matches next item size (2-step lookahead).
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 45.0;
            } else if post_residual >= next_item_size {
                // gap that can still host the next item: mild reward proportional to tightness
                let tight = (post_residual - next_item_size) as f64;
                score -= (20.0 * (1.0 - tight / bin_capacity as f64)).max(0.0);
            } else {
                // gap too small for next item: penalize by closeness (wasted potential)
                let miss = (next_item_size - post_residual) as f64;
                if miss <= 20.0 {
                    score += 15.0 * (1.0 - miss / 20.0);
                }
            }
        }
    }

    // Relative-to-mean coupling: prefer bins that are more full than average
    // (packing tight bins first keeps loose bins flexible).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty so open bins win when they fit reasonably well.
        score += 40.0;
        // But if this bin is the last chance or fit is poor, opening a new bin
        // becomes competitive: reduce penalty.
        if fitting_bins_count == 1 {
            score -= 55.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // new bin can host both current and next item comfortably
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for very large leftover in a mostly-empty bin context:
    // prefer placing into bins where item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward for near-exact two-item fill
            let two_fill = (post_residual - next_item_size) as f64;
            score += two_fill / bin_capacity as f64 * 10.0;
        } else {
            // dead space that cannot host the next item
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are already open and fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_pressure = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 18.0 + 20.0 * fit_pressure + 10.0 * (1.0 - progress);
    }

    // Prefer filling bins below the mean residual (consolidate waste).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;
    score -= (bin_residual as f64 - mean_residual).max(0.0) * 0.05;

    // Mild preference for high fill ratio overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += 12.0 * poly * cap * 0.1;

    // Reward tight fits (small post residual), stronger late in stream
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (10.0 + 20.0 * progress);

    // Penalize last-chance bin underuse
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Encourage using bins when many are open
    score -= open_bins_count as f64 * 0.5 * (1.0 - norm_post);

    // Lookahead: if next item fits post residual, reward
    if next_item_size > 0 {
        let fits = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= fits * (8.0 + 10.0 * progress) * (next_item_size as f64 / cap);
    }

    // Mean residual alignment: prefer bins close to mean
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight penalty for opening new bins late
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Lookahead harmony: bin's post_residual exactly matches the next item.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // Next item fits comfortably in the leftover.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.5 * (post_residual - next_item_size) as f64;
    }
    // Next item would NOT fit here: penalize leaving space the stream can't use soon.
    else if next_item_size > post_residual && next_item_size > 0 {
        score += 0.25 * (next_item_size - post_residual) as f64;
    }

    // Harmonic class penalty on dead space: residues 1..=10 are the classic
    // "waste" band for C=100 (complementary classes like 60/40, 51/49).
    let pr = post_residual;
    if pr <= 10 {
        score += (11 - pr) as f64 * 3.0; // tiny slivers are nearly worthless
    } else {
        // Reward post-residuals that belong to useful complement classes:
        // multiples of 10, and half-capacity class (50) are reusable targets.
        if pr % 10 == 0 {
            score -= 4.0;
        }
        if pr == 50 {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Give it a mild bonus for large items but a
    // baseline that open bins with good fits can beat.
    if bin_residual == bin_capacity {
        // Empty-bin score: capacity minus item, softened, plus crowding bonus.
        score = (bin_capacity - item_size) as f64 * 0.9 + 20.0;
        if item_size >= 60 {
            score -= 25.0; // big items are fine to start fresh bins
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 15.0; // discourage bypassing existing fitting bins
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Slight late-stream tightening: waste matters more as stream completes.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item are "dead space" — penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals below the minimum item size (1..100 unknown, assume >= 10 risk zone)
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) beyond the raw linear term.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize "just barely fits" placements that leave a useless sliver.
    if post_residual > 0 && post_residual <= 5 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage fragmenting further,
    // favor filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln1p() * (1.0 + progress);
    score += pressure * 4.0;

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 20.0;
    }
    // If next item almost fits (small miss), slight penalty for blocking it.
    if next_item_size > post_residual && (next_item_size as i64 - post_residual as i64) <= 10 && next_item_size > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (i.e., fuller bins) to concentrate packing.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Brand-new empty bin candidate: penalize unless nothing else is sensible
    // (e.g., very few open bins or current bin is a bad fit).
    if bin_residual == bin_capacity {
        score += 15.0 + pressure * 6.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: penalize bins that would be exactly filled.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or closely) matches the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 35.0;
        } else if post >= nxt {
            // next item fits here afterwards: mild reward, tighter match better
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would NOT fit after this placement: penalize dead space
            score += 8.0 + diff * 0.15;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    // Leaving a residual well below the mean means this bin becomes "closed-like",
    // which is good if it was nearly full; but avoid stranding large residuals.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.05 * mean_gap;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and no open bin fits well.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            // no open bin fits: new bin is necessary
            score -= 30.0;
        } else if fill_ratio > 0.7 {
            // large item: new bin keeps open bins' residuals intact
            score -= 5.0 * fill_ratio;
        } else {
            // small/medium item: discourage wasting a fresh bin
            score += 25.0;
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize large dead space, especially unusable dead space.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.05 * dead;
        // If the next item cannot use the leftover, penalize more strongly.
        if next_item_size > post_residual {
            score += 0.12 * dead;
        } else if next_item_size > 0 {
            // Reward residuals that exactly accommodate the lookahead item.
            if post_residual == next_item_size {
                score -= 8.0;
            } else {
                score -= 3.0 * (next_item_size as f64 / post_residual as f64);
            }
        }
    } else {
        // Perfect fit: strongly favored.
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let crowdedness = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let mean_tight = mean_residual / bin_capacity as f64;
        score += 18.0 * (1.0 - crowdedness) + 10.0 * mean_tight;
        // Late in the stream, opening new bins is costlier.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= 0.08 * next_item_size as f64;
        }
    }

    // Mild pressure toward bins with smaller residuals (best-fit flavor).
    score += 0.03 * (bin_residual as f64 - mean_residual);

    // Time-horizon coupling: early on, be more exploratory (prefer diversity of residuals);
    // late, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.02 * post_residual as f64;
    score -= progress * 5.0 * fill_ratio;

    // Avoid fragmenting across too many open bins when mean residual is high.
    score += 0.01 * open_bins_count as f64 * (mean_residual / bin_capacity.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress
    let post_norm = post / cap;
    let poly = post_norm * post_norm * (1.0 - progress) + post_norm * progress * (1.0 - post_norm);
    score += 20.0 * poly;

    // Penalize dead space when item nearly fills the bin but leaves a sliver
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.5;
    }

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - post_norm) * (1.0 - post_norm) * (10.0 + 30.0 * progress);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: prefer bins whose post_residual still fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - ((post - nxt) / cap));
        } else {
            score += (nxt - post) * 0.6;
        }
    }

    // Prefer bins with residuals below the mean (consolidating fuller bins)
    score += 0.3 * (mean_residual - post);

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: neutral baseline, slightly penalized early, competitive late
    if bin_residual == bin_capacity {
        score = 0.35 * cap + 15.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into 10-wide buckets.
    let class = (post_residual / 10) as f64;
    score += class * class * 0.8; // penalize large dead-space classes superlinearly

    // Perfect / near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward keeping this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 25.0 - tightness * 0.3; // prefer chains where next item fits tightly
    }
    // If next item would NOT fit here, this bin's remainder is likely dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): only attractive when current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2; // bias toward reusing open bins by default
        if post_residual as f64 > mean_residual {
            score += 10.0; // opening a bin with bigger leftover than average is bad
        }
    }

    // Fraction-of-capacity coupling: leftover near multiples of capacity/4 is more reusable.
    let quarter = (bin_capacity / 4) as f64;
    let rem = (post_residual as f64) % quarter;
    let dist = rem.min(quarter - rem);
    score -= (quarter - dist) * 0.15; // reward leftovers close to C/4 multiples

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize tiny unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if next item cannot fit in post residual and this bin had slack.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: more open bins -> favor filling existing ones, avoid new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // Mean residual coupling: if this bin is much tighter than average, prefer it.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // New-bin candidate: make it unattractive unless current bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 35.0 + pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual == bin_capacity {
        // Brand-new empty bin candidate: neutral-ish baseline, penalize slightly
        // unless existing bins are poor fits (handled by last-chance logic below).
        score += 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the
    // next item exactly (chain packing), relative to mean_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            // Penalize post-residuals close to but not matching next item (dead space trap).
            if gap < 10.0 {
                score += (10.0 - gap) * 12.0;
            }
            // Mild reward if next item still fits comfortably (>= next item size).
            if post_residual >= next_item_size {
                score -= 20.0;
            }
        }
    }

    // Compare post_residual against mean residual: leaving much more than the
    // average is wasteful; much less is good space utilization.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless post_residual is tiny dead space).
    if fitting_bins_count == 1 && post_residual != bin_capacity {
        if post_residual <= 5 {
            score += 50.0; // dead space trap, allow new bin instead
        } else {
            score -= 150.0;
        }
    }

    // Small penalty for very small unusable post-residuals (< 10 dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Late in the stream, prefer tighter packing (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += score * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual that no future item can use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { post_residual as f64 };
        score += 0.9 * dead;
    }

    // Lookahead coupling: reward bins whose remainder can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + 6.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual {
        score += 3.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Last-chance bonus: only fitting bin => avoid opening new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Pressure term: many open bins with high mean residual => prefer filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    score -= 8.0 * pressure * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early stream, tolerate new bins; late stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 14.0 * progress + 4.0 * (open_bins_count as f64 / (total_items.max(1) as f64).sqrt());
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    // Non-linear coupling: reward near-perfect fills exponentially.
    if post_residual < 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
