        // and current item is large relative to capacity
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64);
        score += 30.0 * fragmentation;
        // discourage new bin early in stream when consolidation is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // encourage new bin for big items that would leave awkward residues
        if item_size > bin_capacity / 2 && post_residual % 10 != 0 {
            score -= 12.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.5;

    // Fraction-based fine tuning: penalize fractional residuals in (0,10)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Keep frac coupling: reward bins whose residual fraction is near simple harmonics (1/4, 1/2, 3/4)
    let harmonics = [0.25f64, 0.5, 0.75];
    for h in harmonics.iter() {
        if (frac - h).abs() < 0.02 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward using a bin whose residual is well consumed (large fill fraction).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins;
    // a fresh empty bin gets a penalty proportional to open bin count.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 1.5;
    } else {
        score -= 3.0;
    }

    // Lookahead: if next item fits the post-residual exactly or well, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= (1.0 - next_fit / bin_capacity as f64) * 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 4.0; // dead space for the known next item
    }

    // Late in stream, tighten up: waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += score * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: nearly-full bin is ideal
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0; // chain: perfect match for lookahead item
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetical next placement
            score += slack * 0.5;
            if slack <= 5.0 {
                score -= 30.0; // near-perfect two-item chain
            }
        } else {
            // next item cannot fit here: leftover is likely dead space
            score += (post_residual as f64 - slack_floor(next_item_size, post_residual)) * 0.3;
            score += 10.0;
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New empty bin candidate: penalize slightly so it's chosen only when
    // open bins are poor fits, but reward early stream when few bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 10.0 * progress;
        if open_bins_count == 0 {
            score -= 1000.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0; // new bin supports the lookahead chain
        }
    }

    // Mild penalty for wasting large residuals on small items
    if (item_size as f64) < 0.35 * bin_residual as f64 && post_residual > 30 {
        score += 8.0;
    }

    score
}

#[inline]
fn slack_floor(next_item_size: u32, post_residual: u32) -> u32 {
    if next_item_size > post_residual { next_item_size - post_residual } else { 0 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Penalize dead space that no future item (min size 1) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let fill = (next_item_size as f64) / (post_residual as f64);
            score -= 20.0 * fill;
        } else {
            // next item won't fit here; penalize leaving large unusable-ish gaps
            score += 5.0;
        }
    } else {
        // Last item: just minimize post residual.
        score += 0.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // When many bins are open, prefer consolidating into fuller bins
    // (penalize bins with large residuals relative to mean).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap;

    // Time horizon: early in the stream, be more willing to open new bins
    // (spread items); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tight;
    score += (1.0 - progress) * 0.05 * (open_bins_count as f64);

    // Slight penalty for opening a brand-new bin when decent fits exist,
    // unless the item is large and bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / (bin_capacity as f64) } else { 0.0 };
        let new_bin_penalty = 20.0 - 25.0 * fragmentation * progress;
        score += new_bin_penalty.max(-10.0);
        // Large items near the end justify fresh bins.
        if item_size > 50 && progress > 0.5 {
            score -= 12.0;
        }
    }

    // Small bonus for using bins that are nearly full already (high fill ratio).
    let pre_fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * pre_fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let prog_sq = progress * progress;
    let coupling = pr_norm * (1.0 + 0.8 * progress + 0.6 * prog_sq);
    score += 6.0 * coupling;

    // Quadratic waste penalty: dead space grows super-linearly with progress
    score += 0.5 * pr_norm * pr_norm * (1.0 + 3.0 * progress);

    // Reward tight fits more strongly as the stream advances
    let tightness = 1.0 - pr_norm;
    score -= 4.0 * tightness * (0.5 + progress);

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 10.0 * (0.7 + 0.5 * progress);
    }

    // Lookahead: prefer bins whose post_residual fits the next item
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 3.0 * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 1.5 * pr_norm * (1.0 + progress);
    }

    // Mild penalty when this bin is much tighter than the average open bin
    let mean_norm = mean_residual / cap;
    score += 2.0 * (mean_norm - pr_norm).abs() * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless residuals elsewhere are large
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress - 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small residues (dead space) penalized.
    let dead_zone = if post_residual < 10 { 3.0 } else { 0.0 };
    score += dead_zone;

    // Modulo-class bonus: residuals that are "nice" multiples of common item
    // granularities (10, 20, 25, 50) are reusable.
    for g in [10u32, 20, 25, 50] {
        if post_residual % g == 0 && post_residual > 0 {
            score -= 4.0;
        }
    }

    // Integer-division threshold: post_residual bucketed by fifths of capacity.
    let fifth = bin_capacity / 5;
    let bucket = post_residual / fifth;
    score -= bucket as f64 * 1.5;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // penalize leftover after chaining by its harmonic class
            if gap < 10 {
                score += 5.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by overshoot class
            let over = (next_item_size - post_residual) / 10;
            score += over as f64 * 1.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is huge
    // and no tight fit is available.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Tight-fit reward: near-exact fills are excellent.
    if post_residual <= 5 {
        score -= 10.0;
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.05;

    // Spread-awareness: prefer bins below the mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals that are too small to fit
    // even the smallest plausible item are pure waste -> heavy penalty.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 200.0 * (dead_threshold - post_residual) as f64;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Reward residuals that can still host a future item (usable gap).
    if post_residual >= dead_threshold {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this is a chain fit -> strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 80.0 - slack * 0.5;
    }
    // If next item does not fit, small leftovers hurt more.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open,
    // encourage consolidation; but reward opening a new bin when this bin
    // is a poor fit relative to the mean residual.
    let pressure = open_bins_count as f64;
    score += pressure * 2.0;

    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it only if item is large and this stream
        // is early (many items left to justify a fresh bin).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * item_size as f64 / 100.0 * (1.0 - progress);
        score += 25.0 * progress;
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize bins far below mean residual (they waste the consolidation).
    if post_residual as f64 > mean_residual + 20.0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core archetype: aggressive 2-step lookahead matching.
    // Reward bins whose post_residual matches the next item size well.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - look).abs();
        if pr >= look {
            // Next item can also fit here: strongly reward tight two-item packing.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            if gap < 5.0 {
                score -= 15.0; // near-perfect chain bonus
            }
        } else {
            // Dead space relative to lookahead: penalize proportionally to waste.
            score += 0.5 * (look - pr) * (look - pr) / (bin_capacity as f64);
        }
    } else {
        // Last item: just minimize residual.
        score += 0.0;
    }

    // Prefer tight fits relative to the average open-bin residual.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable slivers (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 60.0;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // As stream progresses, slightly discourage bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = base + pressure * 30.0 + 20.0 * progress
            - (if next_item_size > 0 { (bin_capacity as f64 - next_item_size as f64).abs() } else { 0.0 }) * 0.1;
        // If many open bins can fit, opening new bins is wasteful.
        score += 5.0 * fitting_bins_count as f64;
    }

    // Mild bonus for using bins that are already quite full (consolidation).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Slight preference for fewer open bins (compactness pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows as post_residual shrinks.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot follow here; slight penalty proportional to overflow.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // existing bins with good fits, but allow opening when fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = if fitting_bins_count > 0 {
            // Compare mean residual of open bins vs item: poor fits elsewhere -> open new bin.
            ((mean_residual - item_size as f64) / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        score += 15.0 - 20.0 * fit_quality - 5.0 * progress;
    } else {
        // Prefer bins whose residual is close to the mean (balanced packing),
        // slightly penalize outlier bins.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Late in the stream, consolidate: favor bins with smaller residuals overall.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    // Mild penalty when many bins are open: encourage filling existing ones.
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, compactness (small post_residual) is rewarded more strongly.
    let poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score += poly * (pr * pr) / cap * 0.02;
    score -= poly * pr * 0.10;

    // Reward tight fits: item fills most of the bin.
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * fill_ratio * 12.0;

    // Penalize dead space that no typical item can use (post_residual < smallest items).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size > 0 {
        score += 2.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly everywhere else. Base new-bin score on wasted capacity potential.
    if bin_residual == bin_capacity {
        score = cap * 0.5 - poly * cap * 0.15;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: opening is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Mild preference to spread load when many bins are open with high mean residual.
    score -= (mean_residual / cap) * (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual mod 10 bands.
    let post = post_residual;
    let band = post % 10;
    // Residuals in [1..9] are near-dead space unless a future small item fits;
    // residuals divisible by 10 are more reusable (harmonic with capacity C=100).
    if post > 0 {
        if band == 0 {
            score -= 6.0; // harmonic residual, reusable
        } else if band <= 3 {
            score += 8.0; // sliver, likely dead space
        } else {
            score += 3.0;
        }
    }

    // Exact reusability: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // lookahead fits: reward proportionally to how snugly
            let snug = (post - next_item_size) as f64;
            score -= 12.0 - 0.1 * snug;
            // bonus if post_residual becomes exactly consumable by next item
            if post == next_item_size {
                score -= 25.0;
            }
        } else {
            // lookahead cannot use this bin's remainder: penalize if remainder is small
            if post < next_item_size && post > 0 {
                score += 5.0 + (next_item_size - post) as f64 * 0.2;
            }
        }
    }

    // Fraction-of-capacity coupling: item_size classes (harmonic divisors of 100).
    let item_frac = item_size as f64 / cap;
    if (100.0 / item_frac).fract() < 1e-9 {
        // item size divides capacity exactly (e.g., 10,20,25,50): pairs/triples pack cleanly
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open residuals are bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open when stream is early (plenty of future items to fill it)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // expensive when few items remain
        if next_item_size == 0 {
            score += 200.0;
        }
        // if many open bins with large mean residual, discourage new bin
        score += 0.3 * mean_residual;
        // if current bin is the only fitting one, opening new bin is wasteful
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Prefer fuller bins overall: tie-break toward low residual relative to mean.
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Congestion: with many open bins, consolidate (favor existing bins).
    score += 0.5 * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" band
    // (small, hard-to-fill leftovers) gets heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Unusable gap: nothing typical (min item 1..100 unknown) can be trusted,
        // so treat small gaps as dead space with a steep non-linear penalty.
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr) / 10.0; // tiny gap => big penalty
        } else if pr < 25.0 {
            score += 25.0 * (25.0 - pr) / 15.0;
        }
        // Perfect fit reward: near-zero waste strongly favored.
        if post_residual == 0 {
            score -= 100.0;
        } else if post_residual <= 2 {
            score -= 50.0;
        }
    }

    // Reward filling a bin deeply: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when few are open;
    // when many bins are open, prefer using existing bins (penalize new-bin pull).
    let obp = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins already exist and
        // the item could fit somewhere; relax as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 8.0 * obp - 20.0 * progress;
    } else {
        // Mild reward for consolidating into existing bins.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a bin for a bad fit later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a "ragged" bin — prefer to top it off and reduce fragmentation.
    let residual_f = bin_residual as f64;
    if residual_f + 0.5 < mean_residual {
        score -= 10.0 * (mean_residual - residual_f) / bin_capacity as f64;
    }

    // Lookahead: if the next item would fit exactly in the post_residual,
    // reward leaving that gap; if next item cannot fit, penalize the gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 1.0 && pr > 0.0 {
            score -= 35.0; // post_residual perfectly hosts next item
        } else if nxt > pr && pr > 0.0 && pr < nxt {
            score += 12.0; // gap too small for next item => dead space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits heavily
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits into post_residual,
    // reward this bin strongly (chained placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = (post_residual - next_item_size) as f64;
        score -= 150.0 - chain_tightness * 0.8;
    }

    // Penalize post_residual that is too small for the next item (dead space)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 2.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a new bin when good fits exist among open bins
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0;
        // Allow new bin if lookahead suggests the next item needs fresh space
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0;
        }
    }

    // Mild late-stream conservatism: keep bins tight as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight_bonus = (post_residual as f64).powi(2) / (bin_capacity as f64);
    score += tight_bonus * 0.5;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the next item (chaining).
        score -= (post_residual - next_item_size) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Multiple fitting bins: prefer the emptiest-remaining choice mildly.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer packing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 0.05 * mean_residual * (1.0 - progress);
    }

    // New-bin candidate handling: penalize opening a new bin early/when item fits well elsewhere,
    // but allow it when residuals are fragmented (mean residual low relative to item).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (bin_capacity as f64);
        score += 20.0 + 30.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced new bin anyway
        }
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 10.0; // room to pair with the next item
        }
    }

    // Late-stream conservatism: waste less, prefer filling existing bins.
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 20.0
                 - norm_pr * progress * 15.0
                 + norm_pr * norm_pr * norm_pr * progress * 30.0;
    score += coupling;

    // Reward tight fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 12.0;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize deviating from mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Lookahead: reward leaving room for next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let slack = pr - ns;
        let kern = (-((slack / cap).abs() * 4.0)).exp();
        score -= kern * 10.0;
        if ns > pr as f64 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Mild preference for consolidating into fewer bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.5;

    // Prefer keeping large residual bins flexible (smooth)
    score -= norm_pr * 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: modulo arithmetic on post_residual.
    // Leftovers in "harmonious" classes (multiples of common small sizes) are
    // more likely to be filled later, so penalize them less.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -30.0 // perfect fit, strongly favored
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr % 25 == 0 {
        -6.0
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division thresholds: dead space that can't hold even the smallest
    // item (pr < 10 in classic streams; use 1..100 range guard via min item guess)
    let min_item = 10u32.min(bin_capacity / 2);
    if pr > 0 && pr < min_item {
        score += 12.0; // unusable dead space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item fits, but how tightly? reward tightness
            let tight = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving space it almost fits
            let miss = (next_item_size - pr) as f64;
            if miss <= 10.0 {
                score += 6.0 + miss;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual naturally;
    // add a mild bias so we only open new bins when fit elsewhere is poor.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
    } else {
        // favor fuller bins slightly (best-fit tilt beyond raw post_residual)
        score -= 0.1 * (item_size as f64 / bin_residual.max(1) as f64) * bin_capacity as f64;
    }

    // Mean-residual coupling: if this bin's residual is far below mean (a laggard
    // bin), prefer filling it to consolidate.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.05 * dev;

    // Stream progression: late in the stream, be more conservative about opening
    // new bins (fewer chances to fill them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward closing a bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: if the leftover gap cannot hold the
    // lookahead item (or any plausible item, min size 1..=100 unknown),
    // penalize small unusable gaps strongly.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 30.0; // gap too small for the next item => dead space
        }
        if post_residual < 10 {
            score += 20.0; // tiny sliver, essentially unusable
        }
    }

    // Lookahead fit reward: leftover can still accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are
    // already open (their combined residual capacity is valuable).
    if bin_residual == bin_capacity {
        score += 12.0 + 0.4 * open_bins_count as f64 + 0.2 * mean_residual;
        // Late in the stream, opening new bins is even less attractive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        // Favor fuller existing bins slightly (best-fit bias).
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
