pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 3.0 * fit_ratio;

    // Penalize leaving awkward dead space (small, hard-to-fill leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward if the next item fits exactly/into post_residual,
    // penalize if post_residual is just barely too small for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (avoid item fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are all poor fits (large mean residual mismatch) or
    // early in the stream when there is plenty of future demand.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_gap = mean_residual - item_size as f64;
        // Penalize new bins when open bins have large residuals that could absorb items.
        score += 15.0 + 0.3 * open_bins_count as f64 - 0.5 * waste_gap.max(0.0) + 10.0 * (1.0 - progress);
        // Exact-fit case for a fresh bin with a big item.
        if item_size >= bin_capacity - 5 {
            score -= 20.0;
        }
    }

    // Mild global pressure: when many bins are open, prefer consolidating into
    // existing bins to avoid bin proliferation.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: minimize wasted space, non-linearly scaled by stream progress.
    // Later in the stream, tight fits matter more (dead space is costlier).
    let mut score = pr as f64 * (1.0 + 0.8 * progress * x);

    // Polynomial coupling: reward small post-residual quadratically,
    // but penalize near-zero residuals that create unusable slivers.
    let tight = 1.0 - x;
    score -= 12.0 * tight * tight * (0.5 + 0.5 * progress);
    score += 6.0 * x * x * x; // cubic waste penalty

    // Lookahead coupling: if next item fits the post residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let fill = nx / pr.max(1.0) as f64;
            score -= 10.0 * fill * fill;
        } else {
            // post residual too small for next item: penalize proportionally
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - x);
    }

    // New-bin candidate: keep it moderately attractive only when fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - item_size as f64 / cap) * (1.0 - 0.5 * progress);
    }

    // Mean-residual divergence: prefer bins whose residual deviates from mean
    // (consolidating space into fewer bins).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score -= 3.0 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: Best-Fit tightness (lower post_residual => lower score => preferred).
    let mut score = post_residual as f64;

    // --- Exact fill: dominant reward ---
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Near-dead leftover: nonzero but almost unusable sliver ---
    let tiny_thresh = (bin_capacity / 20).max(1);
    if post_residual > 0 && post_residual < tiny_thresh {
        score += 3.0;
    }

    // --- Harmonic alignment (modulo classes) ---
    // Leftover divisible by the item's size class => bin can host more copies of this class.
    if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 {
        score -= 6.0;
    }
    // Decile-aligned leftover: mildly preferred (common size grids).
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 2.0;
    }

    // --- Capacity-fraction class of the leftover ---
    if post_residual > half {
        score -= 2.0; // flexible leftover (can host any class)
    } else if post_residual > third {
        score -= 1.0; // hosts mid classes
    }

    // --- Lookahead (k=2) synergy / waste detection ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            // Next item chains into this bin: reward, strongest on a perfect pair.
            let gap = post_residual as f64 - nxt;
            score -= 12.0 + 8.0 * (1.0 - gap / cap);
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else if !is_new_bin && next_item_size <= bin_residual {
            // Next item fits here NOW but not after this placement: destroying usable space.
            let snug = 1.0 - (bin_residual - next_item_size) as f64 / cap;
            score += 30.0 * snug;
        }
    }

    // --- Last-chance logic: only fitting open bin before a new bin is opened ---
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 18.0 + 14.0 * progress; // stronger late in the stream (less future to recoup)
    } else if !is_new_bin && fitting_bins_count > 1 {
        score -= 4.0 / fitting_bins_count as f64;
    }

    // --- Fragmentation control: prefer consuming below-mean-residual bins ---
    if !is_new_bin && mean_residual > 0.0 {
        let ratio = (bin_residual as f64 / mean_residual).clamp(0.5, 2.0);
        score -= 4.0 * (1.0 - ratio);
    }

    // --- Mild pressure against opening yet another bin when many are already open ---
    if is_new_bin {
        score += (open_bins_count as f64).sqrt().min(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fits that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leaves a gap the next item cannot use: penalize mildly.
        score += 5.0;
    }

    // Last-chance bin before opening a new one: favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins exist and mean residual is usable.
        score += 25.0 + pressure * 3.0 + progress * 10.0;
        if mean_residual >= item_size as f64 {
            score += 15.0;
        }
    } else {
        // Filling existing bins is rewarded, scaled by how much residual they consume.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0 + pressure * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual.
    score -= 40.0 * (1.0 - (post_residual as f64) / cap).powi(4);

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-gap / 8.0).exp();
        // Also reward near-matches so lookahead guides selection.
        score -= 10.0 * (1.0 - gap / cap).max(0.0).powi(3);
    }

    // Penalize dead space unusable by typical items: post_residual below 10 is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it unattractive unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred.
        score += 30.0;
        // But if the item leaves a huge hole in any open bin relative to mean residual,
        // opening fresh becomes competitive: reduce penalty.
        let waste = (bin_residual as f64 - item_size as f64) / cap;
        if waste > 0.5 && mean_residual / cap < 0.25 {
            score -= 35.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mild reward for bins tighter than the current mean residual.
    score -= 5.0 * ((mean_residual - bin_residual as f64) / cap).max(-1.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if next item fits the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.35 * next_item_size as f64;
    }
    // If next item cannot fit anywhere else well, prefer keeping flexibility.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual < 15 {
            score += 20.0; // but not if it wrecks the bin
        }
    }

    // New-bin candidate handling: empty bin gets a mild opening cost that shrinks
    // as the stream progresses or when many bins are open and fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - bin_capacity as f64).abs() / bin_capacity as f64;
        score += 10.0 - 6.0 * progress + 5.0 * fragmentation;
        // Opening a new bin is attractive when no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Global state coupling: when mean residual is high (lots of slack spread out),
    // prefer consolidating into bins with below-average residual.
    let below_mean = (bin_residual as f64) < mean_residual;
    if below_mean {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild penalty for many open bins: encourage reuse to limit bin count.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual, scaled non-linearly by stream progress.
    let mut score = post * (1.0 + 0.5 * progress * progress);

    // Reward tight fits: quadratic bonus as post_residual approaches 0.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fill_after_next = (post - nxt) / cap;
            score -= 8.0 * (1.0 - fill_after_next) * (1.0 + progress);
        } else {
            // Penalize leaving residual that next item cannot use (dead space risk).
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 10.0 + 6.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin unless residuals are large.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        // If existing mean residual is small, opening new bin is fine; else penalize.
        score += 6.0 + mean_r * 0.15 - 8.0 * progress;
    }

    // Mild penalty for fragmenting bins when many bins are already open.
    score += 0.02 * open_bins_count as f64 * (post / cap);

    // Smooth interaction: penalize mid-range residuals (hard to fill later).
    let mid = (post - cap * 0.5) / (cap * 0.5);
    score += 3.0 * mid * mid * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions (sixths). Residuals that are "harmonically clean"
    // (near multiples of capacity/6) are more reusable by future items.
    let sixth = cap / 6.0;
    let pr = post_residual as f64;
    let class = (pr / sixth).round();          // nearest harmonic class 0..6
    let class_center = class * sixth;
    let harmonic_dev = (pr - class_center).abs(); // distance from clean class

    // Reward clean harmonic residuals (subtract), penalize off-class slivers.
    score -= 6.0 * harmonic_dev / cap;

    // Dead space: residuals too small to hold even the smallest item are waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit bonus (integer division thresholds on post_residual).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual % 25 == 0 {
        score -= 8.0; // quarter-capacity class is highly reusable
    } else if post_residual % 10 == 0 {
        score -= 3.0; // decade class
    }

    // Lookahead coupling: if the next item fits the post residual exactly
    // or nearly, strongly reward this bin (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack < 10 {
            score -= 15.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual < next_item_size && post_residual > 0 {
        // Post residual cannot host the next item: mild penalty scaled by waste.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // which already scores high; add a mild progression-based nudge so
    // early in the stream we prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    // Slight preference for tighter bins (below mean residual) to keep
    // the bin population compact.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: tiny gaps (< min item size 10) are unusable forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // allow spreading when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins open or early in stream.
        score += 25.0 + 30.0 * (1.0 - progress) + (open_bins_count as f64).min(20.0);
        // Accept new bin if current bin would leave a big awkward gap vs. lookahead.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    } else {
        // Existing bin: mild bonus for matching the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        // Prefer bins with below-average residual (more filled bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward near-match within a small window
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff < 10.0 {
            score -= (10.0 - diff) * 2.0;
        }
    }

    // Penalize dead space: residuals too small for typical items (1..100 unknown, but small residuals are waste)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins whose post_residual is near/below mean
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins mildly, more when many bins are open and stream is late
        score += 20.0 + 15.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If lookahead would perfectly fill a fresh bin pair, allow it
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 35.0;
        }
    }

    // Slight preference for tighter fits overall (nonlinear squashing)
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 3.0 * tightness * (post_residual as f64).max(1.0);

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 20.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted pairing potential
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Time horizon: early in the stream, be more willing to spread items (favor new bins
    // less) to keep flexibility; late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> encourage filling existing bins.
    let global_pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score -= 0.5 * global_pressure;

    // New-bin candidate handling: only attractive when item is large or existing fit is bad.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin; discounted for large items or early stream.
        score += 15.0 - 20.0 * fill_ratio - 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Mild penalty for very small items consuming scarce residual in nearly-full bins.
    if item_size <= 20 && bin_residual <= 30 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize wasted residual quadratically (dead space grows superlinearly in badness)
    let mut score = norm_pr * norm_pr * 120.0 + norm_pr * 30.0;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer tight fits less aggressively; later, tight packing matters more
    let progress_coupling = (0.5 * (1.0 - progress) * (1.0 - progress)) * 40.0;
    score += norm_pr * progress_coupling;

    // Reward filling the bin well: subtract based on item fraction, cubic in item size
    score -= norm_item * norm_item * norm_item * 25.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 + 50.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits in the post residual, reward leaving that space
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr as f64 {
            let fit_quality = 1.0 - ((pr - n) / cap).abs();
            score -= 20.0 * fit_quality * fit_quality;
        } else {
            // post residual too small for next item: penalize near-miss dead space
            score += 15.0 * (1.0 - (pr / n));
        }
    }

    // Smooth interaction with mean residual: bins far below mean residual are precious
    let mean_norm = mean_residual / cap;
    let deviation = norm_pr - mean_norm;
    score += 10.0 * deviation * deviation - 8.0 * deviation;

    // Slight penalty for spreading across many open bins early
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate: make it attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = 1.0 - (norm_item * norm_item);
        score = 80.0 * pressure + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    if post_residual < 1 {
        score -= 1000.0; // perfect fit, extremely desirable
    } else if post_residual < 10 {
        // Unusable dead space (min item size is 10 in classic streams) — heavy penalty.
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    } else {
        // Usable gap: reward proportional to how well it accommodates the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else if next_item_size > 0 {
            // Gap survives but cannot host the next item: mild penalty.
            score += 3.0 + 0.10 * (next_item_size - post_residual) as f64;
        }
        // Smooth quadratic dead-space curvature on the remaining gap.
        score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;
    }

    // Tightness bonus: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 1.5 * progress);

    // Prefer bins whose residual deviates favorably from the mean (filling laggard bins).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin is a decent host.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 1
            || (fitting_bins_count == 1 && item_size as f64 / bin_capacity as f64 > 0.7);
        if decent_fit_exists {
            score += 40.0; // keep using open bins
        } else {
            score -= 5.0; // opening fresh is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            // next item can also fit here: reward exact match strongly
            let gap = (post_residual as f64 - nx).abs();
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize proportionally
            score += 0.15 * (nx - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins that keep the residual distribution balanced
    let pr = post_residual as f64;
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let waste = bin_capacity as f64 - item_size as f64;
        // Only attractive if the item is large relative to capacity (poor fit elsewhere)
        score += 25.0 - 0.2 * item_size as f64;
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 10.0; // new bin can host the next item too
        }
        let _ = waste;
    }

    // Late-stream consolidation: avoid leaving many tiny residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr < 10.0 {
        score -= 2.0 * (1.0 - progress); // early on, filling bins tight is good
    } else {
        score += 0.5 * progress; // late, avoid fragmenting residuals
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / cap;

    // Reward near-perfect packing (post residual tiny).
    if post_residual <= 2 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) == nxt {
            score -= 30.0;
        } else if (post_residual as u32) >= next_item_size {
            // next item fits, but imperfectly: mild bonus proportional to snugness
            let snug = 1.0 - ((post_residual as f64 - nxt) / cap);
            score -= 8.0 * snug;
        } else {
            // placing here strands the next item: penalty scaled by how badly
            let strand = nxt - post_residual as f64;
            score += 0.15 * strand;
        }
    }

    // Penalize opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / cap;
        // New bins are fine for large items or when existing residuals are poor.
        let best_alt = if mean_residual > 0.0 { mean_residual } else { cap };
        let alt_quality = (best_alt - item_size as f64) / cap; // how much slack alternatives would leave
        score += 40.0
            - 30.0 * fit_ratio
            - 25.0 * alt_quality.max(0.0)
            - 6.0 * (open_bins_count as f64).ln().max(0.0);

        // Early in stream, opening bins is cheap (builds diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 12.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is already small (consolidate waste).
    let res_ratio = bin_residual as f64 / cap;
    score += 6.0 * res_ratio;

    // Slight preference for bins below mean residual (balance load).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Late-stream: squeeze everything into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - res_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Core: quadratic coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress) - 0.6 * fit_norm * (1.0 - fit_norm) * cap;

    // Penalize large post-residuals more as stream advances (less time to reuse)
    score += 0.5 * fit_norm * fit_norm * cap * progress;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - fit_norm);
    }

    // Lookahead: reward if next item fits the post-residual, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 12.0 * (1.0 - (nxt / cap));
        } else {
            score += 8.0 * (nxt / cap);
        }
    }

    // Mild preference for bins with residuals near mean (balanced packing)
    score += 0.15 * (mean_residual - pr).abs();

    // Discourage spreading across too many open bins when post-residual is wasteful
    score += 0.05 * open_bins_count as f64 * fit_norm;

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band it falls in.
    // Bands: [0..=10] near-full (great), (10..=25], (25..=50], (50..=75], (75..=100] wasteful.
    let band = match post_residual {
        0 => 0.0,
        1..=10 => 1.0,
        11..=25 => 2.0,
        26..=50 => 3.0,
        51..=75 => 4.0,
        _ => 5.0,
    };
    score += band * band * 4.0;

    // Reward tight fits strongly (small post_residual).
    if post_residual <= 10 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual; penalize large leftover more
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so it's only chosen when all open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.5;
    } else {
        // Prefer bins with residual close to item (minimize fragmentation),
        // scaled by how many alternatives exist.
        let waste = (bin_residual - item_size) as f64;
        score += waste * 0.1 * (fitting_bins_count as f64).min(5.0);
    }

    // Modulo arithmetic on post_residual: residuals divisible by common small
    // item sizes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 5.0;
    }

    // Integer-division threshold: residual in [item_size_min ..= 2*min) is a
    // "dead" class for small items but fine as terminal waste.
    if pr > 0 && pr < 10 {
        score -= 8.0; // tiny residual is acceptable terminal waste
    }

    // Late in stream: consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap smaller than the minimum
    // possible item size is unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leaves a gap too small for the next item: penalize.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate gets bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure from open bins.
        score += 15.0 + open_bins_count as f64 * 3.0;
        // If an existing bin would leave little dead space, avoid new bin.
        if post_residual == bin_capacity && fitting_bins_count > 0 {
            score += 5.0;
        }
    } else {
        // Mild reward for using existing bins, scaled by how full they get.
        score -= 5.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Prefer bins with below-mean residual (tighter bins) to consolidate space.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Early in the stream, be slightly more willing to open new bins for
    // flexibility; late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    } else {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // 2-step lookahead: reward when next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + gap * 0.3;
        }
    }

    // Relative-to-mean coupling: bins with residual far from mean are penalized
    // when post_residual deviates from mean residual structure.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Late in the stream, consolidate: prefer minimal post residual even harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    // New-bin candidate (empty bin): make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + next_item_size as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of the fit: reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item (<= 1..100 unknown dist)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // penalize creating a residual that wastes space for the known next item
            score += 10.0;
        }
        // chain fit: next item nearly fills the remaining space too
        let chain = post_residual as f64 - next_item_size as f64;
        if chain >= 0.0 && chain < 5.0 {
            score -= 15.0;
        }
    }

    // Prefer bins with below-average residual (keep big residual bins available for big items)
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 15.0 * rel;

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // late in the stream, tightness matters more than conserving bins.
    score -= 30.0 * (1.0 - progress) * (1.0 - tightness);

    // Many open bins: discourage opening yet another bin
    if bin_residual == bin_capacity {
        score += 20.0 * (open_bins_count as f64).ln().max(0.0);
        // but allow opening a new bin if the item is huge and fits poorly anywhere else
        if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 1 {
            score -= 70.0;
        }
    }

    // Small penalty for placing large items into nearly-full bins (fragmentation avoidance)
    if item_size as f64 > 0.6 * bin_capacity as f64 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr * (0.5 + 0.5 * progress) + 40.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // Penalize wasting a nearly-empty bin's potential when many bins are open
    let waste_penalty = (norm_pr - mean_residual / cap).abs();
    score += waste_penalty * (5.0 + 10.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxs = next_item_size as f64;
        if pr < nxs {
            score += (nxs - pr) * (0.3 + 0.4 * progress);
        } else {
            score -= (1.0 - (pr - nxs) / cap) * 8.0 * (1.0 - progress);
        }
    }

    // New-bin candidate: mild baseline so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress - 10.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "usable" classes (divisible by common small item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Class A: leftover is a multiple of 10 or 20 -> highly reusable.
        if pr % 10 == 0 {
            score -= 8.0;
            if pr % 20 == 0 {
                score -= 4.0;
            }
        }
        // Class B: leftover fits the lookahead item exactly or with slack.
        if next_item_size > 0 && next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 6.0 + (slack as f64) * 0.05;
            if slack == 0 {
                score -= 6.0; // perfect two-item pairing
            }
        } else if next_item_size > 0 {
            score += 3.0; // lookahead cannot use this leftover
        }
        // Dead-space penalty: tiny unusable remainders.
        if pr < 5 {
            score += 12.0;
        } else if pr < 10 {
            score += 5.0;
        }
        // Integer-division tier: leftover in [10, 30] is a "sweet spot" class.
        let tier = pr / 10;
        match tier {
            1 => score -= 3.0,
            2 => score -= 2.0,
            3 => score -= 1.0,
            _ => {}
        }
    } else {
        score -= 10.0; // perfect fill, best possible outcome
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when existing residuals
    // are fragmented (mean residual low relative to item) or many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        let mut new_bin_score = 35.0
            - fragmentation * 20.0
            - (open_bins_count as f64) * 0.5
            - progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_score -= (bin_capacity - next_item_size) as f64 * 0.05;
        }
        score = new_bin_score.max(score + 20.0) - if score < 0.0 { 0.0 } else { 0.0 };
    }

    // Mild preference for fuller bins (waste minimization as fraction).
    score += (bin_capacity - bin_residual) as f64 * -0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly worthless.
    // Any post_residual below the minimum item size (1) is pure loss; below
    // typical item sizes it is likely unusable dead space.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver: heavy penalty.
        score += 40.0;
    } else if post_residual < 25 {
        // Likely dead space for most items: moderate-heavy penalty.
        score += 18.0;
    } else if post_residual < 50 {
        // Partially usable zone: mild penalty.
        score += 6.0;
    }

    // Lookahead coupling: if the next item can still fit into the post
    // residual, this placement preserves future utility — reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward if next item fills it almost exactly.
            let gap_after_next = post_residual as f64 - next_item_size as f64;
            if gap_after_next < 10.0 {
                score -= 10.0;
            }
        } else {
            // Post residual too small for next item: this bin likely goes
            // dormant; penalize proportionally to wasted space.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Tightness reward: the closer item_size is to bin_residual, the better.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Last-chance pressure: if this is the only bin that fits, using it
    // avoids opening a new bin — reward strongly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize mildly per open bin
    // so new bins are only opened when fit quality is poor.
    score += open_bins_count as f64 * 0.8;

    // Progress-aware conservatism: late in the stream, dead space matters
    // more (fewer chances to recover), tighten the dead-space stance.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * 0.05 * progress;

    // Mean residual context: if this bin's residual is far below the mean,
    // it is already the "worst" bin — filling it is good consolidation.
    let residual_diff = mean_residual - bin_residual as f64;
    score += residual_diff * 0.3;

    // New-bin candidate handling: an empty bin should only win when all
    // open-bin options are bad fits. Give it a moderate standing penalty
    // so only genuinely poor fits (large dead space) lose to it.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is large and this is early, a fresh bin has value.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when next item exactly matches post_residual (perfect 2-step fill).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Perfect exact match for the lookahead: very strong reward.
        if next_item_size == post_residual {
            score -= 60.0;
        }
        // Next item fits exactly after a small nudge: still good.
        if next_item_size < post_residual && post_residual - next_item_size <= 10 {
            score -= 20.0;
        }
    }

    // Penalize dead space that no future item (10..100) can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins that end below-average residual
    // (tight packing) when the bin was already loose.
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when good existing options exist,
    // unless the item is large and residual is tight (best-fit escape).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin is attractive only for very large items or when nothing fits well.
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 30.0 * tightness;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin can also host the next item: acceptable
        }
    }

    // Late in the stream, close out bins aggressively (avoid many half-empty bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // Slight preference for fuller bins generally (best-fit bias).
    score -= 0.1 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit: strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty: leftover too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 20 {
        score += 8.0 + 0.5 * (20 - post_residual) as f64;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        // If the next item would fit in the post residual, extra reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Lookahead: penalize placements that leave residual useless for next item
    // but reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate logic: fresh bin should win only when current fit is poor
    // or when open bins are crowded with small residuals.
    if bin_residual == bin_capacity {
        // Base mild penalty so a decent fit beats a new bin.
        score += 10.0;
        // But if the item fits poorly everywhere (large mean residual mismatch),
        // or many bins exist but none fit well, favor opening a new bin.
        let fit_quality = 1.0 - (post_residual as f64 / item_size.max(1) as f64);
        if fit_quality > 0.7 {
            score -= 18.0;
        }
        if open_bins_count == 0 {
            score -= 25.0;
        }
        // Early in stream, opening bins is cheap (more future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        // If mean residual across open bins is small, open bins are nearly full;
        // a new bin adds usable space.
        if mean_residual < item_size as f64 * 1.5 {
            score -= 6.0;
        }
    } else {
        // Slight penalty for spreading across many open bins when few items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 3.0 * open_bins_count as f64 / 10.0;
        }
    }

    // Prefer bins whose residual is below mean (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 25.0 * progress * norm_pr * (1.0 - norm_pr);

    // Penalize tight fits that create dead space relative to mean residual
    let dead = (pr as f64 - mean_residual) / cap;
    score += 15.0 * dead * dead.abs();

    // Reward near-perfect fills more as stream progresses
    score -= 60.0 * progress * (1.0 - norm_pr).powi(6);

    // Lookahead coupling: reward leaving room for the next item (smooth quadratic mismatch)
    if next_item_size > 0 {
        let mismatch = norm_next - norm_pr;
        score -= 30.0 * (1.0 - mismatch * mismatch) * (1.0 - progress * 0.5);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0 + 40.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - norm_item);

    // New-bin candidate: neutral-ish baseline, penalized unless item is huge relative to capacity
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - norm_item) * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: class 0 = perfect fit.
    let class = post_residual % 10;
    score -= match class {
        0 => 12.0,
        1 | 2 => 6.0,
        3 | 4 | 5 => 2.0,
        _ => 0.0,
    };

    // Fractional fill level: reward bins that are already heavily filled.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 8.0 * fill * fill;

    // Lookahead: penalize if next item cannot use this bin's post-residual.
    if next_item_size > 0 {
        if (post_residual as u64) < next_item_size as u64 {
            score += 4.0;
        } else {
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 2.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New empty bin candidate: penalize unless current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = if open_bins_count > 0 {
            (mean_residual / cap).min(1.0)
        } else {
            1.0
        };
        score += 20.0 - 18.0 * frag;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps strongly (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * open_bins_count as f64;
    }

    // Open bins pressure: prefer filling existing bins when many are open
    score += 0.3 * open_bins_count as f64;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }

    // Prefer bins tighter than average residual
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fits (minimal dead space)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: reward when post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits comfortably here: big reward, tighter chain = better
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * chain_slack;
        } else {
            // next item would not fit here: penalize proportionally to the miss
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    }

    // Relative to mean residual: prefer bins with residual near/above mean
    // (keeps big-residual bins available for big future items)
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large enough that a fresh bin is genuinely valuable
    if bin_residual == bin_capacity {
        let base = 15.0 + 0.6 * item_size as f64;
        score += base;
        // still allow new bin if item nearly fills it
        if item_size >= 70 {
            score -= 45.0;
        }
    }

    // Mild pressure to consolidate open bins over time
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: penalize by relative fill.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize tiny post-residuals that are still unusable dead space
    // (too small for the smallest plausible item), unless it's exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for stranding space.
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: mild penalty for wasting a scarce-good bin.
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and no bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_here = post_residual as f64; // == capacity - item
        let poor_open_fit = mean_residual < item_size as f64 * 1.1
            && mean_residual < bin_capacity as f64 * 0.4;
        if poor_open_fit && item_size > bin_capacity / 2 {
            score -= 20.0 * progress; // open new bin late in stream for big items
        } else {
            score += 30.0 + 20.0 * (1.0 - progress); // discourage new bins generally
        }
        let _ = waste_here;
    }

    // Global state coupling: prefer filling bins when mean residual is high
    // (many scattered half-empty bins -> consolidate).
    if mean_residual > 0.0 {
        let consolidation = (post_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 15.0 * consolidation;
    }

    // Mild time-horizon effect: early on, be picky (penalize mediocre fits);
    // near the end, accept anything that closes a bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * (1.0 - progress) * (1.0 - fill_ratio);
    score -= 10.0 * progress * fill_ratio;

    // Prefer bins that are already substantially used (close them out).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Penalize large dead space late in the stream (smooth cubic coupling)
    score += 25.0 * norm_pr * norm_pr * norm_pr * progress;

    // Reward tight fits: small post_residual relative to item size
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness * (1.0 - progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this bin
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.4 * gap;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // last item: minimize post residual aggressively
        score += 15.0 * norm_pr;
    }

    // Slight preference to balance residuals across bins via mean residual
    score += 0.15 * (mean_residual - pr);

    // New-bin candidate: make it moderately attractive only when open bins would leave big dead space
    if bin_residual == bin_capacity {
        score -= 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by modulo arithmetic on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction remaining

    // Class 1: post_residual exactly divisible by common item sizes (10,20,25,50)
    // These leave perfectly reusable residual classes.
    let div_bonus = if post_residual > 0 {
        let mut b = 0.0;
        if post_residual % 10 == 0 { b += 6.0; }
        if post_residual % 20 == 0 { b += 4.0; }
        if post_residual % 25 == 0 { b += 3.0; }
        if post_residual % 50 == 0 { b += 5.0; }
        b
    } else {
        12.0 // perfect fill: strongest reward
    };
    score -= div_bonus;

    // Integer-division threshold classes on post_residual:
    // dead-space zones where few item sizes (1..100) can still fit.
    let dead = if post_residual == 0 {
        0.0
    } else if post_residual < 10 {
        25.0 // unusable dead space
    } else if post_residual < 25 {
        12.0
    } else if post_residual < 40 {
        6.0
    } else if post_residual < 60 {
        2.0
    } else {
        0.0
    };
    score += dead;

    // Harmonic coupling: next_item_size relative to post_residual via integer division
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly here: strong lookahead reward
            score -= 10.0;
            let quot = post_residual / next_item_size;
            if quot >= 2 { score -= 4.0; } // could take multiple future items
            if post_residual == next_item_size { score -= 6.0; } // perfect lookahead fill
        } else {
            // next item won't fit here: penalize proportionally
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should have a moderate baseline;
    // make it attractive only when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + dead * 0.5 - div_bonus * 0.3;
        if fitting_bins_count <= 1 {
            score += 5.0; // discourage opening new bin when this is last chance
        }
    }

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill * fill;

    // Late-stream consolidation: near end of stream, prefer tighter packs
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * frac;

    // Mean-residual coupling: if this bin's residual is far below mean, it is
    // already fragmented; using it consolidates fragmentation.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to hold even the smallest
    // plausible item (1..=10) are wasted capacity; penalize hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 25 {
        // Small-but-usable gaps: mild penalty to prefer larger usable remainders
        score += (25 - post_residual) as f64 * 0.8;
    }

    // Reward very tight fits (post_residual near zero but above dead zone)
    if post_residual > 0 && post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item can fit into the post-residual, reward
    // keeping that compatibility; penalize breaking a chain.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is attractive when the fit
    // into existing bins would create large dead space, or when few bins
    // are open (early stream). Otherwise make new bins less attractive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = (item_size as f64) / (bin_capacity as f64);
        // New bin is good for large items or early on; bad later with small items.
        score -= (fit_quality * 40.0) + (1.0 - progress) * 15.0;
        score += mean_residual * 0.1; // if open bins still have room, prefer them
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect 2-step lookahead fit: post_residual equals next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize small dead space that next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward when next item fits into the post-residual (chained packing)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual as f64 - next_item_size as f64).abs().min(10.0) * 0.5;
    }

    // Prefer bins with residuals below mean (tight packing)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly empty bin when many bins are open
    if post_residual > (bin_capacity as f64 * 0.6) as u32 && open_bins_count > 2 {
        score += 10.0;
    }

    // Late stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post-residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Small dead space is nearly useless.
        score += 15.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= 25.0 - chain_quality * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item: penalize proportionally.
        let waste = post_residual as f64;
        score += waste * 0.5;
    }

    // Penalize using a nearly-full bin when many alternatives exist.
    let fill_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score += fill_frac * open_bins_count as f64 * 2.0;

    // Global balance: prefer bins whose residual is close to what we leave behind.
    let dev = (mean_residual - post_residual as f64).abs();
    score += dev * 0.1;

    // Time horizon: early in stream, be conservative (favor new bins for large items);
    // late in stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if item_size > 60 && progress < 0.3 && bin_residual == bin_capacity {
        score -= 10.0; // open fresh bins early for big items
    }
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 5.0; // prefer existing bins late
    }

    // New-bin candidate baseline: mild penalty so it's chosen only when it beats real fits,
    // but not so high that we never open bins when needed.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If no open bin fits well (post_residual of new bin vs item), opening is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, smoothed non-linearly
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: later in stream, penalize residual more sharply
    let prog_coupling = 1.0 + 2.0 * progress * progress;
    score *= prog_coupling;

    // Reward tight fits via smooth sigmoid-like term on normalized post residual
    let tight = (-8.0 * norm_pr).exp();
    score -= 10.0 * tight * (1.0 + progress);

    // Penalize waste relative to mean residual state
    score += 0.5 * (pr - mean_residual).abs() * (0.5 + progress);

    // Lookahead: if next item fits into post residual, reward
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0 * norm_next * (1.0 - norm_pr);
    } else if next_item_size > 0 {
        score += 4.0 * norm_next * norm_pr;
    }

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: mildly penalize early, allow late when fits are poor
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) * (1.0 - norm_item) + 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity fraction it lands in.
    // Residual classes: 0 (perfect), <=10 (near-perfect), <=25 (good), <=50 (usable), >50 (wasteful).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: extremely desirable
    } else {
        let class_penalty = if pr <= 10 { 2.0 }
                            else if pr <= 25 { 8.0 }
                            else if pr <= 50 { 18.0 }
                            else { 30.0 };
        score += class_penalty;

        // Modulo-harmonic coupling: leftovers that are multiples of common small
        // sizes (5, 10, 20) are more likely to be filled by future items.
        if pr % 10 == 0 {
            score -= 4.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            score += 3.0; // awkward leftover
        }
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // next item fills this bin exactly
        } else if next_item_size < pr {
            let nxt = next_item_size as f64;
            let slack = (pr - next_item_size) as f64;
            // reward if next item leaves a harmonically small slack again
            let nxt_slack_bonus = if slack == 0.0 { 40.0 }
                                  else if slack <= 10.0 { 12.0 }
                                  else if slack <= 25.0 { 5.0 }
                                  else { 0.0 };
            score -= nxt_slack_bonus;
            // integer-division harmonic: post_residual / next_item_size ratio classes
            let ratio = pr / next_item_size;
            if ratio >= 2 && pr % next_item_size == 0 {
                score -= 6.0; // next item divides leftover evenly (room for another)
            }
            let _ = nxt;
        } else {
            // next item too big for this residual: leftover is dead space for lookahead
            score += 10.0 + (pr as f64) * 0.05;
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 20.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit would be terrible).
    if fitting_bins_count == 1 {
        score -= 25.0;
        if pr > 50 {
            score += 15.0; // but a very bad fit weakens the last-chance bonus
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; make it attractive only when the
        // alternative fits are poor or no open bin exists.
        score = 55.0 + post_residual as f64; // post_residual == capacity here
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && item_size as f64 / cap > 0.7 {
            score -= 10.0; // big item: fresh bin gives full flexibility
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, avoid proliferating bins with tiny leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // Many open bins with high mean residual: reuse instead of opening.
        if mean_residual > cap * 0.3 {
            score += 12.0;
        }
    }

    // Mild penalty for hoarding many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual > 10 && post_residual < 20 {
        // Medium-small gaps are mildly risky.
        score += (20 - post_residual) as f64 * 0.5;
    }

    // Reward very tight fits (near-zero post residual) beyond raw value.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Lookahead: if the next item can use the remaining gap, this is a good staging bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Gap likely unusable by next item: slight penalty proportional to gap.
        score += post_residual as f64 * 0.15;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 + progress) * 0.6;

    // Mean residual coupling: if this bin's residual is far below the mean, it's a good filler.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (residual_f - mean_residual) * 0.25;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (handled via fitting_bins_count bonus above); otherwise keep it mildly penalized.
    if bin_residual == bin_capacity {
        score += 5.0 - 20.0 * (fitting_bins_count == 0) as i32 as f64;
        // Late in stream, opening new bins is cheaper than fragmenting.
        score -= progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / 100.0).max(0.0);

        // Penalize post_residual that is too small to fit next item (dead space)
        if (post_residual as i64) < next_item_size as i64 {
            score += 12.0 + 0.25 * post_residual as f64;
        } else {
            // Reward leaving exactly enough room, slightly less than perfect
            score -= 8.0;
        }
    } else {
        // Last item: just minimize post residual
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when a decent fit exists
    if bin_residual == bin_capacity {
        score += 25.0 - 0.1 * item_size as f64;
        // New bin is more attractive late in stream if many bins open
        score += 0.02 * open_bins_count as f64;
    }

    // Slight time decay: early on, be conservative with new bins
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - residual_frac) * (1.0 - residual_frac) * 12.0;

    // Dead-space penalty: leaving slivers that nothing (>=1) can use is bad.
    if post_residual >= 1 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (chaining),
    // penalize if next item is large and this placement strands it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if next_item_size > bin_residual {
            // next item won't fit this bin anyway; slight bonus for using big residual now
            score -= 3.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        if post_residual < 10 { score -= 10.0; }
    }

    // New-bin candidate handling: opening a fresh bin is attractive when the item
    // is large and fits poorly everywhere else; otherwise keep it costly.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits: must open
        } else if fill > 0.6 && post_residual < item_size as u32 / 2 {
            score -= 10.0;
        } else {
            score += 18.0 + 10.0 * (1.0 - fill);
        }
    }

    // Prefer bins with above-mean residual when the item is small (preserve tight bins);
    // prefer below-mean residual (tight bins) when the item is large.
    let fill = item_size as f64 / bin_capacity as f64;
    let dev = bin_residual as f64 - mean_residual;
    if fill > 0.5 {
        score += 0.15 * dev * fill;
    } else {
        score -= 0.08 * dev * (1.0 - fill);
    }

    // Time horizon: late in the stream, consolidate aggressively into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0 * (open_bins_count as f64).ln().max(0.0);

    // Mild penalty for proliferating many open bins early.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let prn = (pr / cap).clamp(0.0, 1.0);

    // Base: prefer small post-residual (tight fit), non-linearly.
    let mut score = prn * prn * cap;

    // Smooth polynomial coupling of tightness with stream progress:
    // late in the stream, tight fits matter more; early on, keep bins flexible.
    let coupling = prn * (1.0 - prn) * 4.0; // peaks at prn = 0.5 (half-empty bin)
    score += coupling * (10.0 + 30.0 * progress);

    // Penalize post-residual that cannot fit the lookahead item (wasted space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + 1.5 * progress);
        } else {
            // reward bins whose leftover still fits the next item, smoothly.
            let fit_q = nx / pr.max(1.0);
            score -= fit_q * (2.0 + 8.0 * (1.0 - progress));
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: discourage opening a new bin when decent open bins exist,
    // more strongly early in the stream; allow it late or when bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 40.0 * (1.0 - progress) * (1.0 - 0.5 * crowd);
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild penalty for deviating far from mean residual (balance bin loads).
    score += 0.05 * (pr - mean_residual).abs();

    // Reward near-perfect fills with a smooth quadratic term.
    score -= (1.0 - prn) * (1.0 - prn) * (5.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by modulo classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining
    let frac = pr / cap;

    // Class A: post_residual in {0, 10, 20, ...} multiples of 10 -> usable by typical items
    let harmonic_class = post_residual % 10;
    match harmonic_class {
        0 => score -= 25.0,           // clean decade residual, highly reusable
        5 => score -= 10.0,           // half-decade, moderately reusable
        1 | 3 | 7 | 9 => score += 15.0, // odd prime-class dead space, rarely reusable
        _ => score += 5.0,            // even non-decade, mildly awkward
    }

    // Integer-division threshold: large residuals (>= half capacity) are valuable
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 30.0;
    } else if post_residual < 10 {
        // tiny dead space: penalize unless it was a near-perfect fit already
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness of the chain
            let tightness = (post_residual - next_item_size) as f64;
            score -= 60.0 - tightness * 0.5;
        } else {
            // next item cannot use this bin's remainder: penalize awkward remainders
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += gap * 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // best available fit is bad. Give the empty bin a moderate baseline score.
    if bin_residual == bin_capacity {
        // baseline: slightly worse than a good fit, better than a terrible one
        score = cap * 0.55 + (open_bins_count as f64) * 2.0;
        // if current item is large relative to capacity, new bin is attractive
        if (item_size as f64) > cap * 0.7 {
            score -= 20.0;
        }
        // if many bins are open with high mean residual, prefer consolidation
        if open_bins_count > 3 && mean_residual > cap * 0.3 {
            score += 30.0;
        }
    }

    // Stream progression: early on, be conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading items across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.2;
    }

    // Lookahead: prefer bins whose post-residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight superlinear penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect chain), penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            // Exact match (slack == 0) is ideal; decay as slack grows.
            score -= 30.0 * (-slack / 15.0).exp();
            // Extra reward for a perfect chain leaving zero slack after next item too.
            if slack == 0.0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot fit here: mildly penalize wasting small residuals
            // that the next item would have consumed.
            let miss = nxt - pr;
            score += 0.5 * miss.min(20.0);
        }
    }

    // Relative-to-mean-residual coupling: bins with residual far above mean
    // are "rich" — using them for a big item is fine; using them for tiny
    // items wastes capacity. Penalize small items going into large-residual bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        if ratio > 1.0 {
            score += 2.0 * (ratio - 1.0) * (item_size as f64 / bin_capacity as f64);
        } else {
            score -= 2.0 * (1.0 - ratio);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily — unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = pr as f64;
        if waste <= 10.0 {
            score -= 40.0;
        } else {
            score -= 40.0 * (-waste / 25.0).exp();
        }
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no open bin fits well (post_residual would be very small anyway).
    if bin_residual == bin_capacity {
        score += 25.0;
        // Allow new bin when item is huge and would leave almost nothing.
        if (item_size as f64) > 0.85 * (bin_capacity as f64) {
            score -= 30.0;
        }
        // Late in the stream, avoid opening bins that will barely be used.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    } else {
        // Mild preference for keeping bins balanced across open set.
        score += 0.05 * (open_bins_count as f64);
    }

    // Small bonus for filling bins completely (zero waste endgame).
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress within the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: small post-residuals are good, but only if usable later.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        // Waste is worse when few bins remain to absorb it (late stream).
        score += dead * dead * (10.0 + 40.0 * progress);
    } else {
        // Perfect fit: strong reward, stronger late.
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead coupling with next item (k=2).
    if next_item_size > 0 {
        let next_fits = (post_residual as u32) >= next_item_size;
        if next_fits {
            // Reward bins that can also host the next item, scaled by tightness.
            let tight = (next_item_size as f64) / (post_residual as f64);
            score -= 8.0 + 12.0 * tight;
        } else {
            // Penalize stranding: leftover space too small for the next item.
            let waste = post_residual as f64;
            score += 6.0 + waste * 0.3;
        }
        // If next item fits this bin EXACTLY after current placement, big reward.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones.
    score -= (open_bins_count as f64) * 1.5;

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it is a laggard bin; filling it reduces fragmentation.
    let lag = bin_residual as f64 - mean_residual;
    if lag > 0.0 {
        score -= lag * 0.15;
    } else {
        score += (-lag) * 0.05;
    }

    // New-bin candidate handling: a fresh empty bin should only win when the
    // item fits poorly everywhere else. Penalize opening a new bin.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0
            || (post_residual > 0 && post_residual < 10);
        if poor_fit_everywhere {
            score -= 15.0; // allow opening a new bin
        } else {
            // Penalize proportional to how many existing bins could host it.
            score += 25.0 + 10.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Mild exploration term: small non-monotone nudge based on progress,
    // encouraging diverse bin choices early, greedy consolidation late.
    score += (1.0 - progress) * ((step_index % 7) as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual (waste), with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Smooth progress coupling: later in stream, penalize larger residuals more
    let prog_term = 1.0 + 1.5 * progress * (1.0 - x) * (1.0 - x);
    score *= prog_term;

    // Cubic coupling of residual with mean residual: reward bins near mean fit
    let mean_norm = mean_residual / cap;
    score += 8.0 * (x - mean_norm) * (x - mean_norm) * (x - 0.5);

    // Tight fit reward: subtract when post residual is small but nonzero
    if post_residual > 0 {
        score -= 12.0 * (-3.0 * x).exp();
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / cap);
    }
    // If next item would be blocked by this placement, mild penalty scaled by tightness
    else if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0 * (1.0 - x);
    }

    // New bin candidate handling: penalize opening a new bin early/mid stream,
    // less so late when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - (mean_residual / cap).max(0.0);
        score = cap as f64 + 30.0 * (1.0 - progress) * fragmentation + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // ---- Perfect fit reward ----
    if post_residual == 0 {
        score -= 1000.0;
    }

    // ---- Harmonic classes: split residual space into 8 capacity-fraction classes ----
    // Class 0 (residual ~0) is excellent; middle classes create awkward dead space.
    let eighth = ((post_residual * 8) / bin_capacity) as f64; // 0..=7 integer class
    let class_penalty = match eighth as u32 {
        0 => -50.0,                       // nearly full bin: great
        1 => 5.0,                         // small leftover, usually reusable
        2 | 3 => 30.0,                    // awkward quarter-ish dead space
        4 | 5 => 45.0,                    // half-empty: worst fragmentation zone
        6 => 25.0,
        _ => 0.0,                         // near-empty bin handled by new-bin logic
    };
    score += class_penalty;

    // ---- Modulo-10 harmonic subclass: residuals just below common item sizes waste space ----
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // This leftover can't host the next item: penalize the shortfall.
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // ---- Lookahead coupling: reward bins that can also absorb the next item ----
    if next_item_size > 0 && post_residual >= next_item_size as f64 {
        // chain-fit bonus, stronger the tighter the chain fit
        let chain_tightness = (post_residual - next_item_size as f64) / cap;
        score -= 40.0 * (1.0 - chain_tightness);
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Only this open bin fits: strongly prefer it over opening a new bin,
        // unless the fit is terrible (huge post_residual already penalized).
        score -= 60.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: penalize proportionally to available slack in open bins,
        // but relax penalty late in the stream or when open bins are nearly full.
        if open_bins_count > 0 {
            let slack_pressure = mean_residual / cap; // high = lots of loose space
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 80.0 * slack_pressure * (1.0 - 0.5 * progress);
            // If the next item is huge and no open bin will hold it, opening fresh is fine
            if next_item_size > 0 && (next_item_size as f64) > mean_residual {
                score -= 50.0;
            }
        } else {
            score -= 100.0; // must open a bin
        }
    }

    // ---- Mild late-stream tightening: prefer closing bins out as stream ends ----
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    // Treat gaps < 10 as fully dead; gaps that cannot fit the lookahead item are half-dead.
    let dead = if post_residual == 0 { 0.0 } else if post_residual < 10 { (10 - post_residual) as f64 * 3.0 } else { 0.0 };
    score += dead;

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual can't serve the next item: penalize proportionally to how close it came.
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make an empty bin mildly unattractive unless it's genuinely better
    // (i.e., when existing fits are poor, the dead-space penalties above will dominate).
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.2;
        // Late in the stream, opening fresh bins is fine since residual mean is low.
        if mean_residual < 15.0 { score -= 10.0; }
    }

    // Slight preference for bins whose residual is close to mean residual (balance load).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: penalize bins that end up nearly full.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards; reward closeness of chained fit.
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
        // Reward residual slightly above next item (chainable), punish large waste.
        score -= 0.10 * (next_item_size as f64).min(post_residual as f64);
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (consolidate into fuller bins), penalize draining already-large residuals.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.25 * mean_gap;

    // Last-chance bin: strong reward to use the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when item is large (would leave tiny
    // unusable residue in existing bins) or few open bins exist.
    if bin_residual == bin_capacity {
        let waste_if_existing = mean_residual - item_size as f64;
        let new_bin_penalty = 8.0 + 0.15 * open_bins_count as f64;
        score += new_bin_penalty;
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 10.0; // large items start fresh bins cheaply
        }
        if waste_if_existing < 0.0 {
            // existing bins can't absorb well; make new bin more attractive
            score -= 1.5 * waste_if_existing.abs();
        }
    }

    // Mild stream-phase adaptation: early on, favor consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used to modulate risk appetite.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin wastes the residual of every other open bin.
        // Penalize proportionally to how many bins already exist and their
        // average leftover capacity that this decision strands.
        let stranded = mean_residual * (open_bins_count as f64).sqrt();
        score += 55.0 + stranded * 0.9;

        // Late in the stream, closing out with fresh bins is more acceptable
        // since stranded capacity has less time to be exploited.
        score -= progress * 20.0;

        // If no other bin can take the item, opening is mandatory: reward it.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Reward placements into bins where the leftover after placement is
        // either very small (perfect fit) or large enough to be reusable.
        let pr = post_residual as f64;
        if pr <= 5.0 {
            score -= 30.0; // near-perfect fit, kill the bin's dead space
        } else if pr >= 10.0 && pr <= 40.0 {
            // mid-range leftovers are the most reusable for typical items
            score -= 8.0;
        } else if pr > 60.0 {
            score += 6.0; // dumping a small item into a big bin is wasteful
        }

        // Lookahead: if the next item fits exactly into the post-residual,
        // this bin is a perfect pipeline; reward strongly.
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).abs();
            if gap == 0 {
                score -= 25.0;
            } else if (gap as f64) <= 5.0 {
                score -= 12.0;
            } else if next_item_size as f64 > pr {
                // next item won't fit here anyway; slight penalty for
                // leaving a residual that matches nothing
                score += 3.0;
            }
        }

        // Last-chance bin: if this is the only bin that can fit the item,
        // strongly prefer it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 45.0;
        } else if fitting_bins_count > 1 {
            // competition: prefer the bin where the fit is tightest,
            // which is already captured by post_residual, but add a mild
            // crowding bonus for consolidating into well-filled bins.
            let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
            score -= fill_ratio * 10.0;
        }

        // Global fragmentation pressure: when mean residual across bins is
        // low, bins are nearly full — favor keeping items out of the
        // remaining roomy bins only if this one is also tight; otherwise
        // prefer spreading to preserve large residuals.
        if mean_residual < 15.0 && post_residual > 30 {
            score -= 10.0;
        }

        // Early in the stream, be more willing to fill existing bins tightly
        // to build a good structure; late, prioritize just fitting.
        score += progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = x * (1.0 - 0.5 * x);

    // Non-linear polynomial coupling with stream progress:
    // early on, tolerate slack slightly (keep bins flexible);
    // late in stream, punish remaining slack more strongly.
    let prog_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += prog_term * x * x * 12.0;

    // Penalize dead space that is too small to hold the smallest plausible item,
    // weighted by how much of the stream remains.
    let remaining = 1.0 - progress;
    let dead = if x > 0.0 && x < 0.15 { (0.15 - x) * 30.0 } else { 0.0 };
    score += dead * remaining;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * prog_term;
    }

    // Lookahead: reward if next item fits into post_residual (smooth coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits = if nx <= x { 1.0 } else { 0.0 };
        let tightness = 1.0 - (x - nx).abs();
        score -= fits * (1.0 + tightness) * 3.0 * (0.5 + 0.5 * prog_term);
        // If next item does NOT fit, mildly penalize leaving a mid-range gap.
        if fits < 1.0 {
            score += x * (1.0 - x) * 2.0;
        }
    }

    // Slight preference for bins deviating below mean residual (balance load),
    // scaled by number of open bins.
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += dev * (open_bins_count as f64).ln_1p() * 0.5;

    // Mild bias toward opening new bins early (keeps options open),
    // discouraging new bins late when open bins fit.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += (1.0 - prog_term) * 2.0 - prog_term * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead-space classes".
    let post = post_residual as i64;
    let residue = post % 10;
    // Penalize awkward residues (1..=9 leftover) proportionally to how far from a
    // "harmonic" multiple of 10 they land; residue 0 is perfectly harmonic.
    let residue_penalty = (residue as f64) * (residue as f64) * 0.15;
    score += residue_penalty;

    // Integer-division thresholds: bins whose post_residual falls into small
    // buckets (<10) are nearly dead; reward pushing bins into these buckets.
    if post > 0 && post < 10 {
        score -= 8.0; // good: bin almost fully utilized
    } else if post == 0 {
        score -= 12.0; // perfect closure
    } else if post >= 90 {
        score += 6.0; // huge leftover: wasteful placement
    }

    // Capacity-fraction coupling: penalize if post_residual cannot host common
    // harmonic fractions of capacity (25, 50).
    if post > 0 && post < 25 {
        score += 3.0;
    }

    // Lookahead harmony: reward if next_item_size fits exactly into post_residual
    // or its harmonic sub-multiples.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size < post_residual {
            let nxt_res = (post_residual - next_item_size) % 10;
            score -= 2.0 - (nxt_res as f64) * 0.2;
        } else {
            score += 2.0; // next item won't fit here
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when the item
    // is large relative to capacity or open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = (open_bins_count as f64) * 0.3;
        score = (bin_capacity as f64) * 0.55 + crowding - 20.0 * progress;
        if item_size >= 50 {
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild mean-residual anchoring: prefer bins below the mean residual
    // (tighter packing) with a harmonic divisor on the gap.
    let gap = mean_residual - bin_residual as f64;
    if gap > 0.0 {
        score -= (gap / 10.0).floor() * 0.5;
    } else {
        score += (-gap / 10.0).floor() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized,
    // but a perfect (or near-perfect) fill is rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: prefer existing bins when many are open.
    if bin_residual != bin_capacity {
        score -= 3.0 * (open_bins_count as f64).sqrt();
    } else {
        // New-bin candidate: penalize unless it avoids a bad fit elsewhere.
        score += 8.0;
        // Opening a new bin is justified if the lookahead item would fit
        // the fresh residual better than the current item does.
        if next_item_size > 0 && next_item_size <= post_residual as u32 {
            score -= 6.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Late in the stream, consolidate harder.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (1.0 - post / cap);
    }

    // Slight preference for bins with residual close to the item (best-fit core).
    score += (post as f64).abs() * 0.1 * (mean_residual / cap.max(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to capacity, non-linearly.
        let waste = post_residual as f64 / cap;
        score += 40.0 * waste * waste;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 / (1.0 + gap);
        // Perfect chain: next item fills this bin exactly afterwards.
        if post_residual == next_item_size {
            score -= 400.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how much it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.8 * miss;
    }

    // Compare against mean residual: prefer bins below mean residual (tighter bins)
    // so loose bins stay available for future items.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Mild penalty for opening a new bin when many bins are already open and fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // But if it's late in the stream, new bins are cheaper (fewer future items to place).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness preference: strongly reward near-exact fills.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 2.5 * tightness * tightness * cap;

    // Penalize dead space that is too small to ever be useful again.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leaving a sliver the next item cannot use is wasteful.
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * item_size as f64;
    }

    // Penalize dumping small items into large-residual bins (fragmentation guard).
    if (item_size as f64) < 0.45 * (bin_residual as f64) && bin_residual != bin_capacity {
        score += 0.5 * (bin_residual as f64 - item_size as f64);
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into existing space rather than opening new bins.
    let pressure = open_bins_count as f64 * mean_residual / cap;
    if bin_residual != bin_capacity {
        score -= pressure.min(20.0);
    } else {
        // New-bin candidate: only attractive when existing bins fit poorly
        // (post_residual high relative to item) or pressure is low.
        score += 30.0 + pressure * 0.8;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // fresh bin is flexible for the lookahead item
        }
    }

    // Late in the stream, waste hurts more; tighten selection.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.35 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fits (low post_residual); later, tolerate larger residuals
    // to keep bins consolidated.
    let post_norm = post / cap;
    let phase = progress * (std::f64::consts::PI * 2.0);
    let coupling = 0.5 + 0.5 * (phase.sin());
    score += 18.0 * post_norm * post_norm * (1.0 - coupling);
    score -= 12.0 * post_norm * (1.0 - post_norm) * coupling;

    // Penalize leaving residuals that are too small to hold typical future items,
    // with a smooth quadratic dead-space term.
    let dead = if post > 0.0 { ((post - 10.0) / cap).max(0.0) } else { 0.0 };
    score += 9.0 * dead * dead;

    // Reward using nearly-full bins (small normalized residual) more as stream advances.
    score -= 6.0 * (1.0 - post_norm) * (0.3 + 0.7 * progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // Lookahead: reward if next item fits exactly into the post-residual (smooth term).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (post - nxt).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    }

    // Mild penalty when bin residual deviates far from mean residual (consolidation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "dead zones"
    // (very small leftovers that nothing can use) are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residual below smallest plausible item leaves waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post) / 10.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit is excellent
    }

    // Harmonic class: post_residual mod capacity fractions.
    // Residuals that are multiples of common small sizes (10,20,25,50) are reusable.
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
    if reusable {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Integer-division threshold: classify residual into bands via /10.
    let band = post_residual / 10;
    score -= match band {
        0 => 6.0,
        1 => 2.0,
        2 => 0.0,
        3 => -1.0,
        _ => -2.0,
    };

    // Lookahead coupling: if the next item fits the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else {
            // next item won't fit here; penalize proportional to leftover waste
            score += 0.05 * post;
        }
    } else {
        // last item: prefer tightest fit overall
        score += 0.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream when
        // consolidation matters less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 10.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            score -= 10.0;
        }
        if post_residual == 0 {
            score -= 100.0; // exact capacity item, must use fresh bin anyway
        }
    }

    // Mild pressure to prefer bins with larger residuals (first-fit-like tiebreak)
    score += 0.02 * (cap - bin_residual as f64);

    // Mean residual context: if this bin's residual is far below mean, it is an
    // outlier small bin — using it consolidates waste.
    if (bin_residual as f64) < mean_residual - 5.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..=9) are worst
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Medium dead space: mildly penalize gaps that likely fit nothing later
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 400.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate (empty bin): make it attractive only when current
    // bins would leave bad dead space; otherwise keep it mildly unattractive
    if bin_residual == bin_capacity {
        let dead_if_used_open = (bin_residual - item_size) < 10;
        if dead_if_used_open && fitting_bins_count > 0 {
            score -= 50.0; // opening fresh bin beats creating dead space
        } else {
            score += 40.0; // prefer reusing existing bins
        }
    }

    // Mean residual coupling: bins far below mean residual are "tighter",
    // slightly prefer filling tighter bins
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Late-stream tightening: near end, avoid leaving any residual
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: strongly reward post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving exactly enough room for the next item, penalize excess slack
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to the shortfall
        let shortfall = (next_item_size - post_residual) as f64;
        score += shortfall * 0.5;
    }

    // Penalize dead space: post_residual too small for any plausible item (1..=100)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Compare against mean residual: bins with residual below mean are scarcer, prefer filling them
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in stream: consolidation matters more; discourage opening new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty that grows with progress and open bins
        score += 15.0 + 40.0 * progress + (open_bins_count as f64).sqrt() * 4.0;
        // But allow opening when item is huge and no tight fit exists elsewhere
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to item size.
    if bin_residual > 0 {
        score -= (item_size as f64) * (item_size as f64) / (bin_residual as f64) * 0.5;
    }

    // Penalize very small dead space creation less if it's a near-perfect fit.
    if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in the post_residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0 + (next_item_size as f64) * 0.1;
        } else if (bin_residual as u32) >= next_item_size && (post_residual as u32) < next_item_size {
            score += 6.0;
        }
    }

    // New-bin candidate handling: only open a new bin when current item is large
    // and open bins have poor average fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Prefer new bin if item is big, mean residual is high (existing bins fragmented),
        // and we're late in the stream.
        let open_bonus = if item_size >= 50 { 10.0 } else { 0.0 };
        score += 30.0 - open_bonus - pressure * 40.0 - progress * 10.0;
    }

    // Slight preference for bins with residual above mean (keep fragmented bins for small items).
    if bin_residual > 0 && bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial coupling to progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Non-linear penalty for large dead space, amplified as the stream progresses
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits smoothly (post residual near zero)
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bin: smooth bonus when few fitting bins
    let fit_factor = 1.0 / fitting_bins_count as f64;
    score -= 5.0 * fit_factor * (1.0 - norm_pr);

    // Lookahead: reward if next item fits the post residual (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0);
        let fit_quality = 1.0 - fits / cap;
        score -= 4.0 * fit_quality * fit_quality;
        // penalize post residual that is almost-but-not-quite usable for next item
        score += 3.0 * (nxt - pr).max(0.0) / cap;
    }

    // Mild penalty for spreading across many open bins vs consolidation
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Coupling with mean residual: prefer bins deviating below mean (tighter bin)
    score += 0.5 * (mean_residual - pr) / cap;

    // New-bin candidate: penalize slightly so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;

    // Reward high fill fraction (tight packing) — harmonic weighting
    score -= 40.0 * fill_frac * fill_frac;

    // Harmonic class of post_residual: dead space quantization.
    // Small post_residual classes (<=5, <=10) are near-perfect fits.
    if post_residual == 0 {
        score -= 100.0; // perfect fit, huge reward
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score += 5.0;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10
    // pair well with typical item sizes; penalize odd/prime-ish dead space.
    let r10 = post_residual % 10;
    if r10 == 0 {
        score -= 8.0;
    } else if r10 >= 5 {
        score += 2.0 * (r10 as f64 - 4.0);
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward; if next item can't fit any residual we leave, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here after placement; leaving big residual wasted
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes (bin_capacity - item_size)
    // immediately; only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Late in stream, prefer closing out open bins rather than opening new ones
        score += 60.0 - 40.0 * progress;
        // If many bins already fit the item, opening new bin is wasteful
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // Perfect-fit impossibility check: item fills new bin exactly
        if item_size == bin_capacity {
            score -= 200.0;
        }
    }

    // Mild preference for tighter (smaller-residual) bins among equals
    score += 0.02 * (bin_residual as f64 - mean_residual);

    // Spread-aware: if open bins have large mean residual, be pickier about waste
    if mean_residual > 40.0 && post_residual > 30 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = (next_item_size as f64).min(cap);
    let item = item_size as f64;
    let open = open_bins_count as f64;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let mean = if mean_residual.is_finite() {
        mean_residual.clamp(0.0, cap)
    } else {
        0.0
    };

    let open_pressure = open / (open + 4.0);
    let fill_pressure = mean / cap;

    // Two-item lookahead: estimate residual after either packing the next item here,
    // or being forced to send it to a fresh bin.
    let mut effective_residual = post;
    let mut lookahead_dead = false;

    if next > 0.0 {
        if post >= next {
            effective_residual = post - next;
        } else {
            effective_residual = post + (cap - next);
            lookahead_dead = true;
        }
    }

    let mut score = effective_residual;

    // Reward tight current/next packing.
    if next > 0.0 && post >= next {
        let after_next = post - next;
        score -= 4.0 * (1.0 - after_next / cap);
        if after_next == 0.0 {
            score -= 6.0 + 3.0 * progress;
        }
    } else if post == 0.0 {
        // Exact current-item fit.
        score -= 4.0 + 2.0 * progress;
    }

    // Strict penalty for leaving a gap that cannot absorb the lookahead item.
    if lookahead_dead {
        let gap = next - post;
        let gap_ratio = gap / cap;
        score += 2.0
            + 6.0 * gap_ratio
            + 2.0 * open_pressure
            + 2.0 * progress
            + 0.03 * item;
    }

    // New-bin candidate pressure: only open when it clearly improves future packing.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 2.0;
        } else {
            score += 2.0
                + 5.0 * open_pressure
                + 2.5 * fill_pressure
                + 2.0 * progress;

            if fitting_bins_count == 1 {
                score += 3.0;
            }
        }
    } else {
        // Prefer already-open bins, especially when many bins are open or mean residual is high.
        score -= 0.5 + 2.0 * open_pressure + 1.5 * fill_pressure;

        // Last-chance pressure: using the only fitting bin avoids creating another bin.
        let scarcity = if fitting_bins_count <= 1 {
            1.0
        } else if fitting_bins_count == 2 {
            0.5
        } else {
            0.25
        };

        score -= 4.0 * scarcity + 0.03 * item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: strong reward, scaled by how snugly it fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 + 10.0 * snug;
        } else {
            // Next item does not fit: penalize wasted capacity relative to next item.
            let waste = (post_residual as f64 - next_item_size as f64).abs();
            score += waste * 0.3;
        }
        // If next item exactly fills the bin, huge bonus.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else {
        // Last item: simply minimize post_residual.
        score -= 5.0;
    }

    // Coupling with mean residual: prefer bins that deviate usefully.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening new bins when open bins exist with decent residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        score += 20.0 + 15.0 * pressure * (0.5 + 0.5 * progress);
        // But if next item would leave a large unusable gap in existing bins,
        // new bin becomes attractive: reduce penalty when lookahead waste is high.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 18.0;
        }
    }

    // Discard bins with tiny unusable residuals unless the item exactly fills them.
    if post_residual > 0 && post_residual < 10 && post_residual != 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize large dead space relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * dead_frac * 120.0;

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let fit_quality = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * fit_quality;
        } else {
            // Next item won't fit here; penalize slightly if we waste space.
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 90.0;
    } else if fitting_bins_count > 3 {
        // Many options: prefer tight fits, less urgency.
        score += 5.0;
    }

    // Global state coupling: many open bins with high mean residual
    // -> prefer filling existing bins over opening new ones.
    if bin_residual < bin_capacity {
        let pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
        score -= pressure * 20.0;
    }

    // Time horizon: early in stream, be more willing to open new bins
    // (keep flexibility); late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward late only if it's clearly better.
        let mut new_bin_score = 60.0 * (1.0 - progress);
        new_bin_score -= 40.0 * progress;
        score += new_bin_score;
    } else {
        score -= 25.0 * progress;
    }

    // Mild preference for bins that already have moderate content.
    let used_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 30.0 * used_frac * used_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Smooth polynomial coupling of post-residual with stream progress.
    // Early stream: prefer tight fits (low post-residual) strongly.
    // Late stream: tolerate larger residuals slightly to keep bins consolidated.
    let mut score = x * (1.0 + 0.8 * progress);

    // Non-linear penalty for awkward residuals that few future items can fill:
    // penalize mid-range dead space via a bump polynomial x*(1-x) shaped term.
    let bump = x * (1.0 - x);
    score += 6.0 * bump * (1.0 - progress);

    // Reward near-perfect fills smoothly.
    score -= 2.0 * (1.0 - x) * (1.0 - x) * (1.0 - 0.5 * progress);

    // Lookahead coupling: if next item fits the post-residual, reward this bin smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let tightness = 1.0 - ((pr - nxt) / cap);
            score -= 3.0 * tightness * (1.0 - progress * 0.5);
        } else {
            // Next item cannot follow here: mild smooth penalty proportional to overflow.
            score += 0.5 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how well it fits).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = 1.0 - x;
        score -= 4.0 * fit_quality;
    }

    // New-bin candidate: prefer opening a new bin early (many future items),
    // and when current residual would leave large unusable space.
    if bin_residual == bin_capacity {
        score = 8.0 * (1.0 - progress) + 6.0 * x * (1.0 - progress) + 2.0;
        // Penalize new bin more when many open bins exist and mean residual is high.
        score += 0.3 * (open_bins_count as f64).sqrt() + 0.02 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo 10: dead space that no item (>=1) can use is worst,
    // but small residues in low classes are reusable.
    let pr = post_residual;
    let cls = pr % 10;
    let div10 = pr / 10;
    // Penalize residues that are unlikely to match typical item sizes (items 1..100)
    // Residues divisible by 10 align with "round" item sizes -> reward
    if cls == 0 && pr > 0 {
        score -= 8.0;
    } else if cls <= 2 {
        score -= 2.0;
    } else if cls >= 8 {
        score += 3.0;
    }

    // Dead space thresholds via integer division
    if pr > 0 && pr < 10 {
        score += 15.0; // unusable sliver
    }
    if div10 >= 4 {
        score -= 2.0 * div10 as f64; // large residual still useful
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0);
            // harmonic match: next item's residue class complement
            if (pr % 10) == (next_item_size % 10) {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; mild penalty if this bin was the only option
            if fitting_bins_count == 1 {
                score -= 10.0; // still better to use last chance bin than open new
            } else {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let tight = if fitting_bins_count == 0 { 0.0 } else { (post_residual as f64) };
        score += 40.0 + 0.3 * open_bins_count as f64 - tight * 0.2;
        // open new bin early in stream or when mean residual is high (fragmented bins)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        if mean_residual > 30.0 {
            score += 10.0;
        }
    }

    // Prefer fuller bins: normalize by capacity fraction
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    // Mean residual coupling: placing into a bin below mean residual balances load
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (1..=9)
    // are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (post_residual small but usable).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Open-bins pressure: mildly discourage adding to bins when many bins open,
    // to keep residual distribution consolidated.
    score += open_bins_count as f64 * 0.4;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 25.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: penalize slightly unless near zero.
        if post_residual >= 10 {
            score += 8.0;
        }
    }

    // New-bin candidate: only attractive when open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        if pressure > 4.0 {
            score -= 10.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but heavily penalize
    // dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining: this bin will be closed next step
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to leftover waste
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless nothing fits well.
    // It has bin_residual == bin_capacity, so post_residual is large,
    // but ensure it never beats a good existing fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
    }

    // Late in stream: consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.05;

    // Penalize leaving dead space that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or the stream is late (waste grows with remaining items).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 + 30.0 * progress;
        // But opening a bin is attractive for large items that would leave big holes.
        if item_size >= 50 {
            score -= 20.0;
        }
        // If the current bin's post-residual would be awkward for the next item,
        // a fresh bin is more forgiving.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 15.0;
        }
    }

    // Prefer filling bins with larger residuals when mean residual is high
    // (many half-empty bins circulating): reduce fragmentation.
    score += (mean_residual - post_residual as f64) * 0.1;

    // Mildly prefer bins with lower residual early (pack tight early),
    // higher residual late (consolidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (bin_residual as f64 - post_residual as f64) * 0.05;

    // Penalize using very full bins for tiny items (waste of tight space).
    if item_size <= 20 && post_residual as f64 > mean_residual {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: post-residual (waste), with smooth non-linear polynomial shaping.
    let x = pr / cap; // normalized post-residual in [0,1]
    let mut score = pr * (1.0 + 0.8 * x * x + 0.4 * x * x * x);

    // Smooth coupling with stream progress: waste matters more as stream advances.
    score += 12.0 * progress * x * x;

    // Penalize dead space that no plausible next item can use (smooth via lookahead).
    let nx = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let g = gap / cap;
            score += 25.0 * g * g * (1.0 + progress);
        } else {
            // Reward bins where the next item also fits (chaining).
            score -= 8.0 * (1.0 - g.abs() / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty for opening a new bin, growing with progress and open-bin count.
    if is_new_bin {
        score += 6.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // But allow new bin if existing bins would leave very tight/awkward space.
        score += 15.0 * (1.0 - x) * (1.0 - x);
    }

    // Smooth mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.15 * (mean_residual - pr) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals in "dead" bands (small but
    // unusable for typical items) are penalized; large residuals are fine.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Integer-division thresholds on post_residual (classes of ~12 units)
    let class = post_residual / 12;
    score += match class {
        0 => 0.0,                      // residual < 12: near-perfect fit, reward
        1 => 6.0,                      // 12..24: awkward dead space
        2 => 3.0,
        3 => 1.0,
        4 => 0.5,
        _ => 0.0,
    };

    // Modulo coupling: residual that is congruent to small useful sizes
    // (10, 20, 30) is more likely reusable later.
    let m = post_residual % 30;
    if m == 0 && post_residual > 0 {
        score -= 4.0;
    } else if m < 10 && post_residual > 0 {
        score += 2.0; // sliver that only tiny items can use
    }

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty if we also create dead space
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when current bin would leave a
    // large awkward residual AND many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = (post_residual as f64) > 0.35 * cap && post_residual < 0.6 * cap;
        if awkward || open_bins_count > 4 {
            score -= 10.0 + 5.0 * progress;
        } else {
            score += 12.0; // prefer existing bins when fit is decent
        }
    }

    // Mild tie-break toward filling bins below the mean residual (compactness).
    if (bin_residual as f64) < mean_residual {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit reward
        score -= 25.0;
    }

    // Reward tight fits relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Lookahead: bonus if post_residual exactly accommodates next item,
    // penalty if post_residual is just barely too small for next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Pressure to consolidate: penalize new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Allow new bin only if mean residual is very small (nothing fits well anywhere)
        score -= 0.5 * mean_residual;
        // Late in stream, prefer filling existing bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild preference for bins below mean residual (balance consolidation).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: prefer tight fits (small post_residual), mildly superlinear.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            let gap = post - next;
            // Perfect chain (gap 0) gets strong reward; decays with gap size.
            score -= 40.0 * (-gap / 12.0).exp();
        } else {
            // Next item won't fit here: penalize a bit, worse the tighter this fit.
            score += 6.0 * (next - post) / bin_capacity as f64;
        }
    }

    // Relative to mean residual: favor bins that are more filled than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    // or the lookahead chain strongly favors a fresh bin.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 30.0 * (-gap / 10.0).exp();
        }
    }

    // Late in the stream: consolidate harder, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative wasted fraction nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item almost perfectly fills the remainder.
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * next_fit * next_fit;
    }
    // Penalize leaving a remainder that nothing typical can use (dead space).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Early stream: prefer consolidating into fewer bins; late stream: prefer tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64).ln().max(0.0);

    // Compare against mean residual: bins with residual far below mean are precious tight bins.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 3.0 * dev.sqrt();
    } else {
        score += 2.0 * (-dev).sqrt();
    }

    // New-bin candidate handling: make fresh bin attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted by stream progress.
        score = 45.0 + 40.0 * progress;
        // If item is large relative to capacity, opening fresh is reasonable.
        score -= 0.15 * item_size as f64;
        // If many bins fit the item, discourage opening a new one.
        score += 6.0 * (fitting_bins_count as f64);
        // Lookahead synergy: fresh bin can host next item too.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let mut score = pr * (1.0 + 0.5 * fit_norm * fit_norm);

    // Stream-progress coupling: early on, be greedy (fill tight); later, tolerate larger residuals
    // to keep bins balanced for future items.
    let progress_weight = 0.8 * t * (1.0 - t) * 4.0; // smooth bump peaking mid-stream
    score -= progress_weight * (cap - pr);

    // Penalize residuals that are too small to be useful (dead space), smoothly.
    let dead = if pr > 0.0 {
        let r = pr / cap;
        r * (1.0 - r) * (1.0 - r)
    } else {
        0.0
    };
    score += 30.0 * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post-residual, penalize otherwise (smooth).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        let fits = (next_item_size as f64 <= pr) as f64;
        score += 10.0 * (1.0 - fits) * (gap / cap).min(1.0);
        score -= 6.0 * fits * (1.0 - gap / cap);
    }

    // Mild penalty for opening new bins when many bins are open and mean residual is high.
    let new_bin = (bin_residual as f64 == cap) as f64;
    score += new_bin * (12.0 + 0.3 * open_bins_count as f64 + 0.1 * mean_residual);

    // Perfect fit reward (smooth quadratic trough at pr = 0).
    score -= 15.0 * ((cap - pr) / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Dead space: post_residual smaller than the smallest plausible item is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Harmonic classes of post_residual (mod 10 buckets): residuals that are
    // multiples of common item sizes keep future pairing options alive.
    let m = (post_residual % 10) as f64;
    score -= 8.0 * (1.0 - m / 10.0); // prefer residuals aligned to the class grid

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            score -= 15.0;
        } else {
            score += 20.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins are crowded
    // or mean residual is large relative to the item.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (item_size as f64) / mean_residual.max(1.0);
        if pressure > 1.5 {
            score -= 30.0;
        } else {
            score += 55.0; // prefer filling existing bins early on
        }
    }

    // Mild stream-progression term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Penalize bins far below the mean residual (they are already fragmented).
    if (bin_residual as f64) < mean_residual - 15.0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10] are pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Penalize large post_residuals less if next item can use them.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate / low-fill bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 15.0 + pressure;
    } else {
        // Mild reward for filling existing bins relative to mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
        score += 0.05 * pressure;
    }

    // Prefer tight fits: reward small post_residual nonlinearly.
    score += 0.2 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead fit: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
