        if post_residual == next_item_size {
            score -= 100.0;
        }
        // Penalize leaving dead space that next item cannot use
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - post_residual as f64 / 100.0);
        }
    }

    // Penalize large dead space relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 45.0;
        // If lookahead can't be satisfied by this fresh bin either, penalize more
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Tight fits are generally good
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small dead space that can't host typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: early in the stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Global residual pressure: if mean residual is high, prefer bins below mean
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit_everywhere = fitting_bins_count <= 1 || mean_residual < item_size as f64 * 0.5;
        if poor_fit_everywhere {
            score -= 10.0;
        } else {
            score += 40.0;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with polynomial smoothing
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth non-linear coupling with stream progress:
    // early on, keep flexibility (penalize very small residuals mildly);
    // late, pack tightly (penalize large residuals more).
    let flex = (1.0 - progress) * (norm_pr * (1.0 - norm_pr) * 4.0);
    score += 12.0 * flex;

    let tight = progress * (norm_pr * norm_pr);
    score += 20.0 * tight;

    // Dead-space penalty: residuals too small to hold typical future items
    let dead = if pr > 0.0 { (10.0 / (pr + 1.0)).powi(2) } else { 0.0 };
    score += dead;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap);
        score -= 8.0 * fit_quality * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap) * progress;
    }

    // Mild reward for reducing spread vs mean residual
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    // Slight penalty for opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes modulo 10 and 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Penalize dead space in "bad" harmonic classes (unusable slivers)
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny sliver, likely dead space
        } else if r10 == 0 {
            score -= 25.0; // perfectly decadal residual is reusable
        } else if r25 == 0 {
            score -= 15.0; // quarter-capacity aligned residual
        } else if r10 >= 5 {
            score -= 5.0; // half-decade residual moderately useful
        } else {
            score += 10.0 * (5 - r10) as f64 / 5.0;
        }
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match rewards
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 40.0;
            } else if gap % 10 == 0 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: prefer tightest fill
        score -= 30.0;
    }

    // Last-chance bin bonus: only fitting bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / bin_capacity as f64) * 20.0;
        score += 45.0 - pressure - (fitting_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 15.0; // lookahead favors fresh capacity
        }
    }

    // Progress-coupled tightness: late in stream, value tight fits more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.1 * progress;

    // Crowd control: many open bins with high mean residual -> prefer consolidation
    if open_bins_count > 2 && mean_residual > post_residual as f64 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot fit even a small item (min size 1..10),
    // or if it is small relative to the lookahead item.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver gap: strongly penalize proportionally to how useless it is.
            score += (10 - post_residual) as f64 * 8.0;
        } else if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.5 {
            // Gap likely unusable for the next item too: penalize.
            score += (next_item_size as f64 - post_residual as f64) * 3.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = if item_size > 0 { post_residual as f64 / item_size as f64 } else { 0.0 };
    score -= fit_ratio * -2.0; // equivalently: score += fit_ratio * 2.0 handled below

    // Penalize wasteful fits: exact fit is great, loose fit leaves big gaps.
    score += fit_ratio * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open
    // and the fit is reasonable.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open_bins_count grows.
        score += 10.0 + open_bins_count as f64 * 2.5;
        // Slightly less penalty late in the stream (consolidation phase).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 5.0;
    } else {
        // Mild reward for using existing bins, scaled by how full the bin already is.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 3.0 + fill * 5.0;
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // bins with residual close to item_size are ideal targets.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += residual_gap * 0.1;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual closely matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills the bin afterwards
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += diff * 0.8;
        }
        // If next item can fit into post_residual, mild reward proportional to fit tightness
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space creation, worse for small leftovers
            let waste = post_residual as f64;
            score += 0.3 * waste;
        }
    }

    // Tightness reward: prefer leaving small residuals overall
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // More open bins competing -> favor bins with residual near mean (balance)
    if open_bins_count > 1 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.2 * dev;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if next item also large and current fit leaves big unusable gap, allow new bin
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score -= 70.0;
        }
    }

    // Penalize very small unusable leftovers (< 10) as dead space
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Late in stream: consolidate, prefer filling existing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual (wasted space), nonlinearly.
    let waste = post_residual as f64;
    score += 0.35 * (waste * waste) / bin_capacity as f64;

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize leaving an awkward residual gap.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 8.0;
            }
        }
    }

    // Last-chance bonus: this is the only bin that fits; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good open bin exists
    // (e.g., many open bins with small residuals / item is large).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64;
        // Prefer new bin when open bins are crowded (mean residual small) and item is big.
        let crowded = mean_residual < item_size as f64 * 1.5;
        if crowded {
            score -= 20.0 + 10.0 * progress;
        } else {
            score += 30.0 + 2.0 * openness;
        }
        // Late in stream, mildly discourage proliferation of bins.
        score += 5.0 * progress;
    }

    // Mild reward for filling bins that are already well-used.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Penalize creating tiny dead space (< smallest plausible follow-up item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Global balance: prefer bins whose residual is near/below mean residual
    // (use up the emptier bins first, keep tight ones coherent).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Smooth non-linear coupling: penalize residual with stream-dependent exponent
    let expo = 1.5 + 2.5 * progress;
    score += 40.0 * prn.powf(expo) * progress;

    // Reward tight fits more strongly as stream progresses
    score -= 30.0 * (1.0 - prn).powf(2.0 + 3.0 * progress);

    // Penalize dead space relative to mean residual (smooth interaction)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - prn);
    }

    // Lookahead coupling: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr >= nxt) as i32 as f64;
        score -= 12.0 * fit_next * (1.0 - (pr - nxt).abs() / cap) * (1.0 + progress);
    }

    // New-bin candidate: penalize opening new bins unless residual is large
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (fitting_bins_count as f64) / (1.0 + open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Harmonic class of post_residual modulo 10: small-dead-space classes
    let pr_mod = (post_residual % 10) as f64;
    score += pr_mod * 0.35;

    // Integer-division threshold: post_residual in [1,9] is prime dead space; reward it
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    }
    // post_residual in a "harmonic band" of capacity fractions
    let frac = pr / cap;
    if frac > 0.5 {
        score += 8.0; // wasteful: leaving >half a bin empty
    } else if frac < 0.05 {
        score -= 3.0; // nearly perfect fill
    }

    // Lookahead coupling: can next item exactly fill this bin's post_residual?
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0; // perfect chain
    } else if next_item_size > 0 && next_item_size < post_residual {
        // harmonic class match: next item leaves post_residual - next in small class
        let chain_rem = post_residual - next_item_size;
        if chain_rem < 10 {
            score -= 5.0;
        }
        score += (chain_rem % 10) as f64 * 0.25;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use leftover: penalize proportionally
        score += ((next_item_size - post_residual) as f64) * 0.12;
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline penalty so open bins with decent fit win
        score += 12.0;
        // but if many open bins are fragmented (high mean residual), allow a fresh bin
        if mean_residual > 45.0 && open_bins_count > 2 {
            score -= 10.0;
        }
        if progress > 0.7 {
            score -= 3.0; // late stream: fresh bins amortize better
        }
    }

    // Prefer using fuller bins: penalize bins far above mean residual
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.08;

    // Mild pressure against bin sprawl
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are small but nonzero are
    // "unusable" for future items (min item size 1, but typical items larger),
    // so penalize gaps in the awkward 1..~20 band super-linearly.
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post) * (20.0 - post) * 0.5;
    }
    // Perfect fit is heavily rewarded.
    if post == 0.0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: more open bins -> penalize spreading, encourage
    // tight packing into existing bins; few bins -> allow consolidation.
    let pressure = (open_bins_count as f64).ln() * 2.0;
    if bin_residual != bin_capacity {
        score -= pressure * (1.0 - post / cap);
    } else {
        // New-bin candidate: penalize by open-bin count and by mean residual
        // of existing bins (wasted capacity already out there).
        score += pressure * 1.5 + mean_residual * 0.1;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post > 0.0 {
        score += 3.0;
    }

    // Late in the stream, be more conservative about opening bins.
    if step_index + 1 >= total_items {
        if bin_residual == bin_capacity {
            score += 40.0;
        } else {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits the post_residual exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chaining: next item consumes the remaining space.
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize large leftover after the hypothetical next placement (dead space).
            score += 0.05 * slack;
        } else {
            // Next item cannot use this bin's leftover; penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.08 * gap;
        }
    } else {
        // Last item: pure tightness matters.
        score -= 8.0 * tightness;
    }

    // Compare against mean residual: prefer bins whose residual is above-average
    // (they absorb big items) but reward below-average residual when the fit is tight.
    let dev = bin_residual as f64 - mean_residual;
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    } else if dev > 0.0 {
        score += 0.03 * dev; // large-residual bins are flexible; slight penalty for wasting them
    } else {
        score -= 0.02 * dev.abs() * tightness; // small bins used tightly are good
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a new bin is wasteful early and when open bins fit;
    // encourage it only when item is large relative to residual of a full bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 25.0 + 15.0 * (1.0 - progress) + 10.0 * waste;
        // If next item is huge and nothing open fits, new bin may still be right;
        // soften penalty when lookahead suggests a fresh bin chains well.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 18.0;
        }
    }

    // Mild penalty per number of open bins to consolidate usage.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly; tiny residuals are gold.
    let pr = post_residual as f64;
    if pr > 0.0 {
        score += 400.0 / pr;
    } else {
        score -= 30.0; // perfect fit bonus
    }

    // Reward tight fill relative to capacity.
    score -= 0.4 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            if slack <= 5.0 {
                score -= 20.0;
            } else {
                score += 0.15 * slack;
            }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Time horizon: early in stream, be conservative (prefer filling existing bins well);
    // late in stream, favor closing bins tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * pr / (bin_capacity as f64);

    // Global state: many open bins -> penalize opening/spreading; low mean residual -> prefer tight bins.
    score += 0.3 * (open_bins_count as f64);
    score += 0.5 * (mean_residual - pr).abs();

    // New-bin candidate: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        if fitting_bins_count >= 1 && pr > 40.0 {
            score -= 12.0; // allow opening fresh bin when waste would be big
        } else {
            score += 15.0 + 0.1 * poor_fit;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual weighted by stream progress
    let progress_coupling = norm_pr * (0.5 + progress) * (1.0 - norm_item);
    score += 30.0 * progress_coupling * progress_coupling;

    // Penalize tight fits less as stream progresses (dead space less valuable later)
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (1.0 - progress);

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (norm_pr - norm_next) / (1.0 - norm_next.max(0.001));
        score -= 8.0 * gap * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr * norm_pr);
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64).ln() * 2.0 * progress;

    // Penalize deviation from mean residual (prefer balanced fills)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: make empty bin moderately attractive early, less late
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * progress * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class: integer division of post_residual into bands
    let band = post_residual / 10; // 0..=10 bands
    // Reward tight fits: lower post_residual gets large subtraction
    score -= (10 - band as f64) * 6.0;

    // Modulo-arithmetic dead-space penalty: residuals that are "awkward"
    // (not multiples of 10, not small) are harder to fill later.
    let rem10 = post_residual % 10;
    if rem10 != 0 {
        score += rem10 as f64 * 1.5;
    }
    // Odd harmonic classes (post_residual % 20 in {1,3,5,...}) slightly worse
    if post_residual % 20 >= 10 && post_residual % 20 <= 19 && post_residual > 0 {
        score += 4.0;
    }

    // Perfect fit: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // harmonic class of leftover after next item
            let after_next = post_residual - next_item_size;
            let band2 = after_next / 10;
            score += band2 as f64 * 3.0;
            if after_next % 10 != 0 {
                score += 2.0;
            }
        } else {
            // next item won't fit here: penalize small post_residuals (dead space)
            if post_residual < next_item_size && post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should lose unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early (long horizon to fill it) and when mean residual is large/fragmented
        let fragmentation = mean_residual / cap;
        score = cap * (0.9 - 0.6 * (1.0 - fragmentation)) - 30.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 200.0;
        }
        // If many fitting bins exist, opening a new bin is wasteful
        if fitting_bins_count > 2 {
            score += 60.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins relative to items -> prefer existing bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are >= 10 typically, but allow for 1..100 streams).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    } else if post_residual < 20 {
        score += 15.0; // risky gap
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let poor_fit = (bin_residual - item_size) as f64; // large = wasteful placement elsewhere
        let mean_gap = mean_residual - item_size as f64;
        score += 45.0;                 // base resistance to opening new bins
        score -= 0.35 * pressure;      // pressure: many open bins -> consolidation is bad
        score -= 0.5 * mean_gap.max(0.0); // existing bins are loose -> don't open new
        score += 0.25 * poor_fit.max(0.0); // all placements would waste space -> new bin ok
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item won't fit here anyway; keep gaps flexible
    }

    // Mild open-bin pressure: discourage spreading across too many bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that cannot fit a typical item (min size ~1..10).
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * 40.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual,
    // penalize if post_residual is just barely too small for next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to the gap.
            score += 30.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it unattractive unless open bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Late in stream, opening new bins is fine; early on prefer filling existing.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * progress;
        // If many bins fit the item, definitely avoid a new bin.
        score += 50.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Slight preference for tighter original residual (denser bins first).
    score += (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that nothing else could use (post residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty if we leave awkward large gap.
            let gap = post_residual as f64;
            if gap > next_item_size as f64 * 0.5 && gap < next_item_size as f64 {
                score += 5.0;
            }
        }
    }

    // Prefer bins with residuals below mean (consolidate small spaces).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: make empty bins attractive only when current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (open_bins_count as f64) * mean_residual / bin_capacity as f64;
        // Opening a new bin is favored when many bins are highly fragmented late in stream.
        let pressure = fragmentation * (0.5 + progress);
        score = bin_capacity as f64 - 15.0 * pressure;
        // But discourage opening new bins when a good fit exists elsewhere.
        if fitting_bins_count > 0 && fit_ratio > 0.7 {
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0; // next item needs fresh bin anyway
        }
    }

    // Mild time-horizon term: early on, be slightly greedy toward balance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap; // 0..1 residual fraction after placement

    // Base: prefer tight fits (low post_residual), with non-linear squaring
    // so small residuals are rewarded disproportionately.
    let mut score = post + 30.0 * norm_post * norm_post;

    // Smooth stream-progress coupling: late in the stream, dead space is more
    // costly (fewer chances to fill it), so amplify the penalty on residual.
    let late = progress * progress;
    score += 40.0 * late * norm_post * (1.0 - norm_post) * 4.0;

    // Lookahead synergy: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            // residual too small for the next item: mild penalty growing with waste
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin (smooth in fitting_bins_count).
    if fitting_bins_count <= 1 {
        score -= 25.0;
    } else {
        score -= 12.0 / fitting_bins_count as f64;
    }

    // Mild preference for consolidating into bins below mean residual
    // (keeps large-residual bins available for larger future items).
    score += 5.0 * ((post - mean_residual) / cap);

    // Slight incentive to use existing bins over opening new ones early,
    // decaying as the stream progresses (new bins become more acceptable later).
    score += 10.0 * (1.0 - progress);

    // Penalize very fragmented open-bin state smoothly.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 buckets.
    let class = post_residual % 10;
    // Residuals in "waste classes" (small leftovers) are dead space -> penalize.
    if class <= 3 {
        score += (4 - class as f64) * 12.0;
    } else if class >= 7 {
        // Large chunky residuals are reusable -> reward.
        score -= class as f64 * 0.6;
    }

    // Integer-division thresholds: how many small items (<=10) fit later.
    let small_fits = post_residual / 10;
    score -= small_fits as f64 * 3.0;

    // Perfect-ish fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Harmonic bonus: post_residual and next item share a class.
            if post_residual % 10 == next_item_size % 10 {
                score -= 6.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 30.0;
        // Cheaper to open new bin early in stream (more future use of it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // If current bin would leave a tiny residue, new bin looks better.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
    }

    // Prefer filling bins with large residuals relative to mean (balance avoidance).
    if (bin_residual as f64) > mean_residual * 1.3 {
        score -= 4.0;
    }

    // Slight preference for fewer open bins when fit is decent.
    if post_residual >= 20 {
        score -= open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    } else if post_residual <= 50 {
        score += (50.0 - post_residual as f64) * 0.4;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space relative to bin capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Open bins pressure: prefer reusing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 8.0;
    }

    // Stream progression: early on, be conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a non-linear penalty
    // for leaving awkward mid-range dead space.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let dead_zone = (pr / cap - 0.5).abs();
    score += 30.0 * dead_zone * dead_zone * cap; // penalize residuals near half capacity

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        // Strong reward if the next item fits snugly too (chained packing).
        score -= 40.0 * (1.0 - slack_after_next / cap);
        // Extra reward for a near-perfect chain (post_residual == next_item_size).
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // This bin would be "closed" for future use; penalize relative to how
        // far the next item misses fitting.
        let miss = (next_item_size - post_residual) as f64;
        score += 10.0 * (miss / cap).min(1.0);
    }

    // Relative-to-mean coupling: placing into a bin with residual far below
    // mean (a tight bin) is good; placing into an above-mean residual bin
    // wastes packing potential.
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: a fresh bin is only attractive when no open
    // bin gives a good fit (post_residual large relative to capacity) or when
    // the item is large and lookahead suggests a fresh bin packs better.
    if bin_residual == bin_capacity {
        let fit_quality = pr / cap; // 1.0 - item_size/cap for a fresh bin
        // Penalize fresh bins mildly by default.
        score += 20.0;
        // But reward a fresh bin when the item is huge (poor fits everywhere)
        // or when the lookahead pair packs cleanly in a fresh bin.
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.7 {
            score -= 30.0 * item_frac;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            let pair = (item_size + next_item_size) as f64 / cap;
            if pair > 0.85 {
                score -= 45.0 * (pair - 0.85) / 0.15;
            }
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If many bins are already open, discourage more.
        score += (open_bins_count as f64).ln().max(0.0) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional waste relative to capacity.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 12.0;

    // Penalize dead space: small post_residual is good, but post_residual that
    // is too small to fit any plausible item (<= 10) is wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty proportional to leftover
            score += (post_residual as f64) * 0.15;
        }
    } else {
        // Last item: pure waste minimization, just keep base score.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
        if tightness > 0.8 {
            score -= 15.0; // good fit AND last chance: strongly prefer
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading out.
    let pressure = (open_bins_count as f64) * mean_residual / (bin_capacity as f64);
    score -= pressure * 0.5;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Penalize it by default so consolidation wins, but relax the penalty when
    // the item fits poorly everywhere (large item, few fitting bins).
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size > bin_capacity / 2 {
            score -= 20.0; // big items are fine in fresh bins
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good existing option: allow new bin
        }
        // Late in the stream, prefer closing out bins over opening new ones.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild time-horizon modulation: early on, be more exploratory (favor
    // spreading into new bins); late, favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    // Exact fill is always perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // Prefer tight fits: penalize small post_residual less than raw value suggests
    let tight = 1.0 - (pr / cap);
    score -= 25.0 * tight * tight;
    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate large residuals (keep bins flexible);
    // later, aggressively prefer minimal post_residual.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (pr / cap) * (pr / cap) * 40.0;
    // Lookahead: if next item fits exactly into post_residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fill = (next_item_size as f64) / pr.max(1.0);
        score -= 15.0 * fill;
    }
    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // Mild penalty relative to mean residual to keep bins balanced
    score += 0.05 * (pr - mean_residual);
    // Penalize very large residual waste nonlinearly (dead space)
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (1.0 - pr / 10.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: quarters of capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post_u = post_residual;

    // Reward near-perfect fits strongly.
    if post_u == 0 {
        score -= 1000.0;
    } else if post_u <= quarter / 4 {
        score -= 200.0;
    } else if post_u <= quarter / 2 {
        score -= 80.0;
    } else if post_u <= quarter {
        score -= 30.0;
    } else if post_u <= half {
        score -= 5.0;
    } else {
        // Large dead space: penalize progressively.
        score += (post - half) * 0.5;
    }

    // Harmonic coupling: can the lookahead item exactly fill the leftover?
    if next_item_size > 0 {
        if next_item_size == post_u {
            score -= 500.0; // perfect chain
        } else if next_item_size < post_u {
            let next_post = post_u - next_item_size;
            // Reward if the chain leaves a usable harmonic remainder.
            if next_post <= quarter / 2 {
                score -= 120.0;
            } else if next_post <= quarter {
                score -= 40.0;
            } else if next_post > half {
                score += (next_post as f64 - half) * 0.3;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize small leftovers
            // (wasted) more when they fall in "dead" classes (1..quarter/2).
            if post_u > 0 && post_u < quarter / 2 {
                score += 60.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: prefer it only when item is huge relative to mean residual
    // or no good fit exists. Give empty bin a mild baseline penalty so real bins win.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if the item is large (>= half capacity), a fresh bin is attractive.
        if item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
        // Late in stream with many open bins, avoid opening more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0 + open_bins_count as f64 * 2.0;
    }

    // Mild tie-breaking: prefer bins whose residual is near the mean (typical class).
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it can only fit tiny items; the tighter the fit
    // (small post_residual) the better, but gaps that are too small to be useful
    // are worse than moderately large gaps.
    let post = post_residual as f64;
    if post > 0.0 {
        // penalize gaps that are too small for typical items (below ~15% capacity)
        if post < 0.15 * bin_capacity as f64 {
            score += 3.0 * (0.15 * bin_capacity as f64 - post);
        }
        // reward very tight fits (near-zero waste) strongly
        if post <= 2.0 {
            score -= 10.0;
        }
    } else {
        // perfect fill: extremely desirable
        score -= 25.0;
    }

    // Open-bins pressure: prefer reusing bins when many bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    score -= 0.3 * bin_pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive if no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // base penalty so a fresh bin is chosen only when placements are poor
        score += 8.0;
        // if mean residual of open bins is large, opening a new bin is wasteful
        score += 0.5 * mean_residual;
        // early in stream, opening bins is cheaper (need spread); later, reuse
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits snugly into the post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() <= 3.0 {
        score -= 6.0;
    }
    // penalize if post_residual is just barely too small for the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect/near-perfect match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // exact two-item completion
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // smaller slack => better chain; steep decay
            score -= 40.0 * (-slack / 18.0).exp();
        } else {
            // next item cannot follow: penalize proportionally to leftover waste
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 + gap * 0.25;
        }
    }

    // Compare post_residual against mean residual: leaving near-average residual
    // keeps flexibility for the stream; extreme small residuals are dead space.
    let pr = post_residual as f64;
    if pr < 10.0 {
        score += (10.0 - pr) * 1.5; // tiny dead space penalty
    } else {
        score -= (pr - mean_residual).abs() * -0.15; // mild reward for matching mean
        score -= 0.15 * (pr - mean_residual).abs();
    }

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if no good chain exists elsewhere.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score += 8.0; // opening a bin tailored to large next item
        }
    }

    // Late in stream: prioritize closing bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 4.0 * (100.0 - pr) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize creating
    // unusable dead space (< 10, since min item size is 1... use graded penalty).
    if post_residual > 0 && post_residual < 5 {
        score += 12.0; // tiny dead space is nearly wasted capacity
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Penalize opening a new bin when other bins fit, scaled by how well
    // the current stream is progressing and how much slack exists globally.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let slack = mean_residual / bin_capacity as f64;
        // If open bins have plenty of slack on average, opening new bins is wasteful.
        score += 20.0 + 15.0 * slack + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // Early stream: keep bins open, consolidate.
        if progress < 0.3 {
            score += 10.0;
        }
    }

    // Global congestion: many open bins with low mean residual -> consolidate
    // into whatever fits best; tighten competition.
    if open_bins_count > 3 {
        score += (open_bins_count as f64).ln() * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is close to item size (relative waste measure).
    let rel_waste = post_residual as f64 / bin_residual.max(1) as f64;
    score += 10.0 * rel_waste;

    // Mild bonus for filling bins that are already partially depleted relative
    // to the mean residual (balances load across bins).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: penalize large residuals early, reward them late
    let x = pr / cap; // normalized post residual in [0,1]
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-style shaping
    score += poly * cap * (0.6 - 0.4 * progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - poly) * item_size as f64 * (0.5 + progress);

    // Lookahead: if next item fits exactly into post residual, reward heavily
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_gap = pr - next_item_size as f64;
        score -= (1.0 - fit_gap / cap) * 12.0 * (1.0 - progress);
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: open new bins early or when residual would be tiny dead space
    if bin_residual == bin_capacity {
        let dead = pr / cap;
        score = pr + 8.0 - 6.0 * progress + dead * 20.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 10.0;
        }
    }

    // Slight penalty for spreading across many open bins when residuals are large
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // --- Tight-fit reward: large item consumption is good ---
    score -= item_size as f64 * 0.45;

    // --- Dead-space penalty for tiny post_residual slivers (unusable) ---
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }
    // Harmonic class: post_residual divisible by 10 leaves reusable chunks
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // --- Lookahead (k=2): reward bins that can also host the next item ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainable: bonus scaled by how well next item nests
            let nest = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 6.0 + 8.0 * nest;
            // harmonic pair: next_item + post_residual hitting a decade boundary
            if (next_item_size + post_residual) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: mild penalty
            score += 3.0;
        }
    }

    // --- Last-chance bonus: only this bin can fit the item ---
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // --- Crowd-awareness: when many bins are open, prefer consolidation ---
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // --- Mean residual coupling: bins far below mean residual are attractive ---
    score -= (mean_residual - post_residual as f64) * 0.15;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized; only wins when open bins waste more
        // space than the fresh bin's post_residual + surcharge.
        let surcharge = 10.0 + item_size as f64 * 0.08 + progress * 5.0;
        // If item is huge relative to capacity, fresh bin is more acceptable
        let relief = if item_size as f64 / cap > 0.7 { 8.0 } else { 0.0 };
        score += surcharge - relief;
    }

    // --- Progress-dependent greed: late in stream, prefer tightest fits ---
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are pure waste.
    if post_residual < 10 {
        // Perfect fill — reward strongly.
        score -= 60.0;
    } else if post_residual <= 20 {
        // Small unusable-ish gap for typical item sizes: heavy penalty.
        score += 35.0;
    } else if post_residual <= 40 {
        score += 12.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This placement strands the next item: penalize.
        score += 15.0;
    }

    // Mean-residual coupling: bins deviating below mean residual are tighter fits.
    score += 0.10 * (mean_residual - bin_residual as f64);

    // Slight late-stream conservatism: keep residual space flexible early on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is only attractive when this is
    // a fresh empty bin AND current bins are nearly full.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        if mean_fullness > 0.85 {
            score -= 20.0; // open a fresh bin when others are nearly exhausted
        } else {
            score += 45.0; // discourage abandoning usable open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: reward tight chaining (small slack after both placements).
            let two_step_slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - two_step_slack * 0.5;
            if post_residual == next_item_size {
                score -= 40.0; // perfect 2-step fill
            }
        } else {
            // Next item cannot follow: penalize more when leftover is small/unusable.
            let waste = (post_residual as f64) / bin_capacity as f64;
            if post_residual < 10 {
                score += 25.0; // dead space creation
            } else {
                score += waste * 10.0;
            }
        }
    } else {
        // Last item: just prefer tightest fit.
        score += 0.0;
    }

    // Prefer bins with residual below mean (converging toward tight packing),
    // but keep some attraction to larger residuals for big items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += ((bin_residual as f64) - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mild penalty on new-bin candidate to prefer reuse unless lookahead strongly favors it.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 0.5;
    }

    // Late-stream bias: consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Dead space penalty: post_residual that is too small to be useful later.
    if post_residual < 10 {
        score -= 25.0; // perfect-ish fill, excellent
    } else if post_residual <= 20 {
        score += 5.0;
    }

    // Lookahead: strongly prefer bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize stranding residual that can't fit the lookahead
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0 - 20.0 * (1.0 - fit_ratio);
    }

    // New-bin candidate: penalize opening a new bin, more so when good
    // fitting bins exist or the stream is late (waste amortization).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 25.0 * progress;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // A new bin is attractive only for huge items that likely won't fit elsewhere well.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Prefer filling bins with larger residuals (reduce bin count pressure),
    // but modulate by global mean residual to avoid fragmenting many bins.
    score -= 0.10 * (bin_residual as f64 - mean_residual);

    // Slight preference for using fewer open bins: filling any bin is good
    // when many are open.
    score -= 0.05 * open_bins_count as f64 * fit_ratio;

    // Time horizon: early in the stream, be more conservative (keep bins flexible);
    // late in the stream, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post-residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + progress) - norm_pr * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits, smoothly scaled by progress
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.6 + 0.4 * progress);

    // Penalize dead space that next item cannot use (smooth interaction)
    let unusable = (pr as f64 - norm_next * cap).max(0.0) / cap;
    score += 15.0 * unusable * unusable;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_item);
    }

    // Slight penalty for spreading across many open bins late in stream
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate: mild penalty so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // New-bin candidate: neutral baseline, chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 * 0.5;
        let pressure = if fitting_bins_count <= 1 { -30.0 } else { 0.0 };
        return base + pressure + (open_bins_count as f64) * 0.5;
    }

    // Harmonic class of post_residual (mod 10 buckets): dead space that is a
    // multiple of 10 is more reusable for typical item granularities.
    let class = post_residual % 10;
    let harmonic_bonus = match class {
        0 => 12.0,
        1 | 9 => 2.0,
        2 | 8 => 4.0,
        3 | 7 => 6.0,
        4 | 6 => 8.0,
        _ => 10.0,
    };
    score -= harmonic_bonus;

    // Lookahead: does post_residual still accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible, reward proportionally.
            score -= 10.0 + (next_item_size as f64) * 0.15;
        } else if post_residual > 0 {
            // Dead space: cannot host next item -> penalize harder for small residue.
            let waste = post_residual as f64 / (next_item_size as f64);
            score += 8.0 + 20.0 * (1.0 - waste.min(1.0));
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += (fitting_bins_count as f64) * 0.3;
    }

    // Prefer bins tighter than the mean (best-fit flavor), scaled by progress.
    let tightness = mean_residual - bin_residual as f64;
    score += tightness * (0.2 + 0.3 * progress);

    // Late in the stream, avoid leaving tiny unusable residues.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (0.5 + progress);
    }

    // Integer-division threshold: half-full or more residual is attractive.
    if post_residual >= bin_capacity / 2 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the minimum
    // item size (1..100, but typically small items exist) are wasted capacity.
    // Penalize unusable slivers heavily; reward perfectly tight fits.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 30.0; // perfect fit, best possible outcome
    } else if post_residual < 10 {
        // dead space: gap too small for most items -> strong penalty
        score += (10.0 - pr) * 4.0;
    }

    // Fit ratio reward: the fuller the bin becomes relative to its residual,
    // the better (encourages filling large gaps with large items).
    if bin_residual > 0 {
        score -= (item_size as f64 / bin_residual as f64) * 12.0;
    }

    // New-bin candidate: penalize opening a new bin, more strongly when
    // other open bins could also fit the item.
    if bin_residual == bin_capacity {
        score += 18.0 + (fitting_bins_count as f64) * 6.0;
    }

    // Last-chance bonus: if this is the ONLY bin that fits, using it avoids
    // opening a new bin; reward strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, consolidation is valuable.
    // Scale the tight-fit reward by how fragmented the state is.
    let fragmentation = (open_bins_count as f64) / ((open_bins_count as f64) + 5.0);
    score -= fragmentation * 3.0;

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement is excellent; if post_residual is just barely too small
    // for the next item, the dead space is confirmed bad.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let r = (post / cap).clamp(0.0, 1.0);
    let item_n = (item_size as f64 / cap).clamp(0.0, 1.0);
    let mean_res = mean_residual.max(0.0).min(cap);
    let mean_n = mean_res / cap;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };
    let remaining = 1.0 - progress;

    let next = if next_item_size > 0 && next_item_size <= bin_capacity {
        next_item_size as f64
    } else {
        0.0
    };
    let has_next = next > 0.0;
    let is_new_bin = bin_residual == bin_capacity;
    let next_fits_here = has_next && post + 1e-9 >= next;
    let exact_next = has_next && post_residual == next_item_size;

    let scarcity = if has_next {
        ((next - mean_res) / cap).clamp(0.0, 1.0)
    } else {
        0.0
    };
    let abundance = if has_next {
        ((mean_res - next) / cap).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let mut score = 1.8 * r
        + 1.1 * r * r
        + 0.15 * item_n * r
        + 0.35 * (r - mean_n);

    if post_residual == 0 {
        score -= 0.15;
    }

    if has_next {
        let gap = post - next;

        if exact_next {
            score -= 1.15
                + 2.2 * r
                + 0.45 * remaining
                + 0.55 * scarcity;
        } else if gap > 0.0 {
            let scale = 8.0 + 0.30 * mean_res + 0.25 * next;
            score -= (0.55 + 0.75 * r) * (-gap / scale).exp();
        } else {
            let miss = -gap;
            score += 0.45 * (miss / cap) * (0.30 + r);
        }
    }

    if !is_new_bin {
        if fitting_bins_count == 1 {
            let strong_last_chance = !has_next || next_fits_here;
            let last_chance_bonus = if strong_last_chance {
                0.85 + 0.45 * remaining
            } else {
                0.20 + 0.15 * remaining
            };
            score -= last_chance_bonus;
        }
    } else {
        let mut opening_penalty = 1.05
            + 0.035 * open_bins_count as f64
            + 0.05 * fitting_bins_count as f64
            + 0.08 * (1.0 - item_n);

        if fitting_bins_count == 0 {
            opening_penalty *= 0.15;
        }

        if !has_next {
            opening_penalty += 0.85;
        }

        if exact_next {
            opening_penalty *= 0.35;
            opening_penalty += 1.1 * abundance + 0.10 * open_bins_count as f64;
        }

        score += opening_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= tightness * tightness * 30.0;

    // Perfect fill is gold.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead space penalty: unusable residual (no future item can plausibly fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / cap) * 15.0;
        } else {
            // next item won't fit here anyway; slight penalty if we leave a gap it almost fits
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += gap * 0.5;
            }
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer fuller bins among many open bins (mild best-fit reinforcement).
    if open_bins_count > 1 {
        let fullness = 1.0 - (bin_residual as f64) / cap;
        score -= fullness * 10.0;
    }

    // Compare against mean residual: bins below mean residual are more packed -> favor.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Early in the stream: be slightly more willing to keep bins consolidated.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    // New-bin candidate handling: only attractive when item is huge relative to
    // typical residuals or all open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base new-bin score: post_residual (= cap - item) already large.
        // Penalize opening a new bin unless the item barely fits anywhere else.
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else {
            let item_frac = item_size as f64 / cap;
            // Opening is reasonable for large items that would waste a packed bin.
            score += 40.0 - 30.0 * item_frac;
            if fitting_bins_count == 1 {
                score += 25.0; // competing with the lone fitting bin's last-chance bonus
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with smooth non-linear shrink over time
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 20.0 * coupling;

    // Penalize large dead space relative to mean residual (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Reward near-perfect fits smoothly (small post_residual rewarded more later)
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Last-chance bonus: only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    }

    // Mild penalty for opening new bins late when many bins already open
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual bucketed by capacity fractions.
    let q = (post_residual * 4) / bin_capacity; // 0..3 harmonic quartile of leftover
    match q {
        0 => score -= 12.0,           // near-perfect fit: leftover < C/4
        1 => score -= 4.0,            // decent leftover
        2 => score += 2.0,            // half-ish leftover, mediocre
        _ => score += 8.0,            // huge leftover wasted
    }

    // Integer-division threshold: exact-fill classes (post_residual % 10 == 0 favored)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item still fits: reward proportional to harmonic class of next fit
            let nq = (next_item_size * 4) / bin_capacity;
            score -= (4.0 - nq as f64) * 2.0;
        } else {
            // next item won't fit here: penalize leaving tight-but-unusable space
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 10.0; // dead space just below next item
            }
        }
    } else {
        // last item: maximize packing tightness
        score -= 5.0;
    }

    // Stream progression: early on, prefer opening new bins less; late, fill aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 3.0 * (mean_residual / bin_capacity as f64);

    // Penalize bins far below mean residual (fragmenting), reward near-mean consolidation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: neutral-ish baseline, mildly penalized so real bins win unless fit is bad.
    if bin_residual == bin_capacity {
        score += 14.0 - 10.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins,
    // disfavor opening new ones.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 3.0;

    // New-bin candidate: only attractive when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    // Lookahead: if next item can fit into the post residual, reward leaving this space.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space that next item cannot use
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead match.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap <= 5 {
            score -= (6 - gap) as f64 * 4.0;
        } else if post_residual < next_item_size {
            // Next item cannot use this residual: dead space penalty grows
            // the smaller the leftover relative to next item.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Reward tight fills relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 20.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Early in the stream, prefer consolidating into few bins; later, allow
    // more freedom to open bins for better fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only when many bins are open late,
        // or when the current item is large and fits would be poor.
        let size_pressure = item_size as f64 / bin_capacity as f64;
        score += 35.0 - progress * 20.0 - size_pressure * 15.0;
    }

    // Slight preference for bins with less residual overall (best-fit bias).
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = (bin_residual - item_size.min(bin_residual)) as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powi(3);

    // Penalize leaving dead space that no typical item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / bin_capacity as f64;
        score += 60.0 - 50.0 * (1.0 - crowded) - 20.0 * progress;
        if post_residual < item_size { score += 100.0; }
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Mild preference for using existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64).ln().max(0.0);

    // Penalize very large post-residuals that waste capacity.
    if post_residual > bin_capacity / 2 {
        score += 0.15 * (post_residual - bin_capacity / 2) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Tight fits rewarded: quadratic penalty on wasted space
    let tightness = 1.0 - (pr / cap);
    score -= 30.0 * tightness * tightness;

    // Non-linear coupling: post_residual interacts with stream progress
    // Early on, prefer filling bins loosely; later, demand tight fits
    let progress_coupling = pr * (0.5 + 0.5 * progress) / cap;
    score += 10.0 * progress_coupling * progress_coupling * progress;

    // Perfect fit bonus (smooth, non-piecewise)
    if pr == 0.0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = pr - next_item_size as f64;
        score -= 12.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty proportional to leftover
        score += 6.0 * (pr / cap);
    }

    // Penalize opening new bins when many bins are open with usable residual
    if bin_residual == bin_capacity {
        score += 25.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // New bin more attractive late in stream if mean residual is low
        score -= 10.0 * (1.0 - mean_residual / cap).max(0.0) * progress;
    }

    // Mild preference for bins below mean residual (balance residuals)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 4.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse when it cannot
    // host typical small items. Class by modulo on capacity fractions.
    let class = post_residual % 10;
    // Residuals in {1..9} are nearly dead; penalize progressively.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 2.0 * class as f64;
    }
    // Residuals divisible by 10 are "harmonic" — reusable by decile-sized items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; penalize wasted residual proportionally
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 25.0 * waste;
            // Harmonic threshold: residual above half capacity is still flexible
            if post_residual > bin_capacity / 2 {
                score -= 20.0;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive if item is huge relative
    // to capacity or all existing fits would be poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Opening fresh is good for large items (leaves harmonic residual 100-item)
        let new_res = bin_capacity - item_size;
        if new_res % 10 == 0 {
            score -= 30.0;
        }
        if fill_ratio > 0.7 {
            score -= 60.0;
        } else {
            // prefer existing bins for small items
            score += 50.0 * (1.0 - fill_ratio);
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (consolidation)
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Tie-break: prefer fewer open bins overall
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead space penalty grows steeply as gap becomes small (< 10 unusable).
        if gap < 10.0 {
            score += 60.0 * (1.0 - gap / 10.0);
        } else if gap < 20.0 {
            score += 12.0 * (1.0 - (gap - 10.0) / 10.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight packing: fill ratio of the item into the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill;

    // Open-bin pressure: discourage spreading across many bins unless beneficial.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item is large or fits poorly.
    if bin_residual == bin_capacity {
        // Mild penalty so open bins are preferred by default.
        score += 8.0;
        // But large items relative to capacity make a fresh bin reasonable.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If mean residual across open bins can't fit future items well, new bin ok.
        if mean_residual < item_size as f64 {
            score -= 5.0;
        }
    }

    // Lookahead: if next item would fit the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u64) > (post_residual as u64) {
        // Post residual too small for next item: dead space for the future.
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (sets up a perfect follow-up fit).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if diff == 0.0 {
            score -= 400.0;
        } else if post >= next {
            score -= 150.0 * (1.0 - diff / 100.0);
        } else {
            // Next item won't fit here: penalize wasted lookahead potential.
            score += 0.5 * (next - post);
        }

        // Two-item chain: can this bin absorb both item and next item?
        if item_size + next_item_size <= bin_residual {
            score -= 60.0;
        }
    }

    // Penalize tiny dead space that no small item (min size 1) can use well
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Relative-to-mean coupling: bins tighter than average are more precious;
    // prefer dumping items into loose (large-residual) bins.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Late in the stream: consolidate aggressively, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, expensive late.
        score += 300.0 * progress;
    } else {
        score -= 50.0 * progress;
    }

    // Prefer filling bins that are already heavily loaded (low residual).
    score += 0.2 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for small post-residual (tight fit).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that no future item (min size 1..10 typical) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: empty bin is attractive only when fits are plentiful
    // or the current fit is bad; otherwise discourage spreading items out.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base penalty: reusing bins is generally better.
        score += 30.0;
        // If many bins can fit, prefer consolidating into existing ones.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If no open bin fits well (this call happens alongside fitting bins),
        // opening a fresh bin is fine; soften penalty when item is large.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // Late in the stream, avoid leaving many partially filled bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.7 {
            score += 15.0 * progress;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, favor this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // Next item cannot use leftover; penalize proportionally.
            score += 8.0 * (next_item_size - post_residual) as f64 / (bin_capacity as f64);
        }
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (fill the emptier bins less, keep large residuals flexible) — but only
    // when multiple bins are open.
    if open_bins_count > 1 && !is_new_bin {
        let diff = (bin_residual as f64) - mean_residual;
        score += 0.05 * diff;
    }

    // Mild time-horizon exploration: early on, encourage diverse bin states.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear sharpening over time
    let mut score = pr * (1.0 + 1.5 * progress * norm_pr);

    // Smooth polynomial coupling: tight fits (small post_residual) rewarded more as stream progresses
    score -= progress * (1.0 - norm_pr) * (1.0 - norm_pr) * 20.0;

    // Penalize dead space that cannot fit the next item (smooth quadratic mismatch)
    let mismatch = if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        gap * gap
    } else {
        0.0
    };
    score += mismatch * 15.0 * (1.0 - progress);

    // Reward exact-ish fits for the lookahead item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= fit_quality * fit_quality * 10.0;
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when bin is far below mean residual (keeps residuals balanced)
    score += ((pr - mean_residual) / cap).abs() * 5.0;

    // Discourage opening new bins late in the stream
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 + 30.0 * progress + open_bins_count as f64 * 0.5;
    }

    // Slight penalty for wasting large items in large-residual bins
    score -= norm_item * (1.0 - norm_pr) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (waste minimization).
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.05;

    // Penalize unusable dead space: if post_residual can't hold even the
    // smallest plausible item, it is dead weight.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 15 {
        score += 5.0;
    }

    // Harmonic class: post_residual mod 10 — small remainders of the
    // decade class are nearly dead space; reward residuals that are
    // "clean" multiples of common item classes.
    let pr_mod = post_residual % 10;
    if pr_mod == 0 {
        score -= 4.0;
    } else if pr_mod >= 8 {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly (or very well) into the
    // post residual, this bin is doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_leftover = post_residual - next_item_size;
        if next_leftover == 0 {
            score -= 20.0;
        } else if next_leftover < 10 {
            score -= 8.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual too small for the lookahead item: mild penalty,
        // stronger the more it falls short.
        let shortfall = (next_item_size - post_residual) as f64;
        score += shortfall * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // fit elsewhere is poor. Penalize the empty candidate so tight fits
    // in existing bins win, but relax the penalty late in the stream or
    // when open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 18.0;
        if mean_residual < 25.0 {
            new_bin_penalty -= 8.0; // fragmented state: fresh bin is attractive
        }
        if progress > 0.8 {
            new_bin_penalty -= 4.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild preference for filling bins with larger residuals when many
    // bins are open (consolidation pressure).
    if open_bins_count > 4 {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small non-zero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward bins whose residual tightly matches the item (low waste ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure from many open bins: discourage spreading into new bins.
    score += 0.5 * open_bins_count as f64;

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 90.0 + 2.0 * open_bins_count as f64;
        score += base_penalty;
        // If the next item could pair with the leftover, opening a fresh bin is less bad.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    } else {
        // Prefer bins whose residual is close to the stream's mean residual (keep balance).
        score += 0.2 * ((bin_residual as f64 - mean_residual).abs());
    }

    // Lookahead: if leftover exactly fits the next item, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 15.0; // leftover likely dead space for the next item
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that tightly match the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as u32 - next_item_size) as f64;
        score -= 150.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to the gap.
        let gap = (next_item_size - post_residual as u32) as f64;
        score += 40.0 + 0.5 * gap;
    }

    // Penalize creating small unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Compare against mean residual: prefer using bins with more space than average
    // when the fit is loose, but prefer tight bins when fit is tight.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * ((mean_residual - post_residual as f64) / cap);

    // Last-chance bin: strongly favor filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open with usable residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 250.0 + 100.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
        // But if the item is huge and no open bin is tight, opening may be fine.
        if item_size as f64 > 0.8 * cap {
            score -= 150.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * (item_size as f64);

    // Penalize large dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0; // awkward zone
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here; slight penalty for wasting space
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Encourage closing out nearly-full bins over fragmenting fresh ones.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 10.0;
    } else if fill_ratio < 0.4 {
        score += 5.0;
    }

    // Global state: many open bins with high mean residual -> prefer using existing bins.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score -= 4.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // is large relative to remaining residuals or few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (fitting_bins_count as f64).max(1.0);
        let waste = (bin_capacity - item_size) as f64;
        // Penalize new bin unless item is huge or fitting options scarce.
        score += 12.0 + waste * 0.25 - (80.0 - item_size as f64).max(0.0) * 0.15
                 - 18.0 / pressure
                 - 5.0 * progress * (open_bins_count as f64 / 10.0).min(1.0);
        // If next item also fits in a fresh bin alongside, ease penalty.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 6.0;
        }
    }

    // Mild time-horizon term: early in stream, be conservative with new space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with polynomial sharpening
    let mut score = pr * (1.0 + 2.5 * norm_pr * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // early on, waste matters less; late, penalize residual quadratically
    score += pr * (0.8 * progress + 2.2 * progress * progress);

    // Interaction: post_residual vs mean residual — avoid leaving bins
    // whose residual deviates strongly from fleet mean (dead-space control)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 3.0 * dev.abs() * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual (chain packing)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (pr - nxt) / cap) * (1.0 - progress * 0.5);
        } else {
            // next item won't fit here: mild penalty scaled by overshoot
            score += 2.0 * ((nxt - pr) / cap).min(1.0);
        }
    }

    // Slight preference for using existing bins over opening new ones,
    // diminishing as stream progresses (early exploration of new bins ok)
    score += 1.5 * (1.0 - progress) * (open_bins_count as f64).sqrt();

    // New-bin candidate: make it attractive only when current bin would
    // leave a very awkward residual relative to typical item scale
    if bin_residual == bin_capacity {
        let awkward = (pr / 50.0).min(1.0); // pr == cap here, so neutral
        score -= 4.0 * (1.0 - awkward);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "clean"
    // fractions of capacity (0, C/4, C/2, 3C/4) since they are re-usable.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 60.0; // perfect fit is always excellent
    } else if post_residual == half {
        score -= 25.0;
    } else if post_residual == quarter || post_residual == 3 * quarter {
        score -= 15.0;
    }

    // Dead space penalty: small residuals (< 10) are unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo-class coupling: if next item exactly matches post_residual,
    // strongly favor this bin (guaranteed future perfect fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual % next_item_size == 0 {
            score -= 18.0; // next item can tile the residual exactly
        }
    }
    // Penalize when next item can never use this residual class again.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, scaled by how tight the fit is.
    if fitting_bins_count == 1 {
        score -= 30.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Prefer filling bins whose residual is far below the mean (tight bins),
    // gently encouraging consolidation.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Integer-division threshold: bins whose residual class (residual / 10)
    // matches the item's class (item / 10) fit harmonically.
    if (post_residual / 10) == (item_size / 10) && post_residual > 0 {
        score -= 8.0;
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Reward placements leaving gaps usable for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // dead space relative to the next item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; keep scores tight.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    score += 0.15 * pressure;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 12.0 + 2.0 * open_bins_count as f64 };
        score += desperation;
        // Late in the stream, discourage opening new bins with tiny dead space left.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // next item fits; penalize leftover waste after the hypothetical second placement
            let second_left = post_residual - next_item_size;
            score += second_left as f64 * 0.6;
            score -= 12.0; // small bonus for being chainable
        } else {
            // next item cannot follow into this bin; dead space risk grows
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
        // last item: prefer tightest fit only
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins tighter than average are valuable, keep them tight
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Penalize large post_residual relative to capacity (unusable dead space)
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 20.0; // near-perfect fill
    } else if pr > bin_capacity as f64 * 0.5 {
        score += 10.0; // leaving bin more than half empty is wasteful when item fits
    }

    // Last-chance bin before opening a new one: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless everything else is bad.
    // Base penalty for opening a new bin, relaxed early in the stream and when
    // no good chain is possible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 45.0;
        // early stream: opening bins is cheaper (future items unknown)
        penalty -= progress * 15.0;
        // if many bins already open, discourage fragmentation
        penalty += open_bins_count as f64 * 1.5;
        // if next item is large, a fresh bin may be genuinely useful
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            penalty -= 18.0;
        }
        score += penalty.max(5.0);
    }

    // Slight preference for tighter bins overall
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Penalize exact-fill waste potential: prefer leaving space usable by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space below minimum item size
    }

    // Lookahead: if next item fits into post_residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // extra reward for chaining multiple plausible fits
        if post_residual >= next_item_size + 10 {
            score -= 10.0;
        }
    }
    // If next item would NOT fit here, mild penalty so bins that chain get priority.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (penalize cramming);
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 15.0;

    // Global state coupling: many open bins with high mean residual -> prefer consolidating here.
    if open_bins_count > 2 && (mean_residual > (bin_capacity as f64) * 0.5) {
        score -= 10.0;
    }
    // Few open bins / low mean residual: slight penalty to avoid fragmentation.
    if mean_residual < 20.0 {
        score += 12.0;
    }

    // New-bin candidate: empty bin gets a moderate default so it wins only when fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // open new bin early or when no tight option exists is handled by base score
        if progress < 0.3 {
            score -= 10.0;
        }
    }

    // Prefer filling bins that are already partially used (reduce bin count).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * 12.0;

    // Nonlinear coupling: large items should seek large residuals.
    if item_size > 60 && bin_residual >= item_size {
        score -= (item_size as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post residual with stream progress
    score -= 18.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 + progress);
    score += 10.0 * norm_post * norm_post * norm_post * (0.5 + progress);
    // reward tight fits more strongly as stream advances
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);
    // penalize dead space relative to mean residual state
    score += 6.0 * (norm_post - mean_residual / cap).abs() * (1.0 + progress);
    // lookahead: reward leaving room for the next item smoothly
    let nxt = next_item_size as f64 / cap;
    if nxt > 0.0 {
        let gap = (norm_post - nxt).abs();
        score -= 8.0 * (1.0 - gap.min(1.0)) * (1.0 - progress);
        score += 5.0 * gap * gap;
    }
    // scarcity pressure: last fitting bin gets smooth bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_post) * (1.0 + progress);
    }
    // mild congestion term
    score += 0.4 * (open_bins_count as f64).ln() * (1.0 + norm_post);
    // new-bin candidate: keep it neutral-to-slightly-high unless item is large
    if bin_residual == bin_capacity {
        score += 4.0 - 6.0 * norm_item * (1.0 + progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small leftover" classes (likely dead space) are penalized when used,
    // rewarded when the leftover is large enough to host future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries via integer division thresholds on post_residual.
    let class = post_residual / 10; // 0..=10 harmonic classes
    match class {
        0 => score += 25.0,            // tiny dead space (0-9)
        1 => score += 18.0,            // 10-19
        2 => score += 10.0,            // 20-29
        3 => score += 4.0,             // 30-39
        4 => score -= 2.0,             // 40-49 usable
        5 => score -= 5.0,             // 50-59
        6 => score -= 4.0,             // 60-69
        7 => score -= 1.0,             // 70-79
        8 => score += 3.0,             // 80-89 mostly fresh
        _ => {}                        // 90+: near-empty bin
    }

    // Modulo coupling: leftover that is congruent to a common small item size
    // is more reusable. Reward post_residual divisible by common sizes.
    if post_residual > 0 {
        let mut reuse = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                reuse += 3.0;
            }
        }
        score -= reuse;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 8.0; // near-perfect two-item chaining
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover too small for next item -> dead space risk
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current open bins
    // are fragmented or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 0 {
            score += 45.0 - 20.0 * progress;
            if item_size >= 60 {
                score -= 20.0; // big items deserve fresh bins
            }
            if mean_residual < item_size as f64 {
                score -= 25.0; // nothing usable open anyway
            }
            if fragmentation > 30.0 {
                score -= 5.0;
            }
        } else {
            score -= 100.0; // must open first bin
        }
    }

    // Mild preference for tighter bins overall.
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are too small to hold
    // any plausible future item (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Moderate dead space (10..=19) is risky too: only very small items fit.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward bins whose residual closely matches the lookahead item (k=2).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual >= next_item_size {
            // Lookahead fits exactly or nearly: reward.
            score -= (20.0 - gap.min(20) as f64) * 2.0;
        } else {
            // Lookahead cannot fit here: mild penalty proportional to gap.
            score += gap as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // Candidate new bin: baseline cost plus pressure from open bins.
        score += 120.0 + open_bins_count as f64 * 10.0 * (0.5 + progress);
    } else {
        // Mild bonus for using existing bins when mean residual is high.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

