        }
        // Next item cannot fit here anymore: mild penalty for wasting the slot
        if next_item_size > post_residual {
            score += 8.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 10.0;
    }

    // Prefer bins whose residual is already small relative to mean (compact bins first)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 30.0 * fill_ratio;
    }

    // Penalize creating tiny dead space (< 10) that likely becomes unusable
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - post / cap;
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Perfect closure bonus: bin becomes exactly full.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item can still fit in the post-residual,
    // this placement keeps a useful bin alive.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Post-residual is dead space for the next item: penalize proportionally.
            score += 0.35 * post;
        }
        // Chain fit: next item exactly fills what remains — excellent.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 + 10.0 * progress;
    }

    // Penalize scattering into many open bins when mean residual is high
    // (bins are already fragmented; prefer consolidating into tightest fits).
    if open_bins_count > 2 {
        score += 0.05 * (open_bins_count as f64) * (mean_residual / cap);
    }

    // New-bin candidate handling: make an empty bin attractive only when the
    // item is large relative to typical residuals or fits are scarce.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / cap;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        // Baseline: opening a new bin is moderately costly.
        score = 0.45 * cap + 20.0 * large_item * scarcity;
        // Late in the stream, opening new bins is cheap (little to consolidate).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress * large_item;
        // But if an open bin fits perfectly, never open a new one.
        if post_residual == 0 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits via non-linear polynomial of normalized post residual.
    let mut score = 2.0 * norm_post * norm_post + 0.5 * norm_post;

    // Smooth coupling: as the stream progresses, dead space becomes more costly.
    score += 1.5 * progress * norm_post * norm_post;

    // Interaction between item size and post residual: penalize leaving large
    // residuals when the current item is large (large items fragment bins).
    score += 0.8 * norm_item * norm_post;

    // Mean-residual coupling: if open bins already have slack on average,
    // penalize adding another slack-heavy placement (smooth quadratic term).
    let norm_mean = mean_residual / cap;
    score += 0.6 * norm_mean * norm_post;

    // Lookahead: reward bins whose post residual can host the next item,
    // with a smooth bell-shaped reward when next size is near post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = nxt - norm_post;
        let bell = (-6.0 * gap * gap).exp();
        score -= 1.2 * bell;
        // Penalize post residuals slightly too small for the lookahead item.
        score += 0.5 * (norm_post - nxt).max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Mild penalty for proliferation of open bins as stream advances (smooth).
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10 buckets.
    // Leftovers in "awkward" classes (1..9 mod 10 that few item sizes hit) are dead space.
    let pr = post_residual;
    let class = if pr == 0 { 0 } else { (pr % 10) as f64 };
    score += class * 0.8; // penalize non-zero modulo classes slightly

    // Perfect fit: zero post-residual is the ideal harmonic class.
    if pr == 0 {
        score -= 40.0;
    }

    // Exact pairing: leftover after this item exactly equals the lookahead item.
    if next_item_size > 0 && pr == next_item_size {
        score -= 25.0;
    }
    // Leftover can host the next item with room to spare (chainable fit).
    if next_item_size > 0 && pr >= next_item_size {
        let slack = (pr - next_item_size) as f64;
        score -= 6.0 + slack * 0.05;
    } else if next_item_size > 0 {
        // Next item won't fit here: leftover risks becoming dead space.
        let wasted = (pr as f64 / cap).powi(2);
        score += 10.0 + 30.0 * wasted;
    }

    // Integer-division thresholds on post_residual: large leftovers are reusable.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr >= half {
        score -= 8.0;
    } else if pr >= quarter {
        score += 2.0;
    } else if pr > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize unless current bin would leave bad residue.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening fresh bins early is cheap; late in the stream prefer consolidation.
        score = cap - 12.0 * (1.0 - progress) + 12.0 * progress;
        if fitting_bins_count <= 1 {
            // No good alternative exists; a new bin is legitimate.
            score -= 14.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && next_item_size + item_size <= bin_capacity {
            // Pairing potential in a fresh bin.
            score -= 4.0;
        }
    }

    // Mild pressure toward bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight bias to fill fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (cap - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

