    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = (item_size as f64 / bin_capacity as f64).powi(2) * 50.0;
        score += 45.0 - large_item - (1.0 - progress) * 20.0;
