    // when the item is large or few bins fit it.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        score = 45.0 - pressure * 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (next_item_size as f64 / bin_capacity as f64) * 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    }

    // Penalize leaving tiny unusable slivers (< 10 dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) super-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // small slivers are nearly worthless; prefer filling exactly
    }

    // Lookahead synergy: bonus if next item fits in the post residual.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 15.0;
        } else {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when mean residual is large.
    score += 0.05 * open_bins_count as f64 + 0.1 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate handling: opening a bin is penalized, but more
    // acceptable early in the stream or when current bins are crowded.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        if mean_residual < 20.0 { score -= 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear tightening late in stream
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr);

    // Dead-space penalty: quadratic in tiny residuals (unusable space)
    let dead = if pr > 0.0 { (1.0 - norm_pr).max(0.0) } else { 0.0 };
    score += 0.5 * norm_pr * norm_pr * (1.0 + progress);

    // Reward when post-residual exactly fits the lookahead item (smooth coupling)
    let fit_next = if next_item_size > 0 && pr >= next_item_size {
        let r = (pr - next_item_size as f64) / cap;
        -1.5 * (1.0 - r) * (1.0 - r) * (1.0 + progress)
    } else if next_item_size > 0 && bin_residual >= next_item_size && pr < next_item_size {
        // placing here destroys room for next item: penalize smoothly
        0.8 * norm_item * (1.0 + progress)
    } else {
        0.0
    };
    score += fit_next;

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 + progress);
    }

    // Slight penalty for spreading across many open bins relative to mean residual
    score += 0.1 * ((open_bins_count as f64).ln() + 1.0) * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate: neutral-ish baseline, penalized early, relaxed late
    if bin_residual == bin_capacity {
        score = 0.6 + 0.5 * progress - 0.3 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: prefer residuals that are "useful" sizes.
    // Class A: post_residual <= 10 (near-perfect fill) -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 45.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 12.0;
    }

    // Dead-space penalty: residuals in (30, 50) are awkward (too big to waste,
    // too small for typical items) -> penalize via fractional capacity coupling.
    let post_frac = post_residual as f64 / cap;
    if post_frac > 0.3 && post_frac < 0.5 {
        score += 15.0 * (post_frac - 0.3);
    }

    // Modulo structure: residuals that are multiples of 10 align with the
    // item-size lattice, making future fills easier.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here: mild penalty proportional to leftover.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless all open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if the current item is large and would leave a harmonic residual,
        // opening fresh is fine.
        if item_size >= 50 {
            score -= 10.0;
        }
        // As stream progresses, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If many open bins already, discourage adding more.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild tie-break toward bins tighter than the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would leave this bin stranded, penalize slightly
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Stream progression: early on, be more willing to open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Prefer bins with residual above the mean (keeps balance)
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits (post_residual == 0) heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item (perfect chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as u32 == next_item_size {
            score -= 500.0; // exact 2-step chain
        } else if (post_residual as u32) > next_item_size {
            // next item can also fit here: mild reward proportional to closeness
            score -= (20.0 * (1.0 - diff / (bin_capacity as f64))).max(0.0);
        } else {
            // next item won't fit: penalize dead space relative to gap
            score += 0.5 * diff;
        }
    }

    // Penalize creating tiny unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Slight preference for consolidating into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // New-bin candidate: make empty bins mildly unattractive unless
    // residuals of open bins are very poor (handled by above bonuses).
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins that end with small post_residual,
    // with a quadratic penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead: penalize placements that leave post_residual too small for
    // the next item (dead space), reward if next item could use the leftover.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt && post_residual > 0 {
            // leftover is dead space for the next item
            score += (nxt - post_residual as f64) * 0.35;
        } else if post_residual as u32 >= next_item_size {
            score -= 2.5;
        }
        // reward leaving exactly a near-perfect slot for the next item
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 3.0 / (1.0 + gap);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
        if post_residual as f64 <= 0.15 * bin_capacity as f64 {
            score -= 4.0;
        }
    }

    // New-bin candidate: make it attractive only when open bins have poor fits.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; beats existing bins only if their
        // post_residual would be large / wasteful.
        score = bin_capacity as f64 * 0.62
            - (open_bins_count as f64) * 0.15
            - mean_residual * 0.25
            + (fitting_bins_count as f64) * 2.2;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 1.0; // slight penalty: existing bins may chain better
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 2.0; // later in stream, prefer consolidation
        return score;
    }

    // Global state coupling: many open bins with high mean residual ->
    // encourage filling existing bins (avoid fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= mean_residual * 0.05 * (1.0 + progress);
    score -= (open_bins_count as f64) * 0.08;

    // Perfect fit jackpot.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let prn = pr / cap;
    let tight = 1.0 - (1.0 - prn) * (1.0 - prn); // small prn -> ~1 (good fit)
    score -= tight * (1.0 + prog) * 30.0;
    // Quadratic penalty on large dead space, amplified by progress
    score += prn * prn * (10.0 + 40.0 * prog);

    // Lookahead: reward if next item can use the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fill = (next_item_size as f64) / pr.max(1.0);
        score -= 15.0 * fill * (1.0 - prog * 0.5);
    } else if next_item_size > 0 {
        score += 5.0 * prog;
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Crowd penalty relative to mean residual
    score += (mean_residual - pr) * 0.15;

    // New-bin candidate: mildly penalize early, allow late when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 { (mean_residual / cap).min(1.0) } else { 0.0 };
        score += 25.0 * (1.0 - prog) - 15.0 * prog * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by small classes are "reusable".
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // class of residual: exact small remainders are valuable dead space
        let class = if pr <= 10 { 0.0 }
                    else if pr <= 20 { 1.0 }
                    else if pr <= 50 { 2.0 }
                    else { 3.0 };
        score += class * 8.0;

        // modulo arithmetic: residuals that are multiples of common item sizes are reusable
        if pr % 10 == 0 { score -= 10.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 5 == 0 { score -= 3.0; }

        // residual large enough to host typical next item
        if next_item_size > 0 {
            if pr >= next_item_size {
                score -= 12.0;
                // exact divisibility of residual by next item is a harmonic bonus
                if pr % next_item_size == 0 { score -= 15.0; }
            } else {
                score += 6.0;
            }
            // lookahead: next item fits in the new post_residual too
            if post_residual >= next_item_size && post_residual - next_item_size >= 0 {
                let second = post_residual - next_item_size;
                if second % 10 == 0 { score -= 5.0; }
            }
        }
    }

    // last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // penalty for wasting a nearly-empty bin's potential on a tiny item
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness < 0.3 { score += 10.0 * (0.3 - tightness); }

    // new-bin candidate: keep it attractive only when current bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 5.0 * crowd * (0.5 + 0.5 * progress) + mean_residual * 0.3;
    }

    // mild pressure toward filling bins as stream progresses
    score -= 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 30.0;
        } else if post_residual < 35 {
            score += 12.0;
        }
    } else {
        score -= 40.0; // perfect closure is excellent
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item is large relative to the mean residual.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / mean_residual.max(1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0
            - 30.0 * (tightness - 1.0).clamp(0.0, 2.0)
            - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    // Lookahead: if the next item would fit exactly in the post residual,
    // this placement chains nicely.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            // reward proportional to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 400.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit: penalize dead space relative to next item
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
    }

    // Penalize small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 20.0;
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Prefer bins with residual below mean (tighter packing)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for fewer open bins early
    score += open_bins_count as f64 * 0.05;

    score
}
